from pathlib import Path
import traceback, logging, datetime


# Configuración SSL solicitada para uso en red corporativa.
# PRECAUCIÓN: verify=False desactiva la comprobación del certificado del servidor.
# Para volver a la verificación segura, cambiar TLS_VERIFY a True.
TLS_VERIFY = False
TLS_NO_VERIFY_HOSTS = (
    'api-infotecnica.coordinador.cl',
    'activos-tx-prod.appspot.com',
    'server.arcgisonline.com',
)

def configure_tls_warnings():
    """Silencia solo advertencias repetitivas de los tres hosts permitidos."""
    import re as _re
    import warnings
    try:
        from urllib3.exceptions import InsecureRequestWarning
    except ImportError:
        return
    if not TLS_VERIFY:
        for host in TLS_NO_VERIFY_HOSTS:
            warnings.filterwarnings(
                'ignore',
                message=r"Unverified HTTPS request is being made to host '" + _re.escape(host) + r"'.*",
                category=InsecureRequestWarning,
            )

def configure_esri_tile_requests():
    """Aplica verify=False solo a las teselas Esri de TkinterMapView.

    TkinterMapView usa requests.get directamente; se inyecta un proxy SOLO
    en su módulo de mapas, sin modificar globalmente requests.get.
    """
    try:
        import requests as _requests
        import tkintermapview.map_widget as map_widget
        from types import SimpleNamespace
        from urllib.parse import urlsplit
    except ImportError:
        return False

    def tile_get(url, *args, **kwargs):
        hostname = (urlsplit(str(url)).hostname or '').lower()
        if hostname == 'server.arcgisonline.com':
            kwargs['verify'] = TLS_VERIFY
        return _requests.get(url, *args, **kwargs)

    # Las excepciones siguen siendo las originales de requests, necesarias
    # para los manejadores except requests.exceptions.ConnectionError del visor.
    map_widget.requests = SimpleNamespace(get=tile_get, exceptions=_requests.exceptions)
    return True

# Sesiones públicas separadas por servicio. Sin credenciales ni encabezados Authorization.
class ScopedApiSession:
    def __init__(self):
        import requests
        self.bdit = requests.Session()
        self.bdatx = requests.Session()
        # Sólo estos dos clientes API aplican la política SSL solicitada.
        self.bdit.verify = TLS_VERIFY
        self.bdatx.verify = TLS_VERIFY
        # Interfaz compatible con requests.Session, usada por load_data().
        self.headers = {"Accept": "application/json"}
    def get(self, url, **kwargs):
        headers = dict(self.headers)
        headers.update(kwargs.pop("headers", {}) or {})
        kwargs["headers"] = headers
        kwargs['verify'] = TLS_VERIFY
        from urllib.parse import urlsplit
        host = (urlsplit(str(url)).hostname or '').lower()
        if host == 'api-infotecnica.coordinador.cl':
            return self.bdit.get(url, **kwargs)
        if host == 'activos-tx-prod.appspot.com':
            return self.bdatx.get(url, **kwargs)
        raise RuntimeError('Dominio API no autorizado: ' + host)

def create_scoped_api_session():
    return ScopedApiSession()

# Al convertir a EXE, conservar DOCUMENTOS_BDIT junto al ejecutable,
# nunca dentro de _internal o carpetas temporales de PyInstaller.
BASE = (Path(sys.executable).resolve().parent
        if getattr(sys, "frozen", False)
        else Path(__file__).resolve().parent)
# Dependencias comprobadas ANTES de registrar los módulos embebidos.
# "Esri" es un servicio cartográfico; para verlo en Tkinter se instalan
# tkintermapview y Pillow. Los mapas base requieren acceso a Internet.
CORE_DEPS = (
    ('requests', 'requests', 'Consultas HTTP BDIT/BDATx'),
    ('openpyxl', 'openpyxl', 'Excel y anexos LDE'),
    ('pyproj', 'pyproj', 'Coordenadas UTM/WGS84'),
    ('numpy', 'numpy', 'Cálculos numéricos'),
    ('matplotlib', 'matplotlib', 'Mapa de análisis'),
    ('rarfile', 'rarfile', 'Inspección de archivos RAR'),
)
OPTIONAL_DEPS = (
    ('tkintermapview', 'tkintermapview', 'Mapa Esri integrado'),
    ('PIL', 'Pillow', 'Marcadores e imágenes del mapa Esri'),
    ('docx', 'python-docx', 'Lectura de documentos Word'),
    ('pypdf', 'pypdf', 'Lectura de documentos PDF'),
)

def get_missing_dependencies(dependencies):
    """Identifica faltantes sin importar módulos que pueden tener efectos laterales."""
    result = []
    for module, package, description in dependencies:
        try:
            found = importlib.util.find_spec(module) is not None
        except (ImportError, ValueError, AttributeError):
            found = False
        if not found:
            result.append((module, package, description))
    return result


def _show_dependency_message(title, body, kind='info', parent=None):
    root = parent
    own_root = root is None
    if own_root:
        root = tk.Tk()
        root.withdraw()
    try:
        if kind == 'error':
            messagebox.showerror(title, body, parent=root)
        elif kind == 'warning':
            messagebox.showwarning(title, body, parent=root)
        else:
            messagebox.showinfo(title, body, parent=root)
    finally:
        if own_root:
            root.destroy()


def _prompt_install(dependencies, required, parent=None):
    if not dependencies:
        return True
    packages = [dep[1] for dep in dependencies]
    label = ('Necesarias para iniciar GeoLínea Tx:' if required else
             'Complementos disponibles para ampliar GeoLínea Tx:')
    details = '\n'.join('• %s — %s' % (pkg, description)
                        for _, pkg, description in dependencies)
    title = 'Bibliotecas necesarias' if required else 'Mapa Esri y formatos adicionales'
    body = (label + '\n\n' + details +
            '\n\n¿Deseas descargar e instalar estas bibliotecas ahora?'
            '\nSe requiere Internet y autorización para instalar paquetes.'
            '\n\n' + ('Si eliges No, el programa no se abrirá.' if required
                       else 'Si eliges No, el programa continuará sin esas funciones.'))
    root = parent
    own_root = root is None
    if own_root:
        root = tk.Tk(); root.withdraw()
    try:
        return messagebox.askyesno(title, body, parent=root)
    finally:
        if own_root:
            root.destroy()


def _install_packages(packages, parent=None):
    """Pip en un hilo para que la ventana de instalación no se congele."""
    import threading
    from queue import Queue, Empty
    packages = list(dict.fromkeys(packages))  # paquetes predefinidos, sin entradas externas
    own_root = parent is None
    root = parent if parent is not None else tk.Tk()
    if own_root:
        root.withdraw()
    dialog = tk.Toplevel(root)
    dialog.title('Preparando GeoLínea Tx')
    dialog.resizable(False, False)
    dialog.transient(root)
    dialog.protocol('WM_DELETE_WINDOW', lambda: None)
    ttk.Label(dialog, text='Instalando bibliotecas autorizadas…',
              font=('Segoe UI', 11, 'bold')).pack(padx=24, pady=(20, 5))
    ttk.Label(dialog, text=', '.join(packages), wraplength=490,
              justify='center').pack(padx=24, pady=5)
    bar = ttk.Progressbar(dialog, mode='indeterminate', length=450)
    bar.pack(padx=24, pady=(10, 18))
    bar.start(12)
    dialog.update_idletasks()
    dialog.grab_set()
    queue = Queue()

    def worker():
        cmd = [sys.executable, '-m', 'pip', 'install', '--disable-pip-version-check',
               '--no-input']
        # En venv no se permite --user; fuera de venv evita instalaciones globales.
        if sys.prefix == getattr(sys, 'base_prefix', sys.prefix):
            cmd.append('--user')
        cmd.extend(packages)
        try:
            completed = subprocess.run(cmd, text=True, capture_output=True,
                                       timeout=900, check=False)
            if completed.returncode:
                raise RuntimeError((completed.stderr or completed.stdout)[-2200:] or
                                   'pip terminó con código %s' % completed.returncode)
            queue.put((True, ''))
        except Exception as exc:
            queue.put((False, str(exc)))

    threading.Thread(target=worker, daemon=True, name='geolineatx-pip').start()
    result = {'ok': False, 'error': ''}

    def poll():
        try:
            result['ok'], result['error'] = queue.get_nowait()
        except Empty:
            if dialog.winfo_exists():
                dialog.after(125, poll)
            return
        dialog.destroy()

    dialog.after(125, poll)
    root.wait_window(dialog)
    if own_root:
        root.destroy()
    importlib.invalidate_caches()
    return result['ok'], result['error']


def check_dependencies(parent=None, interactive=True):
    """El .py puede instalar paquetes tras autorización; el .exe nunca ejecuta pip."""
    required = get_missing_dependencies(CORE_DEPS)
    optional = get_missing_dependencies(OPTIONAL_DEPS)
    is_exe = getattr(sys, 'frozen', False)

    if is_exe:
        if required:
            _show_dependency_message('Ejecutable incompleto',
                 'Este ejecutable no incluye bibliotecas obligatorias:\n\n' +
                 '\n'.join('• '+x[1] for x in required) +
                 '\n\nSolicita una nueva compilación al responsable del programa. '
                 'Un EXE no debe instalar paquetes con pip.', 'error', parent)
            return False
        if optional and interactive:
            _show_dependency_message('Funciones opcionales no incluidas',
                 'Esta versión no incluye:\n\n' +
                 '\n'.join('• '+x[1]+' ('+x[2]+')' for x in optional) +
                 '\n\nPodrás continuar sin esas funciones. Para habilitarlas, '
                 'es necesario generar un nuevo EXE que las incluya.', 'warning', parent)
        return True

    if required:
        if not interactive or not _prompt_install(required, True, parent):
            return False
        success, error = _install_packages([x[1] for x in required], parent)
        if not success:
            _show_dependency_message('No se pudo instalar',
                 error + '\n\nInstalación manual:\npython -m pip install ' +
                 ' '.join(x[1] for x in required), 'error', parent)
            return False
        required = get_missing_dependencies(CORE_DEPS)
        if required:
            _show_dependency_message('Instalación incompleta',
                'Aún faltan: ' + ', '.join(x[1] for x in required) +
                '\nReinicia Python y vuelve a ejecutar GeoLínea Tx.',
                'error', parent)
            return False

    if optional and interactive and _prompt_install(optional, False, parent):
        success, error = _install_packages([x[1] for x in optional], parent)
        if not success:
            _show_dependency_message('Complementos opcionales no instalados',
                error + '\n\nGeoLínea Tx continuará con las funciones disponibles. '
                'Puedes instalarlos después desde Ayuda > Revisar bibliotecas.',
                'warning', parent)
        else:
            remains = get_missing_dependencies(OPTIONAL_DEPS)
            if remains:
                _show_dependency_message('Algunos complementos no están disponibles',
                    'Verifica la instalación o reinicia la aplicación: ' +
                    ', '.join(x[1] for x in remains), 'warning', parent)
    return True

def register_module(name,source):
    mod=types.ModuleType(name)
    mod.__file__=str(BASE/(name+'.py'))
    mod.__package__=''
    sys.modules[name]=mod
    exec(compile(source,mod.__file__,'exec'),mod.__dict__)
    return mod

