MODULES = [('detector_contenido', '"""Detección conservadora de listados de estructuras y coordenadas; no usa OCR."""\nimport csv\nimport re\nimport unicodedata\nimport zipfile\nfrom pathlib import Path\nfrom xml.etree import ElementTree as ET\n\nMAX_BYTES = 35 * 1024 * 1024\nMAX_TEXT = 350000\n\ndef norm(s):\n    return \'\'.join(c for c in unicodedata.normalize(\'NFKD\',str(s).lower()) if not unicodedata.combining(c))\n\nSTRUCT = re.compile(r\'\\b(torres?|estructuras?|postes?|apoyos?|piquetes?|distribucion\\s+de\\s+(?:estructuras|torres)|listado\\s+de\\s+(?:estructuras|torres))\\b\')\nCOORD = re.compile(r\'\\b(coordenadas?|latitud|longitud|latitude|longitude|utm|este|norte|easting|northing|huso|datum|wgs\\s*84)\\b\')\nPAIR = re.compile(r\'\\b(?:latitud|latitude|lat)\\b.{0,65}\\b(?:longitud|longitude|lon|long)\\b|\\b(?:este|easting)\\b.{0,65}\\b(?:norte|northing)\\b\',re.S)\nDECIMAL_PAIR = re.compile(r\'(?<!\\d)-?\\d{1,2}[.,]\\d{4,}\\s*[,;\\t ]+\\s*-?\\d{1,3}[.,]\\d{4,}\')\n\ndef inspect(path):\n    path=Path(path)\n    result={\'archivo\':str(path),\'formato\':path.suffix.lower(),\'clasificacion\':\'No identificado\',\n            \'estructuras\':False,\'coordenadas\':False,\'evidencia\':\'\',\'estado\':\'No analizado\'}\n    try:\n        if path.stat().st_size > MAX_BYTES:\n            result[\'estado\']=\'No analizado: supera límite de 35 MB\';return result\n        ext=path.suffix.lower()\n        snippets=[]\n        if ext in (\'.xlsx\',\'.xlsm\'):\n            from openpyxl import load_workbook\n            wb=load_workbook(path,read_only=True,data_only=True)\n            try:\n                for ws in wb.worksheets[:15]:\n                    snippets.append(ws.title)\n                    for row in ws.iter_rows(max_row=1800,max_col=40,values_only=True):\n                        snippets.append(\' | \'.join(str(v)[:120] for v in row if v is not None))\n                        if sum(map(len,snippets))>MAX_TEXT:break\n            finally:wb.close()\n        elif ext in (\'.csv\',\'.txt\'):\n            with path.open(\'r\',encoding=\'utf-8-sig\',errors=\'replace\') as f:\n                snippets=f.read(MAX_TEXT).splitlines()\n        elif ext==\'.pdf\':\n            from pypdf import PdfReader\n            pdf=PdfReader(str(path),strict=False)\n            for page in pdf.pages[:35]:\n                snippets.append(page.extract_text() or \'\')\n                if sum(map(len,snippets))>MAX_TEXT:break\n        elif ext==\'.docx\':\n            from docx import Document\n            doc=Document(path)\n            snippets.extend(p.text for p in doc.paragraphs[:2000])\n            for table in doc.tables[:50]:\n                for row in table.rows[:300]:\n                    snippets.append(\' | \'.join(c.text for c in row.cells))\n        elif ext==\'.kml\':\n            snippets=[path.read_text(encoding=\'utf-8\',errors=\'replace\')[:MAX_TEXT]]\n        elif ext==\'.kmz\':\n            with zipfile.ZipFile(path) as z:\n                for item in z.infolist():\n                    if item.filename.lower().endswith(\'.kml\') and item.file_size <= MAX_BYTES:\n                        snippets.append(z.read(item)[:MAX_TEXT].decode(\'utf-8\',errors=\'replace\'))\n                        break\n        elif ext==\'.xls\':\n            result[\'estado\']=\'No analizado: convertir XLS a XLSX\';return result\n        else:\n            result[\'estado\']=\'Formato no soportado\';return result\n        content=norm(\'\\n\'.join(snippets)[:MAX_TEXT]); filename=norm(path.stem)\n        struct=bool(STRUCT.search(content)); coords=bool(COORD.search(content))\n        kml_coords=ext in (\'.kml\',\'.kmz\') and \'<coordinates>\' in content\n        coords=coords or bool(PAIR.search(content)) or bool(DECIMAL_PAIR.search(content)) or kml_coords\n        result[\'estructuras\']=struct\n        result[\'coordenadas\']=coords\n        if struct and coords: result[\'clasificacion\']=\'Confirmado\'\n        elif struct or coords or STRUCT.search(filename) or COORD.search(filename):result[\'clasificacion\']=\'Posible\'\n        else:result[\'clasificacion\']=\'No identificado\'\n        evidence=[]\n        if struct:evidence.append(\'términos de estructuras en contenido\')\n        if coords:evidence.append(\'indicios de coordenadas en contenido\')\n        if not (struct or coords) and (STRUCT.search(filename) or COORD.search(filename)):evidence.append(\'solo nombre del archivo\')\n        result[\'evidencia\']=\'; \'.join(evidence) or \'Sin patrones reconocibles\'\n        result[\'estado\']=\'Analizado\' if content.strip() else \'Sin texto extraíble (posible escaneo)\'\n    except Exception as exc:\n        result[\'estado\']=f\'Error de lectura: {str(exc)[:160]}\'\n    return result\n\n\ndef inspect_folder(folder, callback=None):\n    root=Path(folder)\n    supported={\'.xlsx\',\'.xlsm\',\'.xls\',\'.csv\',\'.txt\',\'.pdf\',\'.docx\',\'.kml\',\'.kmz\'}\n    paths=sorted(p for p in root.rglob(\'*\') if p.is_file() and p.suffix.lower() in supported and not any(part.lower() in (\'.cache\',\'reporte_estructuras\',\'__pycache__\') for part in p.relative_to(root).parts[:-1]) and not p.name.startswith(\'~$\'))\n    out=[]\n    for i,p in enumerate(paths,1):\n        if callback:callback(i,len(paths),p.name)\n        r=inspect(p)\n        m=re.search(r\'^ST_(\\d+)$\',next((x for x in p.parts if re.fullmatch(r\'ST_\\d+\',x)),\'\'))\n        r[\'id_seccion\']=m.group(1) if m else \'\'\n        out.append(r)\n    return out\n\n\ndef write_csv(results,path):\n    columns=[\'id_seccion\',\'archivo\',\'formato\',\'clasificacion\',\'estructuras\',\'coordenadas\',\'evidencia\',\'estado\']\n    with open(path,\'w\',newline=\'\',encoding=\'utf-8-sig\') as f:\n        w=csv.DictWriter(f,fieldnames=columns,delimiter=\';\',extrasaction=\'ignore\');w.writeheader();w.writerows(results)\n'), ('extractor_estructuras', '"""Piloto: extrae filas de coordenadas de documentos, sin inferir relaciones BDATx.\nSalidas CSV UTF-8-SIG separadas por punto y coma. No realiza OCR.\n"""\nimport csv, re, unicodedata\nfrom pathlib import Path\nfrom collections import defaultdict\nfrom detector_contenido import inspect, inspect_folder\n\n\n# Inferencia controlada SOLO para LDE sin huso. No reemplaza el catalogo BDATx.\ndef resolver_huso_lde(este,norte,huso_documental=None,referencia=None):\n    """Retorna lon, lat, huso, estado, observacion. Nunca elige arbitrariamente entre 18 y 19."""\n    import re\n    from pyproj import Transformer\n    try: este=float(este);norte=float(norte)\n    except (TypeError,ValueError):return None,None,\'\',\'SIN_COORDENADAS\',\'UTM incompleto\'\n    if not (100000<=este<=900000 and 1000000<=norte<=10000000):\n        return None,None,\'\',\'UTM_INVALIDO\',\'Este/Norte fuera de rango UTM\'\n    original=str(huso_documental or \'\').strip().upper().replace(\' \',\'\')\n    m=re.fullmatch(r\'(18|19)([C-X])?\',original)\n    candidates=[]\n    for z in ([int(m.group(1))] if m else [18,19]):\n        lon,lat=Transformer.from_crs(f\'EPSG:327{z}\',\'EPSG:4326\',always_xy=True).transform(este,norte)\n        # Filtro conservador de Chile continental; NO equivale a un poligono oficial.\n        plausible=(-56<=lat<=-17 and -75.5<=lon<=-66)\n        if plausible:candidates.append((z,lon,lat))\n    if m:\n        if candidates:\n            z,lon,lat=candidates[0];return lon,lat,f\'{z}{m.group(2) or ""}\',\'DOCUMENTAL\',\'Huso indicado en LDE; hemisferio sur para Chile\'\n        return None,None,original,\'REVISAR\',\'Huso declarado produce coordenadas fuera de Chile continental\'\n    if len(candidates)==1:\n        z,lon,lat=candidates[0]\n        return lon,lat,str(z),\'HUSO_INFERIDO\',\'Huso inferido por descarte geográfico entre 18S y 19S; validar contra BDIT/BDATx\'\n    if len(candidates)==2 and referencia is not None:\n        try:\n            lonref,latref=referencia\n            import math\n            ranked=sorted((math.hypot((lon-lonref)*math.cos(math.radians(latref)),lat-latref),z,lon,lat) for z,lon,lat in candidates)\n            if ranked[0][0]<0.3 and ranked[1][0]-ranked[0][0]>1:\n                _,z,lon,lat=ranked[0]\n                return lon,lat,str(z),\'HUSO_INFERIDO_REFERENCIA\',\'Huso inferido por proximidad a referencia geográfica verificada; validar\'\n        except (TypeError,ValueError):pass\n    return None,None,\'\',\'HUSO_AMBIGUO\' if candidates else \'FUERA_CHILE\',(\'Ambos husos 18 y 19 producen ubicaciones plausibles; se requiere referencia\' if candidates else \'Ninguno de los husos 18/19 produce ubicación continental plausible\')\n\nEXTS={\'.xlsx\',\'.xlsm\',\'.csv\',\'.txt\',\'.docx\',\'.pdf\'}\ndef norm(x):\n    return \'\'.join(c for c in unicodedata.normalize(\'NFKD\',str(x or \'\').lower()) if not unicodedata.combining(c)).strip()\ndef number(x):\n    s=str(x or \'\').strip().replace(\' \',\'\').replace(\'°\',\'\')\n    if not s:return None\n    if \',\' in s and \'.\' in s:\n        s=s.replace(\'.\',\'\').replace(\',\',\'.\') if s.rfind(\',\')>s.rfind(\'.\') else s.replace(\',\',\'\')\n    elif \',\' in s:s=s.replace(\',\',\'.\')\n    try:return float(s)\n    except (ValueError,OverflowError):return None\n\ndef classify_header(cells):\n    found={}\n    for i,x in enumerate(cells):\n        t=norm(x).replace(\'_\',\' \').replace(\'-\',\' \')\n        if re.search(r\'\\b(latitud|latitude|lat)\\b\',t):found.setdefault(\'lat\',i)\n        elif re.search(r\'\\b(longitud|longitude|lon|long)\\b\',t):found.setdefault(\'lon\',i)\n        elif re.search(r\'\\b(este|easting|coord e|utm e)\\b\',t):found.setdefault(\'este\',i)\n        elif re.search(r\'\\b(norte|northing|coord n|utm n)\\b\',t):found.setdefault(\'norte\',i)\n        elif re.search(r\'\\b(huso|zona utm|zone|zona)\\b\',t):found.setdefault(\'huso\',i)\n        elif re.search(r\'\\b(torre|estructura|apoyo|poste|piquete|numero estructura|n estructura|numeracion)\\b\',t):found.setdefault(\'estructura\',i)\n    return found if (\'lat\' in found and \'lon\' in found) or (\'este\' in found and \'norte\' in found) else None\n\ndef tables(path):\n    ext=path.suffix.lower()\n    if ext in (\'.xlsx\',\'.xlsm\'):\n        from openpyxl import load_workbook\n        wb=load_workbook(path,read_only=True,data_only=True)\n        try:\n            for sh in wb.worksheets[:30]:\n                yield sh.title, ([str(v) if v is not None else \'\' for v in row] for row in sh.iter_rows(max_row=20000,max_col=65,values_only=True))\n        finally:wb.close()\n    elif ext in (\'.csv\',\'.txt\'):\n        with path.open(encoding=\'utf-8-sig\',errors=\'replace\',newline=\'\') as f:\n            sample=f.read(8192);f.seek(0)\n            first=sample.splitlines()[0] if sample.splitlines() else \'\'\n            # Choose separators from the header, not from decimal commas (Chile).\n            if \';\' in first: delimiter=\';\'\n            elif \'\\t\' in first: delimiter=\'\\t\'\n            elif \'|\' in first: delimiter=\'|\'\n            else:\n                try: delimiter=csv.Sniffer().sniff(sample,delimiters=\',;\\t|\').delimiter\n                except csv.Error: delimiter=\',\'\n            yield \'Texto\',list(csv.reader(f,delimiter=delimiter))[:20000]\n    elif ext==\'.docx\':\n        from docx import Document\n        doc=Document(path)\n        for i,t in enumerate(doc.tables[:100],1):\n            yield f\'Tabla {i}\',([c.text for c in r.cells] for r in t.rows[:20000])\n    elif ext==\'.pdf\':\n        from pypdf import PdfReader\n        pdf=PdfReader(str(path),strict=False)\n        for i,p in enumerate(pdf.pages[:80],1):\n            txt=p.extract_text() or \'\'\n            # PDF sin estructura tabular: únicamente filas delimitadas; no inventar columnas.\n            rows=[re.split(r\'\\s{2,}|\\t|\\s*\\|\\s*\',line.strip()) for line in txt.splitlines()]\n            yield f\'Página {i}\',rows\n\ndef parse_table(rows,path,source,section,classification):\n    head=None; found=[]\n    for lineno,row in enumerate(rows,1):\n        if lineno>20000:break\n        if not isinstance(row,(list,tuple)):continue\n        candidate=classify_header(row)\n        if candidate:\n            head=candidate;continue\n        if not head:continue\n        def get(key):\n            idx=head.get(key)\n            return str(row[idx]).strip() if idx is not None and idx<len(row) else \'\'\n        lat,lon,este,norte=map(lambda k:number(get(k)),(\'lat\',\'lon\',\'este\',\'norte\'))\n        missing_all=all(v is None for v in (lat,lon,este,norte))\n        if missing_all and not get(\'estructura\'):continue\n        errors=[\'Coordenadas ausentes o no interpretables\'] if missing_all else [];z_i=\'\';system=\'Geográficas\' if lat is not None or lon is not None else \'UTM\'\n        if system==\'Geográficas\':\n            if lat is None or lon is None:errors.append(\'Par latitud/longitud incompleto\')\n            elif not (-90<=lat<=90 and -180<=lon<=180):errors.append(\'Latitud/longitud fuera de rango\')\n            elif not (-56<=lat<=-17 and -76<=lon<=-66):errors.append(\'Fuera de rango aproximado Chile continental; revisar\')\n        else:\n            if este is None or norte is None:errors.append(\'Par Este/Norte incompleto\')\n            elif not (100000<=este<=900000 and 1000000<=norte<=10000000):errors.append(\'UTM fuera de rango general\')\n            if este is not None and norte is not None:\n                lon_i,lat_i,z_i,estado_i,obs_i=resolver_huso_lde(este,norte,get(\'huso\'))\n                if lon_i is not None:\n                    lon,lat=lon_i,lat_i\n                    if estado_i==\'HUSO_INFERIDO\':errors.append(obs_i)\n                else:errors.append(obs_i)\n            else:z_i=\'\'\n        found.append({\'id_seccion\':section,\'archivo\':str(path),\'origen\':source,\'fila\':lineno,\'clasificacion_documento\':classification,\n                      \'estructura\':get(\'estructura\'),\'sistema\':system,\'latitud\':lat if lat is not None else \'\',\n                      \'longitud\':lon if lon is not None else \'\', \'este\':este if este is not None else \'\',\n                      \'norte\':norte if norte is not None else \'\', \'huso\':get(\'huso\') or z_i,\n                      \'estado\':\'REVISAR\' if errors else \'VALIDO_PRELIMINAR\',\'observacion\':\'; \'.join(errors)})\n    return found\n\ndef export_csv(path,records,headers):\n    with Path(path).open(\'w\',newline=\'\',encoding=\'utf-8-sig\') as f:\n        writer=csv.DictWriter(f,fieldnames=headers,delimiter=\';\',extrasaction=\'ignore\');writer.writeheader();writer.writerows(records)\n\ndef parse_lde_standard(path,section,classification):\n    """LDE estándar: E=G, N=H, datum=I, huso=J, número=K (encabezado fila 14).\n    Validar esquema y no confundir latitud/longitud con coordenadas UTM.\n    """\n    if path.suffix.lower() not in (\'.xlsx\',\'.xlsm\'):return None\n    if not re.search(r\'\\bLDE\\b|ST\\d+_DOC\',path.name,re.I):return None\n    from openpyxl import load_workbook\n    wb=load_workbook(path,read_only=True,data_only=True)\n    try:\n        sh=wb.worksheets[0]\n        head=[norm(sh.cell(14,j).value) for j in range(1,15)]\n        if not (\'este\' in head[6] and \'norte\' in head[7]):return None\n        output=[]\n        for i,row in enumerate(sh.iter_rows(min_row=16,max_col=14,values_only=True),16):\n            if i>20000:break\n            name=row[10];e=number(row[6]);n=number(row[7])\n            if name is None or (e is None and n is None):continue\n            raw_huso=str(row[9] or \'\').strip()\n            lon,lat,zone,state,obs=resolver_huso_lde(e,n,raw_huso)\n            output.append({\'id_seccion\':section,\'archivo\':str(path),\'origen\':sh.title,\'fila\':i,\n                           \'clasificacion_documento\':classification,\'estructura\':str(name),\n                           \'sistema\':\'UTM\',\'latitud\':lat if lat is not None else \'\',\n                           \'longitud\':lon if lon is not None else \'\', \'este\':e if e is not None else \'\',\n                           \'norte\':n if n is not None else \'\', \'huso\':zone or raw_huso,\n                           \'estado\':\'VALIDO_PRELIMINAR\' if lat is not None and lon is not None else \'REVISAR\',\n                           \'observacion\':\'\' if state==\'DOCUMENTAL\' else obs})\n        return output\n    finally:wb.close()\n\ndef run(folder,progress=None):\n    root=Path(folder); destination=root/\'.cache\'/\'REPORTE_ESTRUCTURAS\';destination.mkdir(parents=True,exist_ok=True)\n    # La clasificación y extracción se reconstruyen desde archivos EXISTENTES en cada ejecución.\n    # Nunca se reutiliza un CSV de .cache como fuente de verdad.\n    import hashlib\n    inspections=inspect_folder(root)\n    rows=[]; errors=[]; selected=[]; duplicates=[]; seen_files={}\n    for meta in inspections:\n        path=Path(meta[\'archivo\']); section=meta.get(\'id_seccion\',\'\')\n        if path.suffix.lower() not in EXTS:continue\n        if meta[\'clasificacion\']==\'No identificado\' or meta[\'estado\'].startswith((\'Error\',\'No analizado\',\'Formato no\')):\n            continue\n        if not section:\n            match=re.search(r\'^ST[_ -]?(\\d+)(?:[_ -]|$)\',path.name,re.I)\n            if match:\n                section=match.group(1)\n                meta[\'id_seccion\']=section\n            else:\n                errors.append({\'archivo\':str(path),\'motivo\':\'No se identificó ST_ID: archivo omitido para evitar asociaciones incorrectas\'})\n                continue\n        try:\n            digest=hashlib.sha256(path.read_bytes()).hexdigest()\n        except OSError as exc:\n            errors.append({\'archivo\':str(path),\'motivo\':str(exc)});continue\n        key=(section,digest)\n        if key in seen_files:\n            duplicates.append({\'id_seccion\':section,\'archivo\':str(path),\'duplicado_de\':seen_files[key]})\n            continue\n        seen_files[key]=str(path)\n        selected.append(meta)\n    for n,meta in enumerate(selected,1):\n        path=Path(meta[\'archivo\'])\n        if progress:progress(n,len(selected),path.name)\n        if path.stat().st_size>35*1024*1024:\n            errors.append({\'archivo\':str(path),\'motivo\':\'Supera 35 MB\'});continue\n        try:\n            dedicated=parse_lde_standard(path,meta[\'id_seccion\'],meta[\'clasificacion\'])\n            if dedicated is not None:\n                rows.extend(dedicated)\n            else:\n                for source,records in tables(path):\n                    rows.extend(parse_table(records,path,source,meta[\'id_seccion\'],meta[\'clasificacion\']))\n        except Exception as exc:errors.append({\'archivo\':str(path),\'motivo\':str(exc)[:250]})\n    # Deduplicación de filas: mismo registro en una misma sección solo una vez.\n    unique=[];seen_rows=set()\n    for row in rows:\n        key=(row[\'id_seccion\'],norm(row[\'estructura\']),row[\'latitud\'],row[\'longitud\'],row[\'este\'],row[\'norte\'],row[\'huso\'])\n        if key in seen_rows:continue\n        seen_rows.add(key);unique.append(row)\n    rows=unique\n    columns=[\'id_seccion\',\'archivo\',\'origen\',\'fila\',\'clasificacion_documento\',\'estructura\',\'sistema\',\'latitud\',\'longitud\',\'este\',\'norte\',\'huso\',\'estado\',\'observacion\']\n    export_csv(destination/\'01_COORDENADAS_EXTRAIDAS.csv\',rows,columns)\n    export_csv(destination/\'02_DOCUMENTOS_CLASIFICADOS.csv\',inspections,[\'id_seccion\',\'archivo\',\'formato\',\'clasificacion\',\'estructuras\',\'coordenadas\',\'evidencia\',\'estado\'])\n    export_csv(destination/\'03_ERRORES_LECTURA.csv\',errors,[\'archivo\',\'motivo\'])\n    export_csv(destination/\'05_ARCHIVOS_DUPLICADOS_OMITIDOS.csv\',duplicates,[\'id_seccion\',\'archivo\',\'duplicado_de\'])\n    sections=sorted({r[\'id_seccion\'] for r in rows if r[\'id_seccion\']})\n    control=[{\'id_seccion\':s,\'estructuras_extraidas\':sum(r[\'id_seccion\']==s for r in rows),\n              \'pendientes_revision\':sum(r[\'id_seccion\']==s and r[\'estado\']==\'REVISAR\' for r in rows),\n              \'coordinado\':\'PENDIENTE_CRUCE_BDIT_BDATX\',\'vanos\':\'PENDIENTE_CRUCE_BDATX\',\'torres\':\'PENDIENTE_CRUCE_BDATX\'} for s in sections]\n    export_csv(destination/\'04_CONTROL_SECCIONES.csv\',control,[\'id_seccion\',\'estructuras_extraidas\',\'pendientes_revision\',\'coordinado\',\'vanos\',\'torres\'])\n    (destination/\'LEEME.txt\').write_text(\'PILOTO - Resultados preliminares. VALIDO_PRELIMINAR solo valida rangos generales, NO georreferencia ni asociación oficial.\\nNo se asigna coordinado, vano o torre sin cruces BDIT/BDATx.\\nLos PDF escaneados no se procesan (sin OCR). PDF con tablas no delimitadas puede requerir lector especializado.\\nLa selección de documento vigente debe confirmarse usando fecha_modificacion del inventario BDIT; no se infiere desde nombres de carpeta.\\n\',encoding=\'utf-8\')\n    return destination,len(rows),len(errors)\n'), ('archivo_zip', '"""LíneaTx: inspección y selección segura de documentos dentro de ZIP.\n\nNo extrae el archivo ZIP completo: solo los miembros aprobados y seleccionados.\nFunciona sin conexión y no admite ZIP anidados ni documentos cifrados.\n"""\nfrom __future__ import annotations\nimport hashlib\nimport os\nimport re\nimport stat\nimport tkinter as tk\nimport zipfile\nfrom pathlib import Path, PurePosixPath\nfrom tkinter import ttk, messagebox\n\n# Tipos realmente soportados por el lector LDE local.\nLDE_FORMATS = frozenset({\'.xlsx\',\'.xlsm\',\'.csv\',\'.txt\',\'.docx\',\'.pdf\'})\nMAX_FILES = 5000\nMAX_MEMBER = 35 * 1024 * 1024\nMAX_SELECTED = 250 * 1024 * 1024\nMAX_RATIO = 400\n\n\ndef _safe_member(name):\n    """Ruta relativa POSIX apta para una extracción sin escapes ni rutas absolutas."""\n    if not name or \'\\\\\' in name or \'\\x00\' in name or \':\' in name:\n        return None\n    parts=PurePosixPath(name)\n    if parts.is_absolute() or not parts.parts or any(p in (\'..\',\'.\') for p in parts.parts):\n        return None\n    if parts.parts[0].startswith(\'.\') and parts.parts[0] in (\'.\',\'..\'):\n        return None\n    return parts\n\n\ndef scan_zip(zip_path):\n    """Lista contenido sin extraerlo, con extensión y estado de compatibilidad."""\n    zip_path=Path(zip_path)\n    if not zipfile.is_zipfile(zip_path):\n        raise ValueError(\'El archivo seleccionado no es un ZIP válido.\')\n    items=[]\n    with zipfile.ZipFile(zip_path) as z:\n        infos=z.infolist()\n        if len(infos)>MAX_FILES:\n            raise ValueError(f\'ZIP con más de {MAX_FILES} elementos: no se analizará.\')\n        names=set()\n        for info in infos:\n            if info.is_dir(): continue\n            suffix=Path(info.filename).suffix.lower() or \'(sin extensión)\'\n            filemode=(info.external_attr>>16) & 0o170000\n            reason=\'\'\n            if _safe_member(info.filename) is None:\n                reason=\'Ruta no segura\'\n            elif info.filename in names:\n                reason=\'Nombre duplicado en ZIP\'\n            elif filemode == stat.S_IFLNK:\n                reason=\'Enlace simbólico no permitido\'\n            elif info.flag_bits & 0x1:\n                reason=\'Archivo cifrado\'\n            elif info.file_size>MAX_MEMBER:\n                reason=\'Supera 35 MB\'\n            elif info.file_size and info.compress_size and info.file_size/max(1,info.compress_size)>MAX_RATIO:\n                reason=\'Compresión anómala\'\n            elif suffix not in LDE_FORMATS:\n                reason=\'No interpretable como LDE\'\n            names.add(info.filename)\n            items.append({\'nombre\':info.filename,\'extension\':suffix,\n                          \'tamano\':info.file_size,\n                          \'estado\':\'Disponible para LDE\' if not reason else reason,\n                          \'seleccionable\':not bool(reason)})\n    return items\n\n\ndef extract_selected(zip_path, names, target_root):\n    """Extrae solo seleccionados, con cuotas e inspección de rutas (sin ZipFile.extractall)."""\n    zip_path=Path(zip_path).resolve()\n    target_root=Path(target_root).resolve()\n    selected=list(dict.fromkeys(names))\n    if not selected: return []\n    catalog={r[\'nombre\']:r for r in scan_zip(zip_path)}\n    bad=[name for name in selected if name not in catalog or not catalog[name][\'seleccionable\']]\n    if bad:raise ValueError(\'Documentos ZIP no permitidos: \'+\', \'.join(bad[:3]))\n    if sum(catalog[n][\'tamano\'] for n in selected)>MAX_SELECTED:\n        raise ValueError(\'La selección supera 250 MB descomprimidos.\')\n    target_root.mkdir(parents=True,exist_ok=True)\n    extracted=[]\n    with zipfile.ZipFile(zip_path) as z:\n        for name in selected:\n            member=_safe_member(name)\n            if member is None:raise ValueError(\'Ruta no permitida: \'+name)\n            out=(target_root.joinpath(*member.parts)).resolve()\n            if not out.is_relative_to(target_root):\n                raise ValueError(\'ZIP contiene ruta fuera de carpeta de destino.\')\n            out.parent.mkdir(parents=True,exist_ok=True)\n            # Escribir en temporal y renombrar al terminar, sin dejar parcial.\n            partial=out.with_name(out.name+\'.lineatx_part\')\n            size=0\n            try:\n                with z.open(name,\'r\') as src, partial.open(\'wb\') as dest:\n                    for block in iter(lambda:src.read(128*1024),b\'\'):\n                        size+=len(block)\n                        if size>MAX_MEMBER or size>catalog[name][\'tamano\']+1024:\n                            raise ValueError(\'ZIP excede tamaño declarado: \'+name)\n                        dest.write(block)\n                partial.replace(out)\n            finally:\n                partial.unlink(missing_ok=True)\n            extracted.append(out)\n    return extracted\n\n\n\n\ndef _configure_rar_backends(rarfile):\n    """Detecta herramientas habituales en Windows aunque no estén en PATH."""\n    import shutil\n    candidates=[]\n    for env in (\'PROGRAMFILES\',\'PROGRAMFILES(X86)\',\'LOCALAPPDATA\'):\n        root=os.environ.get(env)\n        if root:\n            candidates += [(Path(root)/\'7-Zip\'/\'7z.exe\',\'SEVENZIP_TOOL\'),\n                           (Path(root)/\'WinRAR\'/\'UnRAR.exe\',\'UNRAR_TOOL\'),\n                           (Path(root)/\'WinRAR\'/\'UnRAR64.exe\',\'UNRAR_TOOL\')]\n    for candidate,setting in candidates:\n        if candidate.is_file() and not shutil.which(getattr(rarfile,setting,\'\')):\n            setattr(rarfile,setting,str(candidate))\n\n\ndef scan_rar(rar_path):\n    """Inspecciona RAR sin extraer; requiere rarfile (lector puro de cabeceras)."""\n    try:import rarfile\n    except ImportError as ex:\n        raise RuntimeError(\'Para inspeccionar RAR instala rarfile: python -m pip install rarfile\') from ex\n    rar_path=Path(rar_path)\n    if not rarfile.is_rarfile(str(rar_path)):\n        raise ValueError(\'El archivo seleccionado no tiene una firma RAR válida.\')\n    _configure_rar_backends(rarfile)\n    items=[];names=set()\n    with rarfile.RarFile(str(rar_path)) as r:\n        infos=r.infolist()\n        if not infos:raise ValueError(\'RAR vacío o con cabeceras ilegibles; comprueba que el archivo no esté dañado.\')\n        if len(infos)>MAX_FILES:raise ValueError(f\'RAR con más de {MAX_FILES} elementos: no se analizará.\')\n        for info in infos:\n            if info.is_dir():continue\n            name=info.filename.replace(\'\\\\\',\'/\')\n            suffix=Path(name).suffix.lower() or \'(sin extensión)\'\n            reason=\'\'\n            if _safe_member(name) is None:reason=\'Ruta no segura\'\n            elif name in names:reason=\'Nombre duplicado en RAR\'\n            elif getattr(info,\'is_symlink\',lambda:False)():reason=\'Enlace simbólico no permitido\'\n            elif info.needs_password():reason=\'Archivo cifrado\'\n            elif info.file_size>MAX_MEMBER:reason=\'Supera 35 MB\'\n            elif info.file_size and info.compress_size and info.file_size/max(1,info.compress_size)>MAX_RATIO:reason=\'Compresión anómala\'\n            elif suffix not in LDE_FORMATS:reason=\'No interpretable como LDE\'\n            names.add(name)\n            items.append({\'nombre\':name,\'extension\':suffix,\'tamano\':info.file_size,\n                          \'estado\':\'Disponible para LDE\' if not reason else reason,\n                          \'seleccionable\':not bool(reason)})\n    return items\n\n\ndef scan_archive(path):\n    p=Path(path)\n    if p.suffix.lower()==\'.rar\':return scan_rar(p)\n    if p.suffix.lower()==\'.zip\':return scan_zip(p)\n    raise ValueError(\'Formato de archivo comprimido no admitido (se admite ZIP o RAR).\')\n\n\ndef extract_rar_selected(rar_path,names,target_root):\n    try:import rarfile\n    except ImportError as ex:raise RuntimeError(\'Instala rarfile: python -m pip install rarfile\') from ex\n    _configure_rar_backends(rarfile)\n    rar_path=Path(rar_path).resolve();target_root=Path(target_root).resolve()\n    selected=list(dict.fromkeys(names))\n    if not selected:return []\n    catalog={row[\'nombre\']:row for row in scan_rar(rar_path)}\n    bad=[x for x in selected if x not in catalog or not catalog[x][\'seleccionable\']]\n    if bad:raise ValueError(\'Elementos RAR no permitidos: \'+\', \'.join(bad[:4]))\n    if sum(catalog[x][\'tamano\'] for x in selected)>MAX_SELECTED:\n        raise ValueError(\'La selección RAR supera 250 MB descomprimidos.\')\n    target_root.mkdir(parents=True,exist_ok=True)\n    result=[]\n    try:\n        with rarfile.RarFile(str(rar_path)) as arc:\n            for name in selected:\n                rel=_safe_member(name)\n                if rel is None:raise ValueError(\'Ruta no permitida en RAR.\')\n                target=(target_root.joinpath(*rel.parts)).resolve()\n                if not target.is_relative_to(target_root):raise ValueError(\'Ruta RAR fuera de la carpeta de extracción.\')\n                target.parent.mkdir(parents=True,exist_ok=True)\n                temp=target.with_name(target.name+\'.lineatx_part\');size=0\n                try:\n                    with arc.open(name) as inp,temp.open(\'wb\') as out:\n                        while True:\n                            block=inp.read(128*1024)\n                            if not block:break\n                            size+=len(block)\n                            if size>MAX_MEMBER or size>catalog[name][\'tamano\']+1024:\n                                raise ValueError(\'RAR supera el tamaño declarado: \'+name)\n                            out.write(block)\n                    temp.replace(target)\n                finally:temp.unlink(missing_ok=True)\n                result.append(target)\n    except rarfile.RarCannotExec as ex:\n        raise RuntimeError(\'RAR reconocido, pero falta un descompresor en Windows. Instala 7-Zip o WinRAR (UnRAR.exe) y vuelve a intentar.\') from ex\n    return result\n\n\ndef extract_archive_selected(path,names,target_root):\n    path=Path(path)\n    if path.suffix.lower()==\'.rar\':return extract_rar_selected(path,names,target_root)\n    return extract_selected(path,names,target_root)\n\n\ndef new_extraction_destination(archive_path, destination_parent):\n    """Crea un destino nuevo sin borrar extracciones anteriores.\n\n    Ante un bloqueo de escritura en OneDrive, utiliza una carpeta temporal local\n    para poder leer el LDE sin alterar el ZIP ni los archivos descargados.\n    Retorna (carpeta, aviso) con aviso vacío cuando se utiliza el destino previsto.\n    """\n    import tempfile\n    import uuid\n    archive_path=Path(archive_path)\n    stem=re.sub(r\'[^A-Za-z0-9._-]+\',\'_\',archive_path.stem)[:60].strip(\'._\') or \'ANEXO\'\n    destination_parent=Path(destination_parent)\n    tried=[]\n    for parent in (destination_parent,\n                   Path(os.environ.get(\'LOCALAPPDATA\') or tempfile.gettempdir()) / \'LineaTx\' / \'ANEXOS_TEMPORALES\'):\n        try:\n            # Nunca reutilizar/eliminar una carpeta previa. Evita WinError 5\n            # causado por OneDrive, antivirus o exploradores con handles abiertos.\n            parent.mkdir(parents=True,exist_ok=True)\n            for _ in range(5):\n                target=parent/(stem+\'_\'+uuid.uuid4().hex[:10])\n                try:\n                    target.mkdir(exist_ok=False)\n                    return target, (\'\' if parent==destination_parent else\n                                    \'Carpeta de salida bloqueada: se usó una carpeta temporal local. \' +\n                                    \'Destino: \'+str(target))\n                except FileExistsError:\n                    continue\n            raise OSError(\'No fue posible crear una carpeta exclusiva de extracción.\')\n        except OSError as exc:\n            tried.append(f\'{parent}: {exc}\')\n    raise OSError(\'No fue posible escribir los anexos ni en la carpeta de la línea ni en la carpeta temporal local.\\n\'+\n                  \'\\n\'.join(tried))\n\n\ndef choose_archive_members(parent,path):\n    return choose_zip_members(parent,path)\n\nclass ZipPicker(tk.Toplevel):\n    """Vista previa legible; selección múltiple Ctrl/Shift y extracción confirmada."""\n    def __init__(self,parent,zip_path):\n        super().__init__(parent)\n        self.zip_path=Path(zip_path)\n        self.items=scan_archive(zip_path)\n        self.selection=None\n        self.title(\'GeoLínea Tx · Documentos dentro del ZIP/RAR\')\n        self.geometry(\'980x530\');self.minsize(690,390)\n        self.transient(parent.winfo_toplevel());self.grab_set()\n        panel=ttk.Frame(self,padding=15);panel.pack(fill=\'both\',expand=True)\n        ttk.Label(panel,text=f\'Archivo comprimido: {self.zip_path.name}\',font=(\'Segoe UI\',12,\'bold\')).pack(anchor=\'w\')\n        eligible=sum(x[\'seleccionable\'] for x in self.items)\n        ttk.Label(panel,text=f\'{len(self.items)} archivos · {eligible} admitidos para lectura LDE. Selecciona uno o varios con Ctrl/Mayús.\',\n                  foreground=\'#52677B\').pack(anchor=\'w\',pady=(5,12))\n        holder=ttk.Frame(panel);holder.pack(fill=\'both\',expand=True)\n        cols=(\'nombre\',\'ext\',\'tamano\',\'estado\')\n        self.tree=ttk.Treeview(holder,columns=cols,show=\'headings\',selectmode=\'extended\')\n        for c,label,width in [(\'nombre\',\'Documento / ruta dentro del ZIP\',520),(\'ext\',\'Extensión\',95),(\'tamano\',\'Tamaño\',100),(\'estado\',\'Lectura\',185)]:\n            self.tree.heading(c,text=label);self.tree.column(c,width=width,stretch=c==\'nombre\',anchor=\'w\')\n        bar=ttk.Scrollbar(holder,orient=\'vertical\',command=self.tree.yview)\n        self.tree.configure(yscrollcommand=bar.set)\n        bar.pack(side=\'right\',fill=\'y\');self.tree.pack(side=\'left\',fill=\'both\',expand=True)\n        for i,item in enumerate(self.items):\n            self.tree.insert(\'\', \'end\',iid=str(i),values=(item[\'nombre\'],item[\'extension\'],\n                f"{item[\'tamano\']/1024:,.1f} KB",item[\'estado\']),tags=(\'ok\' if item[\'seleccionable\'] else \'blocked\',))\n        self.tree.tag_configure(\'blocked\',foreground=\'#8D9298\')\n        controls=ttk.Frame(panel);controls.pack(fill=\'x\',pady=(12,0))\n        ttk.Button(controls,text=\'Seleccionar compatibles\',command=self.select_all).pack(side=\'left\')\n        ttk.Button(controls,text=\'Limpiar selección\',command=lambda:self.tree.selection_remove(*self.tree.selection())).pack(side=\'left\',padx=(8,0))\n        self.status=ttk.Label(controls,text=\'\');self.status.pack(side=\'left\',padx=14)\n        ttk.Button(controls,text=\'Cancelar\',command=self.cancel).pack(side=\'right\',padx=(8,0))\n        ttk.Button(controls,text=\'Usar documentos seleccionados\',command=self.accept).pack(side=\'right\')\n        self.tree.bind(\'<<TreeviewSelect>>\',lambda e:self.update_status())\n        self.protocol(\'WM_DELETE_WINDOW\',self.cancel)\n        self.update_status()\n\n    def select_all(self):\n        self.tree.selection_set(*(str(i) for i,it in enumerate(self.items) if it[\'seleccionable\']))\n        self.update_status()\n\n    def update_status(self):\n        selected=[self.items[int(i)] for i in self.tree.selection()]\n        valid=sum(1 for it in selected if it[\'seleccionable\'])\n        self.status.configure(text=f\'{valid} compatibles seleccionados\')\n\n    def accept(self):\n        selected=[self.items[int(i)] for i in self.tree.selection()]\n        invalid=[x[\'nombre\'] for x in selected if not x[\'seleccionable\']]\n        if invalid:\n            messagebox.showwarning(\'Documentos no compatibles\',\n                \'Desmarca los archivos no interpretables como LDE. Puedes consultarlos en la lista, pero no procesarlos.\\n\'+\n                \'\\n\'.join(invalid[:5]),parent=self)\n            return\n        self.selection=[x[\'nombre\'] for x in selected]\n        self.destroy()\n\n    def cancel(self):\n        self.selection=None\n        self.destroy()\n\n\ndef choose_zip_members(parent,zip_path):\n    dialog=ZipPicker(parent,zip_path)\n    parent.wait_window(dialog)\n    return dialog.selection\n'), ('consulta_documental_bdit', 'import csv\nfrom datetime import datetime, timezone\nimport json\nimport os\nimport re\nimport threading\nimport queue\nimport tkinter as tk\nfrom tkinter import ttk, filedialog, messagebox\nfrom pathlib import Path\nfrom urllib.parse import urljoin, urlparse, unquote\nimport requests\nfrom detector_contenido import inspect_folder, write_csv\nfrom extractor_estructuras import run as extract_structures\nfrom archivo_zip import choose_archive_members, extract_archive_selected, new_extraction_destination\nimport hashlib\n\nBASE = \'https://api-infotecnica.coordinador.cl/v1/\'\nHEADERS = {\'Accept\': \'application/json\', \'User-Agent\': \'ConsultaDocumentalBDIT/1.1\'}\nTIMEOUT = (12, 60)\n\ndef get_json(session, url, params=None):\n    r = session.get(url, params=params, timeout=TIMEOUT, headers=HEADERS)\n    r.raise_for_status()\n    return r.json()\n\ndef as_records(data):\n    if isinstance(data, list): return data\n    if isinstance(data, dict):\n        for key in (\'results\',\'data\',\'items\',\'registros\'):\n            if isinstance(data.get(key), list): return data[key]\n    return []\n\ndef fetch_catalog(session, slug, progress):\n    url = urljoin(BASE, f\'{slug}/\')\n    out = []\n    visited = set()\n    params = {\'page_size\': 1000}\n    while url:\n        if url in visited: raise RuntimeError(\'Paginación circular en \' + slug)\n        visited.add(url)\n        data = get_json(session, url, params)\n        rows = as_records(data)\n        if not rows and isinstance(data, dict) and not any(k in data for k in (\'results\',\'data\',\'items\',\'registros\')):\n            raise ValueError(f\'Formato de respuesta inesperado: {slug}\')\n        out.extend(rows)\n        progress(f\'{slug}: {len(out)} registros\')\n        nxt = data.get(\'next\') if isinstance(data, dict) else None\n        if nxt:\n            url = urljoin(BASE, nxt)\n            params = None\n        else: break\n    return out\n\ndef clean_id(v):\n    if v is None: return \'\'\n    if isinstance(v, dict): return clean_id(v.get(\'id\'))\n    s = str(v).strip()\n    return s[:-2] if re.fullmatch(r\'\\d+\\.0\', s) else s\n\ndef extract_line_ids(section):\n    ids = set()\n    for field in (\'linea_id\', \'id_linea\', \'linea\'):\n        v = section.get(field)\n        if isinstance(v, dict): v = v.get(\'id\')\n        if v is not None and re.fullmatch(r\'\\d+\', clean_id(v)): ids.add(clean_id(v))\n    for field in (\'HIPERVINCULO\', \'hipervinculo\', \'url_linea\', \'linea_url\'):\n        value = str(section.get(field) or \'\')\n        for m in re.finditer(r\'/lineas/(\\d+)(?:/|\\b)\', value, re.I): ids.add(m.group(1))\n    return ids\n\ndef resolve_section_line(section, known_line_ids):\n    """Retorna línea BDIT verificada o motivo de incertidumbre.\n\n    Una ST sin relación o con varias líneas NO debe dirigirse a una LT arbitraria.\n    """\n    possibilities=extract_line_ids(section)\n    valid={v for v in possibilities if v in known_line_ids}\n    if len(valid)==1 and not (possibilities-valid):\n        return next(iter(valid)), \'\'\n    if len(valid)>1 or len(possibilities)>1:\n        return \'\', \'La sección tiene múltiples referencias de línea; requiere revisión.\'\n    if not possibilities:\n        return \'\', \'La API no proporciona una relación de línea verificable para esta sección.\'\n    return \'\', \'La línea referenciada no está en el catálogo BDIT consultado.\'\n\ndef document_items(data):\n    if isinstance(data, list): return data\n    if isinstance(data, dict):\n        for key in (\'results\',\'data\',\'items\',\'documentos\'):\n            if isinstance(data.get(key), list): return data[key]\n    return []\n\ndef doc_name(d):\n    for key in (\'nombre\',\'name\',\'nombre_archivo\',\'filename\',\'file_name\',\'titulo\',\'title\',\'descripcion\'):\n        if d.get(key): return str(d[key])\n    return f"Documento {d.get(\'id\', \'sin ID\')}"\n\ndef infer_downloaded_extension(path):\n    """Detecta tipo real cuando API no entregó extensión, sin confundir Office con ZIP."""\n    import zipfile\n    path=Path(path)\n    with path.open(\'rb\') as file: head=file.read(8)\n    if head.startswith(b\'%PDF-\'):return \'.pdf\'\n    if head.startswith((b\'PK\\x03\\x04\',b\'PK\\x05\\x06\',b\'PK\\x07\\x08\')):\n        if not zipfile.is_zipfile(path):return \'.bin\'\n        with zipfile.ZipFile(path) as z:\n            filenames=set(z.namelist())\n        if \'xl/workbook.xml\' in filenames:return \'.xlsx\'\n        if \'word/document.xml\' in filenames:return \'.docx\'\n        if \'ppt/presentation.xml\' in filenames:return \'.pptx\'\n        return \'.zip\'\n    return \'.bin\'\n\ndef doc_extension(d):\n    candidate=str(d.get(\'filename\') or d.get(\'nombre_archivo\') or d.get(\'file_name\') or doc_name(d))\n    from urllib.parse import urlparse\n    suffix=Path(urlparse(candidate).path).suffix.lower()\n    return suffix if suffix else \'No informada\'\n\ndef doc_url(d):\n    for key in (\'archivo\',\'archivo_url\',\'documento_url\',\'download_url\',\'url_descarga\',\'file\',\'file_url\',\'url\',\'ruta\'):\n        val = d.get(key)\n        if isinstance(val, dict): val = val.get(\'url\') or val.get(\'archivo\')\n        if isinstance(val, str) and val.strip():\n            raw=val.strip()\n            if raw.startswith(\'https://\'):return raw\n            if raw.startswith(\'/v1/\') or raw.startswith(\'v1/\'):return urljoin(\'https://api-infotecnica.coordinador.cl/\',raw.lstrip(\'/\'))\n            if raw.startswith(\'/\') and \'/documentos/\' in raw:return urljoin(BASE,raw)\n    return \'\'\n\n# BDIT: fecha_modificacion es el campo temporal oficial observado en /documentos/.\nDATE_FIELDS = (\'fecha_modificacion\', \'fecha_carga\', \'fecha_subida\', \'fecha_creacion\', \'fecha_registro\',\n               \'created_at\', \'created\', \'uploaded_at\', \'upload_date\',\n               \'fechaCarga\', \'fechaCreacion\', \'fecha\', \'date\')\nMODIFIED_FIELDS = (\'updated_at\', \'modified_at\', \'fechaActualizacion\')\n\ndef parse_api_date(value):\n    if value is None or isinstance(value, bool): return None\n    if isinstance(value, (int, float)):\n        try:\n            stamp = float(value)\n            if stamp > 1e12: stamp /= 1000\n            return datetime.fromtimestamp(stamp, tz=timezone.utc)\n        except (ValueError, OverflowError, OSError): return None\n    value = str(value).strip()\n    if not value: return None\n    try:\n        dt = datetime.fromisoformat(value.replace(\'Z\', \'+00:00\'))\n        return dt.replace(tzinfo=timezone.utc) if dt.tzinfo is None else dt.astimezone(timezone.utc)\n    except ValueError: pass\n    for fmt in (\'%d/%m/%Y %H:%M:%S\', \'%d/%m/%Y %H:%M\', \'%d/%m/%Y\',\n                \'%Y-%m-%d\', \'%Y/%m/%d\', \'%Y-%m-%d %H:%M:%S\'):\n        try: return datetime.strptime(value, fmt).replace(tzinfo=timezone.utc)\n        except ValueError: pass\n    return None\n\ndef document_date(doc):\n    for field in DATE_FIELDS:\n        if field in doc:\n            parsed = parse_api_date(doc[field])\n            if parsed: return parsed, field\n    return None, \'\'\n\ndef order_documents(documents):\n    """Muestra primero las cargas nuevas, agrupadas por sección tramo.\n\n    Se agrupa por (línea BDIT, ST) para admitir la búsqueda de varias líneas.\n    Los grupos se presentan según su carga más reciente, y dentro de cada ST\n    los documentos se ordenan de más nuevo a más antiguo. Sin fecha al final.\n    latest indica la fecha más reciente, pero NUNCA selecciona documentos.\n    """\n    def group_of(doc):\n        return clean_id(doc.get(\'line_id\')), clean_id(doc.get(\'section\'))\n\n    def section_sort_key(value):\n        return (0, int(value)) if str(value).isdigit() else (1, str(value))\n\n    latest = {}\n    for doc in documents.values():\n        dt = doc.get(\'date\')\n        group = group_of(doc)\n        if dt is not None and (group not in latest or dt > latest[group]):\n            latest[group] = dt\n\n    def sort_key(pair):\n        identifier, doc = pair\n        group = group_of(doc)\n        group_date = latest.get(group)\n        dt = doc.get(\'date\')\n        return (\n            group_date is None, -group_date.timestamp() if group_date else 0,\n            group[0], section_sort_key(group[1]),\n            dt is None, -dt.timestamp() if dt else 0,\n            str(doc.get(\'name\') or \'\').casefold(), str(identifier)\n        )\n\n    ordered = sorted(documents.items(), key=sort_key)\n    for identifier, doc in ordered:\n        dt = doc.get(\'date\')\n        doc[\'latest\'] = dt is not None and dt == latest.get(group_of(doc))\n        doc[\'date_label\'] = (dt.strftime(\'%d-%m-%Y %H:%M:%S UTC\')\n                             if dt is not None else \'No disponible\')\n    return dict(ordered)\n\ndef safe_filename(name):\n    name = Path(unquote(urlparse(name).path)).name or \'documento\'\n    name = re.sub(r\'[<>:"/\\\\|?*\\x00-\\x1f]\', \'_\', name).strip(\' .\')\n    return name[:150] or \'documento\'\n\n\ndef signature_type(data):\n    """Clasificación por firma: un HTTP 200 no necesariamente contiene el archivo."""\n    prefix=data[:1024].lstrip(b\'\\xef\\xbb\\xbf\\x00\\r\\n\\t \')\n    if data.startswith(b\'%PDF-\'):return \'pdf\'\n    if data.startswith((b\'PK\\x03\\x04\',b\'PK\\x05\\x06\',b\'PK\\x07\\x08\')):return \'zip-office\'\n    if data.startswith((b\'Rar!\\x1a\\x07\\x00\',b\'Rar!\\x1a\\x07\\x01\\x00\')):return \'rar\'\n    if data.startswith(b\'7z\\xbc\\xaf\\x27\\x1c\'):return \'7z\'\n    if data.startswith(bytes.fromhex(\'D0CF11E0A1B11AE1\')):return \'ole-office\'\n    if prefix[:32].lower().startswith((b\'<!doctype html\', b\'<html\', b\'<?xml\',b\'<head\',b\'<body\')):return \'html-xml\'\n    if prefix.startswith((b\'{\',b\'[\')) and (b\'"\' in prefix[:120] or b\'error\' in prefix[:200].lower()):return \'json\'\n    return \'desconocido\'\n\ndef safe_response_url(url):\n    parsed=urlparse(str(url))\n    # No incluir tokens de consulta ni fragmentos en archivos de diagnóstico.\n    return parsed._replace(query=\'\',fragment=\'\').geturl()\n\ndef _response_excerpt(data):\n    """Pequeño fragmento desprovisto de HTML para indicar causa del error."""\n    text=data[:1200].decode(\'utf-8\',errors=\'replace\')\n    text=re.sub(r\'<[^>]+>\',\' \',text)\n    text=re.sub(r\'(?i)(authorization|access_token|api_key|token|password)["\\s:=]+[^\\s,;<>]+\',r\'\\1=[reservado]\',text)\n    return \' \'.join(text.split())[:360]\n\ndef _extension_by_signature(kind,expected,stream_path):\n    if kind==\'rar\':return \'.rar\'\n    if kind==\'pdf\':return \'.pdf\'\n    if kind==\'7z\':return \'.7z\'\n    if kind==\'ole-office\':return expected if expected in (\'.doc\',\'.xls\',\'.ppt\') else \'.bin\'\n    if kind==\'zip-office\':\n        # ZIP is the real container format of XLSX/DOCX/PPTX. Classify by\n        # package members, never by the Content-Type reported by an API proxy.\n        import zipfile\n        try:\n            if not zipfile.is_zipfile(stream_path):\n                raise ValueError(\'La respuesta empieza con PK pero no es ZIP válido\')\n            with zipfile.ZipFile(stream_path) as archive:\n                names=set(archive.namelist())\n                if not names:\n                    raise ValueError(\'El ZIP descargado está vacío\')\n                # Validate CRC of reasonably sized attachments; larger files\n                # retain the structural validation without a second full read.\n                if Path(stream_path).stat().st_size<=32*1024*1024:\n                    corrupt=archive.testzip()\n                    if corrupt:\n                        raise ValueError(\'CRC incorrecto en archivo ZIP: \'+corrupt[:100])\n                if \'xl/workbook.xml\' in names:\n                    content_type_xml=archive.read(\'[Content_Types].xml\') if \'[Content_Types].xml\' in names else b\'\'\n                    if b\'macroEnabled\' in content_type_xml:\n                        return \'.xlsm\'\n                    return \'.xlsx\'\n                if \'word/document.xml\' in names:return \'.docx\'\n                if \'ppt/presentation.xml\' in names:return \'.pptx\'\n                if \'xl/workbook.bin\' in names:return \'.xlsb\'\n        except (OSError,zipfile.BadZipFile,RuntimeError) as ex:\n            raise ValueError(\'ZIP/Office incompleto o dañado: \'+str(ex)) from ex\n        return \'.zip\'\n    return expected\n\ndef download_diagnostic(session, url, target, expected_suffix, alternatives=(), progress=None):\n    """Descarga verificada, diferenciando fallas HTTP, red, HTML y archivo real.\n\n    Sólo usa el endpoint documental oficial y los enlaces explícitos de metadatos\n    BDIT. No convierte respuestas de error HTML/JSON en archivos .rar/.zip.\n    """\n    target=Path(target)\n    expected_suffix=str(expected_suffix or \'.bin\').lower()\n    record={\'url_solicitada\':safe_response_url(url),\'intentos\':[],\'estado\':\'ERROR\',\n            \'extension_esperada\':expected_suffix}\n    target.parent.mkdir(parents=True,exist_ok=True)\n    seen=set();candidates=[]\n    for raw in [url, str(url).rstrip(\'/\')+\'/\', *alternatives]:\n        candidate=str(raw or \'\').strip()\n        parsed=urlparse(candidate)\n        if parsed.scheme!=\'https\' or not parsed.hostname or parsed.username or parsed.password:\n            continue\n        if candidate not in seen:\n            seen.add(candidate);candidates.append(candidate)\n    for idx,candidate in enumerate(candidates,1):\n        attempt={\'url\':safe_response_url(candidate)}\n        record[\'intentos\'].append(attempt)\n        tmp=target.with_name(target.name+\'.lineatx_part\')\n        try:\n            if progress:progress(f\'Intento {idx}/{len(candidates)} · {attempt["url"]}\')\n            with session.get(candidate,headers={\'Accept\':\'application/octet-stream,application/pdf,application/x-rar-compressed,application/zip,*/*;q=0.5\',\n                                                \'User-Agent\':\'LineaTx/21.0\'},timeout=(18,90),stream=True,allow_redirects=True) as r:\n                attempt.update({\'http\':r.status_code,\'url_final\':safe_response_url(r.url),\n                    \'content_type\':r.headers.get(\'Content-Type\',\'\'),\n                    \'content_disposition\':r.headers.get(\'Content-Disposition\',\'\'),\n                    \'content_length\':r.headers.get(\'Content-Length\',\'\'),\n                    \'redirecciones\':[{\'http\':h.status_code,\'url\':safe_response_url(h.url)} for h in r.history]})\n                if progress:progress(f\'HTTP {r.status_code} · {r.headers.get("Content-Type", "sin tipo")}\')\n                if r.status_code>=400:\n                    # No leer un archivo gigante en caso de error.\n                    try:sample=next(r.iter_content(chunk_size=1200),b\'\')\n                    except Exception:sample=b\'\'\n                    attempt[\'respuesta_servidor\']=_response_excerpt(sample)\n                    reason={401:\'Acceso no autorizado\',403:\'Acceso denegado\',404:\'Documento no disponible en el servidor\',\n                            429:\'Servidor limita peticiones\',500:\'Falla interna del servidor\',502:\'Servidor intermedio sin respuesta\',\n                            503:\'Servicio temporalmente no disponible\',504:\'Tiempo de espera del servidor\'}.get(r.status_code,\'Error HTTP\')\n                    attempt[\'error\']=f\'{reason} (HTTP {r.status_code})\'\n                    continue\n                if not (200<=r.status_code<300):\n                    attempt[\'error\']=f\'Respuesta HTTP {r.status_code} inesperada\';continue\n                # No cargar todo el documento en memoria.\n                total=0;first=b\'\'\n                declared=r.headers.get(\'Content-Length\')\n                if declared and declared.isdecimal() and int(declared)>600*1024*1024:\n                    attempt[\'error\']=\'El archivo supera el límite de 600 MB\';continue\n                with tmp.open(\'wb\') as f:\n                    for chunk in r.iter_content(chunk_size=128*1024):\n                        if not chunk:continue\n                        if len(first)<2048:first+=chunk[:2048-len(first)]\n                        total+=len(chunk)\n                        if total>600*1024*1024:raise ValueError(\'La descarga supera 600 MB\')\n                        f.write(chunk)\n                kind=signature_type(first)\n                attempt.update({\'bytes_recibidos\':total,\'firma\':kind,\'primeros_bytes_hex\':first[:16].hex()})\n                if not total:\n                    attempt[\'error\']=\'Documento vacío\';continue\n                content_type=attempt[\'content_type\'].lower()\n                # IMPORTANT: Some BDIT download endpoints send HTTP 200 and\n                # Content-Type: text/html for a *real* XLSX/ZIP (PK signature).\n                # Headers alone are not trustworthy: identify actual content.\n                if kind in (\'html-xml\',\'json\'):\n                    attempt[\'respuesta_servidor\']=_response_excerpt(first)\n                    attempt[\'error\']=f\'El servidor devolvió contenido {kind}, no un documento ({content_type})\'\n                    continue\n                if kind==\'desconocido\' and any(x in content_type for x in (\'text/html\',\'application/json\')):\n                    attempt[\'respuesta_servidor\']=_response_excerpt(first)\n                    attempt[\'error\']=f\'Contenido no reconocible; servidor declara {content_type}\'\n                    continue\n                # Control de firmas para archivos cuyo formato está declarado.\n                if expected_suffix in (\'.rar\',\'.zip\',\'.xlsx\',\'.xlsm\',\'.docx\',\'.pdf\',\'.7z\',\'.xls\',\'.doc\',\'.ppt\'):\n                    allowed={\'rar\',\'zip-office\',\'pdf\',\'7z\',\'ole-office\'}\n                    if kind not in allowed:\n                        attempt[\'error\']=f\'La respuesta no tiene firma de archivo ({kind})\';continue\n                actual=_extension_by_signature(kind,expected_suffix,tmp)\n                # Keep a trace when BDIT/its proxy declares a misleading MIME.\n                if kind in (\'zip-office\',\'rar\',\'pdf\',\'7z\',\'ole-office\') and any(\n                        x in content_type for x in (\'text/html\',\'application/json\')):\n                    attempt[\'aviso_mime\']=\'Cabecera HTTP incorrecta: \'+content_type\n                    record[\'aviso_mime\']=f\'BDIT declaró {content_type}, pero se validó archivo {actual} por contenido\'\n                if actual==\'.bin\' and expected_suffix!=\'.bin\':\n                    attempt[\'error\']=\'Formato binario no reconocible\';continue\n                final=target.with_suffix(actual) if actual!=expected_suffix else target\n                tmp.replace(final)\n                record.update({\'estado\':\'OK\',\'archivo\':str(final),\'bytes\':total,\n                               \'extension_detectada\':actual,\'url_final\':safe_response_url(r.url)})\n                if actual!=expected_suffix:record[\'aviso_extension\']=f\'Extensión declarada {expected_suffix}, contenido real {actual}\'\n                return record\n        except Exception as ex:\n            attempt[\'error\']=f\'{type(ex).__name__}: {str(ex)[:320]}\'\n        finally:\n            try:tmp.unlink(missing_ok=True)\n            except OSError:pass\n    record[\'error\']=\' | \'.join(f"HTTP {a.get(\'http\',\'-\')}: {a.get(\'error\',\'Respuesta no válida\')}" for a in record[\'intentos\'])\n    return record\n\nclass App(ttk.Frame):\n    def __init__(self, parent=None):\n        super().__init__(parent)\n        self.lines=[]; self.sections=[]; self.index={}; self.documents={}; self.selected=set()\n        self.events=queue.Queue(); self.busy=False; self.filtered=[]; self.last_download_folder=None\n        self.extracted_by_archive={}  # archivo original -> archivos extraídos vigentes\n        self.search_mode=tk.StringVar(value=\'linea\')\n        self.selected_section_ids=set()\n        self.active_sections={}  # ID ST -> ID línea BDIT verificado\n        self.section_lookup={}\n        self.section_line_lookup={}\n        self.line_lookup={}\n        self.section_candidates=[]\n        self.session=requests.Session()\n        # Entorno corporativo: verificar certificados desactivado para BDIT.\n        self.session.verify = getattr(__import__(\'__main__\'), \'TLS_VERIFY\', True)\n        # Reintentos automáticos solo ante fallas transitorias de red/servidor.\n        from requests.adapters import HTTPAdapter\n        from urllib3.util.retry import Retry\n        retries=Retry(total=2,connect=2,read=0,backoff_factor=0.7,\n                      status_forcelist=(429,500,502,503,504),allowed_methods=frozenset({\'GET\'}),\n                      respect_retry_after_header=True)\n        self.session.mount(\'https://\',HTTPAdapter(max_retries=retries))\n        self.make_ui()\n        self.after(100, self.poll)\n\n    def make_ui(self):\n        # Flujo visible: consultar API -> buscar -> documentos -> descarga -> trazar -> comparar.\n        header=ttk.Frame(self,padding=(18,12,18,7));header.pack(fill=\'x\')\n        ttk.Label(header,text=\'Buscar líneas o secciones tramo\',style=\'PageTitle.TLabel\').pack(anchor=\'w\')\n        ttk.Label(header,text=\'Consulta BDIT y elige una línea completa o solo las secciones que necesitas.\',style=\'Subtitle.TLabel\').pack(anchor=\'w\')\n\n        search_card=ttk.Frame(self,style=\'Card.TFrame\',padding=(16,13))\n        search_card.pack(fill=\'x\',padx=16,pady=(2,9))\n        api_row=ttk.Frame(search_card,style=\'Card.TFrame\');api_row.pack(fill=\'x\',pady=(0,8))\n        self.btn_api=ttk.Button(api_row,text=\'1 · Consultar API Líneas\',style=\'Primary.TButton\',command=self.load_catalog)\n        self.btn_api.pack(side=\'left\',padx=(0,12))\n        ttk.Label(api_row,text=\'Carga el catálogo de líneas y secciones desde BDIT.\',style=\'CardStatus.TLabel\').pack(side=\'left\')\n        mode_row=ttk.Frame(search_card,style=\'Card.TFrame\');mode_row.pack(fill=\'x\',pady=(0,8))\n        ttk.Label(mode_row,text=\'Quiero buscar:\',style=\'CardLabel.TLabel\').pack(side=\'left\',padx=(0,10))\n        ttk.Radiobutton(mode_row,text=\'Una línea completa\',variable=self.search_mode,value=\'linea\',command=self.change_search_mode).pack(side=\'left\',padx=(0,14))\n        ttk.Radiobutton(mode_row,text=\'Una o varias secciones tramo\',variable=self.search_mode,value=\'secciones\',command=self.change_search_mode).pack(side=\'left\')\n        self.line_row=ttk.Frame(search_card,style=\'Card.TFrame\')\n        row=self.line_row;row.pack(fill=\'x\')\n        ttk.Label(row,text=\'2 · Buscar por ID o nombre\',style=\'CardLabel.TLabel\').pack(side=\'left\',padx=(0,10))\n        self.search=tk.StringVar()\n        self.search_entry=ttk.Entry(row,textvariable=self.search,width=31,state=\'disabled\')\n        self.search_entry.pack(side=\'left\',fill=\'x\',expand=True,padx=(0,12))\n        self.search_entry.bind(\'<Return>\',lambda e:self.quick_consult())\n        self.btn_docs=ttk.Button(row,text=\'3 · Ver documentos\',command=self.quick_consult,state=\'disabled\')\n        self.btn_docs.pack(side=\'left\')\n        menu_button=ttk.Menubutton(row,text=\'⋯  Opciones\')\n        menu_button.pack(side=\'left\',padx=(9,0))\n        menu=tk.Menu(menu_button,tearoff=0)\n        menu.add_command(label=\'Volver a consultar API Líneas\',command=self.load_catalog)\n        menu.add_command(label=\'Explorar ZIP/RAR descargados\',command=self.browse_downloaded_zip)\n        menu.add_separator()\n        menu.add_command(label=\'Clasificar archivos descargados\',command=self.analyze_folder)\n        menu.add_command(label=\'Extraer coordenadas (CSV de control)\',command=self.extract_coordinates)\n        menu.add_command(label=\'Exportar inventario CSV\',command=self.export_csv)\n        menu_button[\'menu\']=menu\n        self.suggestions=ttk.Frame(search_card,style=\'Card.TFrame\')\n        self.suggestions.pack(fill=\'x\',pady=(9,0))\n        ttk.Label(self.suggestions,text=\'Línea BDIT:\',style=\'CardLabel.TLabel\').pack(side=\'left\',padx=(0,8))\n        self.combo=ttk.Combobox(self.suggestions,state=\'disabled\',width=72)\n        self.combo.pack(side=\'left\',fill=\'x\',expand=True)\n        self.combo.bind(\'<<ComboboxSelected>>\',lambda e:self.choose_suggestion())\n        self.search.trace_add(\'write\',lambda *_:self.update_line_suggestions())\n        self.section_panel=ttk.Frame(search_card,style=\'Card.TFrame\')\n        section_search_row=ttk.Frame(self.section_panel,style=\'Card.TFrame\');section_search_row.pack(fill=\'x\',pady=(1,6))\n        ttk.Label(section_search_row,text=\'Buscar ST por ID o nombre:\',style=\'CardLabel.TLabel\').pack(side=\'left\',padx=(0,9))\n        self.section_search=tk.StringVar()\n        self.section_entry=ttk.Entry(section_search_row,textvariable=self.section_search,width=26,state=\'disabled\')\n        self.section_entry.pack(side=\'left\',fill=\'x\',expand=True,padx=(0,7))\n        self.section_entry.bind(\'<Return>\',lambda e:self.add_section_by_query())\n        self.section_combo=ttk.Combobox(self.section_panel,state=\'disabled\',height=12)\n        self.section_combo.pack(fill=\'x\',pady=(0,7))\n        self.section_combo.bind(\'<<ComboboxSelected>>\',lambda e:self.add_selected_section())\n        self.section_search.trace_add(\'write\',lambda *_:self.update_section_suggestions())\n        section_buttons=ttk.Frame(self.section_panel,style=\'Card.TFrame\');section_buttons.pack(fill=\'x\',pady=(1,5))\n        self.btn_add_section=ttk.Button(section_buttons,text=\'Agregar sección\',command=self.add_selected_section)\n        self.btn_add_section.pack(side=\'left\',padx=(0,8))\n        ttk.Button(section_buttons,text=\'Quitar seleccionada\',command=self.remove_selected_section).pack(side=\'left\',padx=(0,8))\n        self.btn_section_docs=ttk.Button(section_buttons,text=\'Ver documentos seleccionados\',style=\'Primary.TButton\',command=self.consult_selected_sections)\n        self.btn_section_docs.pack(side=\'right\')\n        selected_frame=ttk.Frame(self.section_panel,style=\'Card.TFrame\');selected_frame.pack(fill=\'x\')\n        self.selected_section_tree=ttk.Treeview(selected_frame,columns=(\'st\',\'name\',\'line\'),show=\'headings\',height=3,selectmode=\'extended\')\n        for col,label,width,stretch in [(\'st\',\'Sección\',90,False),(\'name\',\'Nombre sección tramo\',400,True),(\'line\',\'Línea BDIT\',110,False)]:\n            self.selected_section_tree.heading(col,text=label)\n            self.selected_section_tree.column(col,width=width,stretch=stretch)\n        self.selected_section_tree.pack(fill=\'x\',expand=True)\n        self.summary=tk.StringVar(value=\'Paso 1: pulsa «Consultar API Líneas».\')\n        self.summary_label=ttk.Label(search_card,textvariable=self.summary,style=\'CardStatus.TLabel\')\n        self.summary_label.pack(anchor=\'w\',pady=(8,0))\n        self.pending_lookup=None\n        self.filtered=[]\n        self.on_line_selected=None\n        self.on_trace_ready=None\n\n        results=ttk.Frame(self,padding=(16,0,16,3));results.pack(fill=\'both\',expand=True)\n        self.action_bar=ttk.Frame(results)\n        self.btn_download=ttk.Button(self.action_bar,text=\'4 · Descargar seleccionados\',style=\'Primary.TButton\',command=self.download_selected)\n        self.btn_download.pack(side=\'left\',padx=(0,10))\n        self.read_draw_btn=ttk.Button(self.action_bar,text=\'5 · Leer anexos y dibujar\',\n                                      command=self.read_and_draw, state=\'disabled\')\n        self.read_draw_btn.pack(side=\'left\',padx=(2,12))\n        pick=ttk.Menubutton(self.action_bar,text=\'Seleccionar  ▾\')\n        pick.pack(side=\'left\')\n        picker=tk.Menu(pick,tearoff=0)\n        picker.add_command(label=\'Marcar más recientes (solo si lo eliges)\',command=self.select_latest)\n        picker.add_command(label=\'Todos los documentos\',command=lambda:self.set_all(True))\n        picker.add_command(label=\'Quitar selección\',command=lambda:self.set_all(False))\n        pick[\'menu\']=picker\n        self.selection_status=tk.StringVar(value=\'\')\n        ttk.Label(self.action_bar,textvariable=self.selection_status,style=\'Subtitle.TLabel\').pack(side=\'right\')\n        self.results_tabs=ttk.Notebook(results)\n        self.results_tabs.pack(fill=\'both\',expand=True,pady=(6,0))\n        documents_frame=ttk.Frame(self.results_tabs,padding=5)\n        sections_frame=ttk.Frame(self.results_tabs,padding=5)\n        self.results_tabs.add(documents_frame,text=\'Documentos\')\n        self.results_tabs.add(sections_frame,text=\'Secciones\')\n        ttk.Label(documents_frame,text=\'Orden: cargas más recientes por sección tramo. Ningún archivo se marca automáticamente. Doble clic para elegir.\',style=\'Subtitle.TLabel\').pack(anchor=\'w\',pady=(0,5))\n        doc_table=ttk.Frame(documents_frame);doc_table.pack(fill=\'both\',expand=True)\n        cols=(\'sel\',\'lid\',\'sid\',\'date\',\'latest\',\'id\',\'ext\',\'name\')\n        self.doc_tree=ttk.Treeview(doc_table,columns=cols,show=\'headings\',selectmode=\'extended\')\n        for col,label,width,stretch in [\n            (\'sel\',\'\',43,False),(\'lid\',\'Línea BDIT\',95,False),(\'sid\',\'Sección\',85,False),(\'date\',\'Fecha de modificación\',155,False),\n            (\'latest\',\'Carga reciente\',106,False),(\'id\',\'ID documento\',105,False),(\'ext\',\'Ext.\',105,False),(\'name\',\'Documento\',430,True)]:\n            self.doc_tree.heading(col,text=label)\n            self.doc_tree.column(col,width=width,minwidth=40,stretch=stretch,anchor=\'w\')\n        y=ttk.Scrollbar(doc_table,orient=\'vertical\',command=self.doc_tree.yview)\n        x=ttk.Scrollbar(doc_table,orient=\'horizontal\',command=self.doc_tree.xview)\n        self.doc_tree.configure(yscrollcommand=y.set,xscrollcommand=x.set)\n        doc_table.grid_rowconfigure(0,weight=1);doc_table.grid_columnconfigure(0,weight=1)\n        self.doc_tree.grid(row=0,column=0,sticky=\'nsew\');y.grid(row=0,column=1,sticky=\'ns\');x.grid(row=1,column=0,sticky=\'ew\')\n        self.doc_tree.bind(\'<Double-1>\',self.toggle_doc)\n        sec_table=ttk.Frame(sections_frame);sec_table.pack(fill=\'both\',expand=True)\n        self.sect=ttk.Treeview(sec_table,columns=(\'id\',\'name\',\'line\',\'relation\'),show=\'headings\')\n        for col,label,width in [(\'id\',\'ID sección\',110),(\'name\',\'Nombre sección tramo\',560),(\'line\',\'Línea BDIT\',125),(\'relation\',\'Relación\',175)]:\n            self.sect.heading(col,text=label);self.sect.column(col,width=width,anchor=\'w\',stretch=col==\'name\')\n        sy=ttk.Scrollbar(sec_table,orient=\'vertical\',command=self.sect.yview)\n        sx=ttk.Scrollbar(sec_table,orient=\'horizontal\',command=self.sect.xview)\n        self.sect.configure(yscrollcommand=sy.set,xscrollcommand=sx.set)\n        sec_table.grid_rowconfigure(0,weight=1);sec_table.grid_columnconfigure(0,weight=1)\n        self.sect.grid(row=0,column=0,sticky=\'nsew\');sy.grid(row=0,column=1,sticky=\'ns\');sx.grid(row=1,column=0,sticky=\'ew\')\n\n        foot=ttk.Frame(self,padding=(17,7,17,9));foot.pack(fill=\'x\')\n        self.status=tk.StringVar(value=\'Listo para consultar.\')\n        ttk.Label(foot,textvariable=self.status,style=\'Status.TLabel\').pack(side=\'left\',fill=\'x\',expand=True)\n        self.progress=ttk.Progressbar(foot,mode=\'indeterminate\',length=145)\n        self.progress.pack(side=\'right\')\n        self.activity_open=False\n        self.activity_frame=ttk.Frame(self,padding=(17,2,17,7))\n        self.activity=tk.Text(self.activity_frame,height=7,wrap=\'word\',font=(\'Consolas\',9),state=\'disabled\')\n        self.activity.pack(fill=\'both\',expand=True)\n        self.activity_button=ttk.Button(foot,text=\'Ver actividad  ▾\',command=self.toggle_activity)\n        self.activity_button.pack(side=\'right\',padx=(0,14))\n\n    def toggle_activity(self):\n        self.activity_open=not self.activity_open\n        if self.activity_open:\n            self.activity_frame.pack(fill=\'x\')\n            self.activity_button.configure(text=\'Ocultar actividad  ▴\')\n        else:\n            self.activity_frame.pack_forget()\n            self.activity_button.configure(text=\'Ver actividad  ▾\')\n\n    def append_activity(self,message):\n        self.activity.configure(state=\'normal\')\n        self.activity.insert(\'end\',f\'[{datetime.now():%H:%M:%S}] {message}\\n\')\n        self.activity.see(\'end\')\n        self.activity.configure(state=\'disabled\')\n\n    def quick_consult(self):\n        if self.search_mode.get()==\'secciones\':\n            return self.consult_selected_sections()\n        if self.busy:return\n        query=self.search.get().strip()\n        if not query:\n            messagebox.showinfo(\'Buscar línea\',\'Escribe un ID o nombre de línea.\',parent=self);return\n        if not self.lines:\n            self.summary.set(\'Primero pulsa «Consultar API Líneas» para obtener el catálogo.\');return\n        exact=[row for row in self.lines if clean_id(row.get(\'id\'))==query]\n        candidates=exact or [row for row in self.lines if query.casefold() in\n                   (clean_id(row.get(\'id\'))+\' \'+str(row.get(\'nombre\') or row.get(\'name\') or \'\')).casefold()]\n        candidates=sorted(candidates,key=lambda row:clean_id(row.get(\'id\')))[:500]\n        if not candidates:\n            self.summary.set(\'No se encontró la línea. Revisa su ID o actualiza el catálogo.\');return\n        self.filtered=candidates\n        self.combo[\'values\']=[f"{clean_id(row.get(\'id\'))} | {row.get(\'nombre\') or row.get(\'name\') or \'Sin nombre\'}" for row in candidates]\n        if len(candidates)>1:\n            self.combo.set(\'\');self.summary.set(f\'{len(candidates)} coincidencias: elige una de la lista desplegable.\');return\n        self.combo.current(0);self.choose_suggestion()\n\n    def choose_suggestion(self):\n        if self.busy or self.search_mode.get()!=\'linea\':return\n        self.select_line()\n        line=self.current_line()\n        if line and callable(self.on_line_selected):self.on_line_selected(clean_id(line.get(\'id\')))\n        if self.sect.get_children():\n            self.results_tabs.select(0)\n            self.load_documents()\n        else:self.summary.set(\'La línea no tiene secciones asociadas en el catálogo BDIT.\')\n\n    def update_line_suggestions(self):\n        # Búsqueda local después de consultar API. No borra documentos ya visualizados.\n        if not self.lines:return\n        q=self.search.get().strip().casefold()\n        matches=[row for row in self.lines if q in\n                 (clean_id(row.get(\'id\'))+\' \'+str(row.get(\'nombre\') or row.get(\'name\') or \'\')).casefold()]\n        self.filtered=sorted(matches,key=lambda x:(str(x.get(\'nombre\') or \'\').casefold(),clean_id(x.get(\'id\'))))[:2000]\n        self.combo[\'values\']=[f"{clean_id(row.get(\'id\'))} | {row.get(\'nombre\') or row.get(\'name\') or \'Sin nombre\'}" for row in self.filtered]\n        self.combo.set(\'\')\n        if q and not matches:self.summary.set(\'Sin coincidencias en el catálogo consultado.\')\n        elif q:self.summary.set(f\'{len(matches)} líneas coincidentes. Selecciona una o pulsa «Ver documentos».\')\n\n    def change_search_mode(self):\n        """Alterna la busqueda sin usar \'before\' sobre widgets retirados.\n\n        Tkinter exige que la referencia de \'before\' este actualmente\n        gestionada por pack. summary_label es el ancla estable de ambas\n        vistas; los paneles opcionales se vuelven a insertar antes de ella.\n        """\n        if self.busy:\n            return\n        section_mode = self.search_mode.get() == \'secciones\'\n        # Estado consistente incluso con alternancias rapidas o repetidas.\n        for panel in (self.line_row, self.suggestions, self.section_panel):\n            if panel.winfo_manager() == \'pack\':\n                panel.pack_forget()\n        if section_mode:\n            self.section_panel.pack(fill=\'x\', pady=(5, 0), before=self.summary_label)\n        else:\n            self.line_row.pack(fill=\'x\', before=self.summary_label)\n            self.suggestions.pack(fill=\'x\', pady=(9, 0), before=self.summary_label)\n        self.documents={};self.selected=set();self.active_sections={}\n        self.sect.delete(*self.sect.get_children())\n        self.doc_tree.delete(*self.doc_tree.get_children())\n        self.render_docs()\n        self.summary.set(\'Busca y agrega una o varias secciones tramo.\' if section_mode else \'Busca una línea BDIT por ID o nombre.\')\n        if self.action_bar.winfo_manager():self.action_bar.pack_forget()\n        self.read_draw_btn.configure(state=\'disabled\')\n\n    def update_section_suggestions(self):\n        if not self.sections:return\n        q=self.section_search.get().strip().casefold()\n        if not q:\n            self.section_candidates=[];self.section_combo[\'values\']=[];self.section_combo.set(\'\');return\n        candidates=[]\n        for section in self.sections:\n            sid=clean_id(section.get(\'id\'))\n            name=str(section.get(\'nombre\') or section.get(\'name\') or \'\')\n            if q in (sid+\' \'+name).casefold():candidates.append(section)\n        candidates.sort(key=lambda row:(clean_id(row.get(\'id\'))!=q,str(row.get(\'nombre\') or \'\')))\n        self.section_candidates=candidates[:500]\n        self.section_combo[\'values\']=[f"{clean_id(x.get(\'id\'))} | {x.get(\'nombre\') or x.get(\'name\') or \'Sin nombre\'}" for x in self.section_candidates]\n        self.section_combo.set(\'\')\n        self.summary.set(f\'{len(candidates)} secciones coincidentes. Agrégalas a la selección.\' if candidates else \'No se encontraron secciones para la búsqueda.\')\n\n    def add_section_by_query(self):\n        if self.busy:return\n        q=self.section_search.get().strip()\n        matches=[s for s in self.sections if clean_id(s.get(\'id\'))==q]\n        if len(matches)==1:\n            self._add_section(matches[0]);return\n        self.add_selected_section()\n\n    def add_selected_section(self):\n        if self.busy:return\n        ix=self.section_combo.current()\n        if ix<0 or ix>=len(self.section_candidates):\n            messagebox.showinfo(\'Elegir sección\',\'Busca y selecciona una sección de la lista.\',parent=self);return\n        self._add_section(self.section_candidates[ix])\n\n    def _add_section(self,section):\n        sid=clean_id(section.get(\'id\'))\n        lid,reason=self.section_line_lookup.get(sid,(\'\', \'Relación no verificada\'))\n        if not lid:\n            messagebox.showwarning(\'Línea no identificada\',\n                f\'Sección {sid}: {reason}\\n\\nNo se asociará a una línea por suposición. Comprueba los datos en BDIT.\',parent=self)\n            self.append_activity(f\'REVISAR ST {sid}: {reason}\')\n            return\n        if sid in self.selected_section_ids:\n            self.summary.set(f\'La sección {sid} ya está seleccionada.\');return\n        self.selected_section_ids.add(sid)\n        name=section.get(\'nombre\') or section.get(\'name\') or \'\'\n        self.selected_section_tree.insert(\'\', \'end\',iid=sid,values=(sid,name,lid))\n        groups=len({self.section_line_lookup[x][0] for x in self.selected_section_ids})\n        self.summary.set(f\'{len(self.selected_section_ids)} secciones elegidas · {groups} línea(s) BDIT. Cada línea tendrá su propia carpeta LT<ID>.\')\n\n    def remove_selected_section(self):\n        for sid in self.selected_section_tree.selection():\n            self.selected_section_tree.delete(sid)\n            self.selected_section_ids.discard(sid)\n        self.summary.set(f\'{len(self.selected_section_ids)} secciones seleccionadas.\')\n\n    def consult_selected_sections(self):\n        if self.busy:return\n        if not self.lines or not self.sections:\n            messagebox.showinfo(\'Consultar BDIT\',\'Pulsa primero «Consultar API Líneas».\',parent=self);return\n        if not self.selected_section_ids:\n            messagebox.showinfo(\'Elegir secciones\',\'Agrega una o varias secciones tramo antes de continuar.\',parent=self);return\n        sections={sid:self.section_line_lookup[sid][0] for sid in sorted(self.selected_section_ids)}\n        self._activate_sections(sections)\n        self.results_tabs.select(0)\n        self.load_documents()\n\n    def _activate_sections(self, sections):\n        self.active_sections=dict(sections)\n        self.documents={};self.selected=set();self.last_download_folder=None\n        self.sect.delete(*self.sect.get_children());self.doc_tree.delete(*self.doc_tree.get_children())\n        for sid,lid in sections.items():\n            section=self.section_lookup.get(sid,{})\n            self.sect.insert(\'\', \'end\',iid=sid,values=(sid,section.get(\'nombre\') or section.get(\'name\') or \'\',lid,\'Relación API verificada\'))\n        self.render_docs()\n        gids=sorted(set(sections.values()))\n        self.summary.set(f\'{len(sections)} ST seleccionadas · líneas BDIT: {", ".join(gids)}. Archivos separados por LT.\')\n        self.read_draw_btn.configure(state=\'normal\' if any(self.output_folder(lid).exists() for lid in gids) else \'disabled\')\n\n    def active_line_ids(self):\n        return sorted(set(self.active_sections.values()))\n\n    def active_line_folders(self):\n        return [self.output_folder(lid) for lid in self.active_line_ids()]\n\n    def read_and_draw(self):\n        if self.busy:return\n        groups={lid:{sid for sid,owner in self.active_sections.items() if owner==lid} for lid in self.active_line_ids()}\n        if not groups:\n            messagebox.showwarning(\'Sin selección\',\'Selecciona una línea o una o varias secciones tramo.\',parent=self);return\n        from visor_lde_archivos import build_trace,save_trace,EXTENSIONS\n        tasks=[]\n        for lid,sections in groups.items():\n            folder=self.output_folder(lid)\n            if not folder.is_dir():continue\n            if self.search_mode.get()==\'secciones\':\n                # Solo ST seleccionadas, nunca anexos antiguos de otras ST de esta línea.\n                roots=[folder/f\'ST_{sid}\' for sid in sections]\n            else:roots=[folder]\n            loose=[]\n            for root in roots:\n                if not root.is_dir():continue\n                loose.extend(p for p in root.rglob(\'*\') if p.is_file() and p.suffix.lower() in EXTENSIONS\n                       and \'.cache\' not in p.relative_to(folder).parts\n                       and \'ANEXOS_EXTRAIDOS\' not in p.relative_to(folder).parts\n                       and not p.name.lower().startswith((\'reporte_\',\'~$\')))\n            extracted=[]\n            for archive,files in self.extracted_by_archive.items():\n                parent=Path(archive).parent\n                if not any(parent==r or (r in parent.parents) for r in roots):continue\n                extracted.extend(p for p in files if p.is_file() and p.suffix.lower() in EXTENSIONS)\n            paths=list(dict.fromkeys([*loose,*extracted]))\n            if paths:tasks.append((lid,folder,paths))\n            else:self.append_activity(f\'LT {lid}: no hay anexos LDE legibles de las ST seleccionadas.\')\n        if not tasks:\n            messagebox.showwarning(\'Sin anexos legibles\',\'Descarga y selecciona los LDE de las secciones elegidas.\',parent=self);return\n        def job():\n            import json\n            for lid,folder,paths in tasks:\n                def progress(i,total,msg):self.events.put((\'status\',f\'LT {lid} · Anexos {i}/{total}: {msg}\'))\n                result=build_trace(sorted(paths),progress=progress)\n                n=result[\'totals\'][\'vertices\']\n                if not n:\n                    self.events.put((\'status\',f\'LT {lid}: anexos sin estructuras georreferenciables.\'));continue\n                geo,csv=save_trace(result,folder/f\'Trazado_Anexos_LT{lid}.geojson\')\n                pts=[{\'st\':p.get(\'seccion_bdit\') or p.get(\'st\') or \'\', \'lon\':p[\'lon\'],\'lat\':p[\'lat\'],\n                      \'nombre\':p.get(\'nombre\') or \'\', \'estado\':\'SIN_CONTRASTE_BDATX\',\'id_torre\':None,\n                      \'este\':p.get(\'este\'),\'norte\':p.get(\'norte\'),\'huso\':p.get(\'huso\'),\'archivo\':p.get(\'archivo\')} for p in result[\'points\']]\n                traces=[{\'st\':part.get(\'seccion\') or \'\', \'coords\':part[\'coords\'],\n                         \'nombre\':part.get(\'archivo\') or \'LDE\'} for part in result[\'paths\']]\n                segments=[{\'st\':v.get(\'seccion\') or \'\',\'a\':v[\'a\'],\'b\':v[\'b\'],\n                           \'nodo1\':v[\'desde\'],\'nodo2\':v[\'hasta\'], \'longitud_m\':v[\'longitud_m\'],\n                           \'estado\':\'REVISAR_LONGITUD\' if v[\'estado\']==\'REVISAR_SALTO\' else \'VANO_RECONSTRUIDO_LDE\'} for v in result[\'spans\']]\n                cache=folder/\'.cache\';cache.mkdir(parents=True,exist_ok=True)\n                data={\'results\':pts,\'paths\':traces,\'segments\':segments,\'bd_paths\':[],\n                      \'bd_points\':[],\'bd_segments\':[],\'document_points\':[],\'mode\':\'DOCUMENTOS_SIN_BDATX\'}\n                (cache/f\'Analisis_LT{lid}.json\').write_text(json.dumps(data,ensure_ascii=False),encoding=\'utf-8\')\n                self.events.put((\'status\',f\'LT {lid}: {len(pts)} vértices, {len(segments)} vanos. Trazado: {geo.name}\'))\n                self.events.put((\'trace_ready\',(lid,len(pts),len(segments),str(geo),str(csv))))\n        self.run_task(job)\n\n    def run_task(self, fn):\n        if self.busy:return\n        self.busy=True;self.progress.start(12)\n        self.btn_docs.configure(state=\'disabled\');self.btn_download.configure(state=\'disabled\')\n        self.btn_api.configure(state=\'disabled\');self.read_draw_btn.configure(state=\'disabled\')\n        def runner():\n            try: fn()\n            except Exception as ex:self.events.put((\'error\',str(ex)))\n            finally:self.events.put((\'done\',None))\n        threading.Thread(target=runner,daemon=True).start()\n\n    def poll(self):\n        try:\n            while True:\n                typ,payload=self.events.get_nowait()\n                if typ==\'status\':self.status.set(payload);self.append_activity(payload)\n                elif typ==\'catalog\':\n                    self.lines,self.sections,self.index=payload\n                    self.line_lookup={clean_id(l.get(\'id\')):l for l in self.lines}\n                    self.section_lookup={clean_id(st.get(\'id\')):st for st in self.sections}\n                    self.section_line_lookup={sid:resolve_section_line(st,set(self.line_lookup)) for sid,st in self.section_lookup.items()}\n                    self.update_line_suggestions();self.update_section_suggestions()\n                    self.search_entry.configure(state=\'normal\');self.combo.configure(state=\'readonly\')\n                    self.section_entry.configure(state=\'normal\');self.section_combo.configure(state=\'readonly\')\n                    self.summary.set(f\'{len(self.lines):,} líneas y {len(self.sections):,} secciones BDIT consultadas. Busca por línea o sección.\')\n                    self.search_entry.focus_set()\n                elif typ==\'docs\':\n                    self.documents=payload\n                    self.selected=set()  # Nunca preseleccionar el más reciente: decide el usuario.\n                    self.render_docs()\n                    if not self.action_bar.winfo_manager():self.action_bar.pack(fill=\'x\',pady=(0,4),before=self.results_tabs)\n                    self.results_tabs.tab(0,text=f\'Documentos ({len(payload)})\')\n                    self.results_tabs.tab(1,text=f\'Secciones ({len(self.sect.get_children())})\')\n                    self.summary.set(f\'{len(payload)} documentos ordenados por fecha de carga (más reciente primero en cada ST). Selecciona manualmente los anexos LDE.\')\n                elif typ==\'download_extension\':\n                    key,extension=payload\n                    if key in self.documents:\n                        self.documents[key][\'extension_real\']=extension\n                        self.render_docs()\n                elif typ==\'zip_downloaded\':\n                    self.after(40,lambda archives=payload:self._select_downloaded_zip_contents(archives))\n                elif typ==\'download_completed\':\n                    self.read_draw_btn.configure(state=\'normal\')\n                    self.summary.set(\'Descarga finalizada. Paso 5: pulsa «Leer anexos y dibujar».\')\n                elif typ==\'trace_ready\':\n                    line_id,n,vanos,geo,csv=payload\n                    self.summary.set(f\'Línea {line_id}: {n} vértices y {vanos} vanos dibujados. Puedes comparar las torres BDATx.\')\n                    if callable(self.on_trace_ready):self.on_trace_ready(line_id)\n                elif typ==\'error\':messagebox.showerror(\'Consulta BDIT\',payload);self.status.set(\'Error: \'+payload);self.append_activity(\'ERROR: \'+payload)\n                elif typ==\'download_summary\':\n                    ok,errors,report=payload\n                    self.append_activity(f\'RESUMEN: {len(ok)} descargados, {len(errors)} errores · Diagnóstico: {report}\')\n                    if errors:\n                        detail=\'\\n\'.join(errors[:8])\n                        if len(errors)>8:detail+=f\'\\n... y {len(errors)-8} errores adicionales.\'\n                        messagebox.showwarning(\'Descarga con errores\',\n                            f\'{len(ok)} archivos descargados; {len(errors)} errores.\\n\\n{detail}\\n\\nDetalle técnico: {report}\',parent=self)\n                    else:\n                        messagebox.showinfo(\'Descarga completada\',f\'{len(ok)} archivos guardados correctamente.\\n\\nCarpeta: {self.last_download_folder}\',parent=self)\n                elif typ==\'info\':messagebox.showinfo(\'Resultado\',payload)\n                elif typ==\'done\':\n                    self.busy=False;self.progress.stop()\n                    self.btn_api.configure(state=\'normal\')\n                    self.btn_docs.configure(state=\'normal\' if self.lines else \'disabled\')\n                    self.btn_download.configure(state=\'normal\' if self.selected else \'disabled\')\n                    if any(f.is_dir() for f in self.active_line_folders()):\n                        self.read_draw_btn.configure(state=\'normal\')\n                    if self.pending_lookup and self.lines:\n                        self.pending_lookup=None\n                        self.after(10,self.quick_consult)\n        except queue.Empty:pass\n        self.after(100,self.poll)\n\n    def load_catalog(self):\n        def job():\n            lines=fetch_catalog(self.session,\'lineas\',lambda s:self.events.put((\'status\',s)))\n            sections=fetch_catalog(self.session,\'secciones-tramos\',lambda s:self.events.put((\'status\',s)))\n            idx={}\n            for sec in sections:\n                for lid in extract_line_ids(sec):idx.setdefault(lid,[]).append(sec)\n            self.events.put((\'catalog\',(lines,sections,idx)))\n            self.events.put((\'status\',\'Catálogo BDIT de líneas y secciones cargado.\'))\n        self.run_task(job)\n\n    def output_folder(self,line_id=None):\n        if line_id is None:\n            if self.active_sections:\n                ids=self.active_line_ids()\n                if len(ids)!=1:return None\n                line_id=ids[0]\n            else:\n                line=self.current_line() if self.search_mode.get()==\'linea\' else None\n                if not line:return None\n                line_id=clean_id(line.get(\'id\'))\n        lid=clean_id(line_id)\n        if not lid or not lid.isdigit():return None\n        return Path(__file__).resolve().parent/\'DOCUMENTOS_BDIT\'/(\'LT\'+safe_filename(lid))\n\n    def filter_lines(self):\n        q=self.search.get().strip().casefold()\n        self.filtered=sorted((x for x in self.lines if q in (clean_id(x.get(\'id\'))+\' \'+str(x.get(\'nombre\') or x.get(\'name\') or \'\')).casefold()),key=lambda x:str(x.get(\'nombre\') or \'\'))[:3000]\n        labels=[f"{clean_id(x.get(\'id\'))} | {x.get(\'nombre\') or x.get(\'name\') or \'Sin nombre\'}" for x in self.filtered]\n        self.combo[\'values\']=labels\n        self.combo.set(\'\')\n        self.sect.delete(*self.sect.get_children());self.doc_tree.delete(*self.doc_tree.get_children());self.documents={};self.selected=set();self.last_download_folder=None\n\n    def current_line(self):\n        ix=self.combo.current()\n        return self.filtered[ix] if 0<=ix<len(self.filtered) else None\n\n    def select_line(self):\n        line=self.current_line()\n        if not line:return\n        lid=clean_id(line.get(\'id\'))\n        sections={clean_id(s.get(\'id\')):lid for s in self.index.get(lid,[])}\n        self._activate_sections(sections)\n        self.summary.set(f\'Línea {lid} · {line.get("nombre") or line.get("name") or ""} · {len(sections)} secciones asociadas\')\n        if not sections:self.status.set(\'Sin secciones asociadas. Comprueba relaciones de la API.\')\n\n    def load_documents(self):\n        # Capturar ST/línea antes del worker. No consultar documentos de otras ST.\n        selected=dict(self.active_sections)\n        if not selected:\n            messagebox.showwarning(\'Sin secciones\',\'Selecciona una línea o una o varias secciones tramo.\',parent=self);return\n        def job():\n            result={};failures=[]\n            for i,(sid,lid) in enumerate(selected.items(),1):\n                self.events.put((\'status\',f\'Consultando documentos {i}/{len(selected)} · LT {lid} · ST {sid}\'))\n                try:\n                    data=get_json(self.session,urljoin(BASE,f\'secciones-tramos/{sid}/documentos/\'))\n                    docs=document_items(data)\n                    if not isinstance(docs,list):raise ValueError(\'Formato documental no reconocido\')\n                    for j,d in enumerate(docs):\n                        if not isinstance(d,dict):continue\n                        key=f\'{sid}:{d.get("id",j)}:{j}\'\n                        dt,field=document_date(d)\n                        result[key]={\'line_id\':lid,\'section\':sid,\'doc\':d,\'name\':doc_name(d),\n                          \'url\':doc_url(d) or (urljoin(BASE,f\'secciones-tramos/{sid}/documentos/{d["id"]}/\') if d.get(\'id\') is not None else \'\'),\n                          \'date\':dt,\'date_field\':field}\n                except Exception as ex:failures.append(f\'LT {lid} · ST {sid}: {ex}\')\n            result=order_documents(result)\n            self.events.put((\'docs\',result))\n            undated=sum(d[\'date\'] is None for d in result.values())\n            self.events.put((\'status\',f\'{len(result)} documentos · {undated} sin fecha de modificación · {len(failures)} secciones con error\'))\n            if failures:self.events.put((\'info\',\'Consultas con error:\\n\'+\'\\n\'.join(failures[:20])))\n        self.run_task(job)\n\n    def render_docs(self):\n        self.doc_tree.delete(*self.doc_tree.get_children())\n        for key,d in self.documents.items():\n            self.doc_tree.insert(\'\', \'end\',iid=key,values=(\'☑\' if key in self.selected else \'☐\',\n                 d.get(\'line_id\',\'\'),d[\'section\'],d[\'date_label\'],\'SÍ\' if d[\'latest\'] else \'\',\n                 d[\'doc\'].get(\'id\',\'\'),d.get(\'extension_real\') or doc_extension(d[\'doc\']),d[\'name\']))\n        self.selection_status.set(f\'{len(self.selected)} de {len(self.documents)} seleccionados · elección manual\')\n        self.btn_download.configure(state=\'normal\' if self.selected and not self.busy else \'disabled\')\n\n    def toggle_doc(self,event):\n        key=self.doc_tree.identify_row(event.y)\n        if key in self.documents:\n            if key in self.selected:self.selected.remove(key)\n            else:self.selected.add(key)\n            self.render_docs()\n\n    def select_latest(self):\n        self.selected={key for key,d in self.documents.items() if d[\'latest\']}\n        self.render_docs()\n        missing={d[\'section\'] for d in self.documents.values() if d[\'date\'] is None}\n        without={sid for sid in missing if not any(d[\'latest\'] for d in self.documents.values() if d[\'section\']==sid)}\n        if without:\n            messagebox.showwarning(\'Fechas no disponibles\',\n                \'No se marcaron documentos sin fecha de modificación verificable.\\n\'\n                \'Secciones afectadas: \'+\', \'.join(sorted(without)))\n\n    def set_all(self,value):\n        self.selected=set(self.documents) if value else set();self.render_docs()\n\n    def export_csv(self):\n        if not self.documents:messagebox.showwarning(\'Sin datos\',\'Primero consulta documentos.\',parent=self);return\n        path=filedialog.asksaveasfilename(defaultextension=\'.csv\',filetypes=[(\'CSV\',\'*.csv\')],initialfile=\'inventario_documentos_bdit.csv\')\n        if not path:return\n        with open(path,\'w\',newline=\'\',encoding=\'utf-8-sig\') as f:\n            w=csv.writer(f,delimiter=\';\')\n            w.writerow([\'id_linea\',\'id_seccion\',\'id_documento\',\'nombre\',\'extension\',\'fecha_modificacion_utc\',\'campo_fecha_api\',\'es_ultimo_por_seccion\',\'url\',\'seleccionado\'])\n            for k,d in self.documents.items():\n                w.writerow([d.get(\'line_id\',\'\'),d[\'section\'],d[\'doc\'].get(\'id\',\'\'),d[\'name\'],doc_extension(d[\'doc\']),\n                  d[\'date_label\'],d[\'date_field\'],\'SI\' if d[\'latest\'] else \'NO\',d[\'url\'],\'SI\' if k in self.selected else \'NO\'])\n        messagebox.showinfo(\'Exportación\',\'Inventario guardado correctamente.\')\n\n    def analyze_folder(self):\n        folders=[folder for folder in self.active_line_folders() if folder.is_dir()]\n        if not folders:\n            folder=filedialog.askdirectory(title=\'Seleccionar carpeta LT de documentos BDIT\')\n            if not folder:return\n            folders=[Path(folder)]\n        def job():\n            for folder in folders:\n                results=inspect_folder(str(folder),lambda i,n,name:self.events.put((\'status\',f\'{folder.name} · Analizando {i}/{n}: {name}\')))\n                target=folder/\'.cache\'/\'clasificacion_contenido_bdit.csv\'\n                target.parent.mkdir(parents=True,exist_ok=True)\n                write_csv(results,target)\n                confirmed=sum(x[\'clasificacion\']==\'Confirmado\' for x in results)\n                possible=sum(x[\'clasificacion\']==\'Posible\' for x in results)\n                self.events.put((\'status\',f\'{folder.name}: {len(results)} archivos, {confirmed} confirmados, {possible} posibles. CSV: {target}\'))\n            self.events.put((\'info\',f\'Clasificación terminada para {len(folders)} carpeta(s) de línea BDIT.\'))\n        self.run_task(job)\n\n    def extract_coordinates(self):\n        folders=[folder for folder in self.active_line_folders() if folder.is_dir()]\n        if not folders:\n            folder=filedialog.askdirectory(title=\'Seleccionar carpeta LT de documentos BDIT\')\n            if not folder:return\n            folders=[Path(folder)]\n        def job():\n            for folder in folders:\n                dest,count,errors=extract_structures(str(folder),lambda i,n,name:self.events.put((\'status\',f\'{folder.name} · Extrayendo {i}/{n}: {name}\')))\n                old=Path(dest)\n                if old.is_dir() and old.parent==folder:\n                    import shutil\n                    stamp=datetime.now().strftime(\'%Y%m%d_%H%M%S_%f\')\n                    cache=folder/\'.cache\';cache.mkdir(exist_ok=True)\n                    target=cache/f\'{old.name}_{stamp}\'\n                    shutil.move(str(old),str(target));dest=target\n                self.events.put((\'status\',f\'{folder.name}: {count} registros · {errors} errores · CSV: {dest}\'))\n            self.events.put((\'info\',f\'Extracción terminada para {len(folders)} carpeta(s) BDIT; revisar alertas de coordenadas.\'))\n        self.run_task(job)\n\n    def browse_downloaded_zip(self):\n        folders=[f for f in self.active_line_folders() if f.is_dir()]\n        if not folders:\n            messagebox.showinfo(\'Sin archivos\',\'Primero descarga un ZIP o RAR de las ST elegidas.\',parent=self);return\n        archives=sorted(p for f in folders for p in [*f.rglob(\'*.zip\'),*f.rglob(\'*.rar\')])\n        if not archives:\n            messagebox.showinfo(\'Sin ZIP/RAR\',\'No se encontraron ZIP ni RAR descargados.\',parent=self);return\n        choice=filedialog.askopenfilename(parent=self,title=\'Seleccionar ZIP o RAR descargado\',\n            initialdir=str(folders[0]),filetypes=[(\'Archivos ZIP/RAR\',\'*.zip *.rar\')])\n        if choice and Path(choice).resolve() in {p.resolve() for p in archives}:\n            self._select_downloaded_zip_contents([choice])\n\n    def _select_downloaded_zip_contents(self,archives):\n        """Elección explícita tras descarga: no se extraen archivos no seleccionados."""\n        for archive in archives:\n            archive=Path(archive)\n            if not archive.is_file():continue\n            try:\n                chosen=choose_archive_members(self,archive)\n                if chosen is None:\n                    self.append_activity(\'Archivo no seleccionado: \'+archive.name)\n                    continue\n                if not chosen:\n                    self.append_activity(\'Archivo sin anexos seleccionados: \'+archive.name)\n                    continue\n                # No borrar la carpeta anterior: Windows/OneDrive puede mantenerla\n                # abierta y devolver WinError 5 incluso si el ZIP es válido.\n                dest,aviso=new_extraction_destination(archive,archive.parent/\'ANEXOS_EXTRAIDOS\')\n                try:\n                    files=extract_archive_selected(archive,chosen,dest)\n                except OSError as exc:\n                    # El destino creado puede quedar bloqueado después de abrir\n                    # el ZIP: reintentar extracción en almacenamiento local.\n                    import tempfile,os\n                    local=Path(os.environ.get(\'LOCALAPPDATA\') or tempfile.gettempdir())/\'LineaTx\'/\'ANEXOS_TEMPORALES\'\n                    if dest.is_relative_to(local):raise\n                    self.append_activity(f\'AVISO: destino OneDrive no disponible ({exc}). Probando carpeta local.\')\n                    dest,aviso=new_extraction_destination(archive,local)\n                    files=extract_archive_selected(archive,chosen,dest)\n                self.extracted_by_archive[str(archive.resolve())]=files\n                self.append_activity(f\'Archivo {archive.name}: extraídos {len(files)} documentos en {dest}\')\n                if aviso:self.append_activity(\'AVISO: \'+aviso)\n                self.status.set(f\'{len(files)} anexos listos para leer y dibujar.\')\n                self.read_draw_btn.configure(state=\'normal\')\n            except Exception as exc:\n                self.append_activity(f\'ERROR al seleccionar o extraer documentos de {archive.name}: {type(exc).__name__}: {exc}\')\n                messagebox.showerror(\'No se pudieron extraer los anexos\',\n                    f\'Archivo: {archive.name}\\n\\n{type(exc).__name__}: {exc}\\n\\n\'\n                    \'El ZIP original permanece intacto. Si la carpeta está sincronizada con OneDrive, \'\n                    \'comprueba que no esté bloqueada.\',parent=self)\n\n\n    def download_selected(self):\n        if not self.selected:\n            messagebox.showwarning(\'Sin selección\',\'Selecciona uno o varios documentos.\',parent=self);return\n        selected=[(k,d) for k,d in self.documents.items() if k in self.selected]\n        # Cada documento debe tener una única línea BDIT oficial.\n        unresolved=[d[\'section\'] for _,d in selected if clean_id(d.get(\'line_id\')) not in self.line_lookup]\n        if unresolved:\n            messagebox.showerror(\'Relación no verificada\',\n                \'No se descargará a una carpeta LT arbitraria. Verifica la línea de estas ST: \'+\', \'.join(unresolved),parent=self);return\n        groups={}\n        for key,d in selected:\n            lid=clean_id(d[\'line_id\']);groups.setdefault(lid,[]).append((key,d))\n        for lid in groups:self.output_folder(lid).mkdir(parents=True,exist_ok=True)\n        self.last_download_folder=self.output_folder(next(iter(groups))) if len(groups)==1 else None\n        self.append_activity(f\'INICIO DESCARGA · {len(selected)} documento(s) · líneas BDIT: {", ".join(groups)}\')\n        if not self.activity_open:self.toggle_activity()\n        def job():\n            ok=[];errors=[];diagnostic_by_line={lid:[] for lid in groups};errors_by_line={lid:[] for lid in groups}\n            ok_by_line={lid:[] for lid in groups}\n            counter=0\n            for lid,docs in groups.items():\n                folder=self.output_folder(lid)\n                for key,d in docs:\n                    counter+=1;doc_id=d[\'doc\'].get(\'id\');section=d[\'section\']\n                    self.events.put((\'status\',f\'Descargando {counter}/{len(selected)} · LT {lid} · ST {section} · DOC {doc_id}\'))\n                    if not doc_id:\n                        error=f\'LT {lid} ST {section} · {d["name"]}: documento sin ID\'\n                        errors.append(error);errors_by_line[lid].append(error);continue\n                    api_url=f\'https://api-infotecnica.coordinador.cl/v1/secciones-tramos/{section}/documentos/{doc_id}/\'\n                    original=safe_filename(d[\'doc\'].get(\'filename\') or d[\'name\'])\n                    suffix=Path(original).suffix.lower() or (doc_extension(d[\'doc\']) if doc_extension(d[\'doc\'])!=\'No informada\' else \'.bin\')\n                    datepart=d[\'date\'].strftime(\'%Y%m%d_%H%M%S\') if d[\'date\'] else \'SIN_FECHA\'\n                    target=folder/f\'ST_{section}\'/f\'ST{section}_DOC{doc_id}_{datepart}{suffix}\'\n                    alt=d.get(\'url\',\'\')\n                    alternatives=[alt] if alt and alt.rstrip(\'/\')!=api_url.rstrip(\'/\') else []\n                    def onprogress(msg):\n                        self.events.put((\'status\',f\'{counter}/{len(selected)} · LT {lid} ST {section} DOC {doc_id} · {msg}\'))\n                    result=download_diagnostic(self.session,api_url,target,suffix,alternatives=alternatives,progress=onprogress)\n                    result.update({\'id_linea\':lid,\'id_seccion\':section,\'id_documento\':doc_id,\n                                   \'nombre_original\':original,\'fecha_modificacion\':d[\'doc\'].get(\'fecha_modificacion\')})\n                    diagnostic_by_line[lid].append(result)\n                    if result[\'estado\']==\'OK\':\n                        ok.append(result[\'archivo\']);ok_by_line[lid].append(result[\'archivo\'])\n                        actual=result.get(\'extension_detectada\',suffix)\n                        if actual!=suffix:self.events.put((\'download_extension\',(key,actual)))\n                        self.events.put((\'status\',f\'DESCARGADO · LT {lid} ST {section} DOC {doc_id} · {Path(result["archivo"]).name}\'))\n                        if result.get(\'aviso_extension\'):self.events.put((\'status\',\'AVISO: \'+result[\'aviso_extension\']))\n                        if result.get(\'aviso_mime\'):self.events.put((\'status\',\'AVISO: \'+result[\'aviso_mime\']))\n                    else:\n                        error=f\'LT {lid} ST {section} DOC {doc_id} · {d["name"]}: {result.get("error","Descarga fallida")}\'\n                        errors.append(error);errors_by_line[lid].append(error)\n                        self.events.put((\'status\',\'ERROR DESCARGA: \'+error))\n            reports=[]\n            for lid,docs in groups.items():\n                folder=self.output_folder(lid)\n                report=folder/\'resultado_descargas.json\'\n                report.write_text(json.dumps({\'id_linea\':lid,\'carpeta\':str(folder),\'descargados\':ok_by_line[lid],\n                    \'errores\':errors_by_line[lid],\'diagnostico_http\':diagnostic_by_line[lid],\n                    \'documentos_seleccionados\':[{\'id_linea\':lid,\'id_seccion\':d[\'section\'],\n                        \'id_documento\':d[\'doc\'].get(\'id\'),\'filename\':d[\'doc\'].get(\'filename\'),\n                        \'fecha_modificacion\':d[\'doc\'].get(\'fecha_modificacion\'),\n                        \'url_descarga\':safe_response_url(d[\'url\']) if d[\'url\'] else \'\'} for _,d in docs]},\n                    ensure_ascii=False,indent=2),encoding=\'utf-8\')\n                reports.append(str(report))\n            self.events.put((\'status\',f\'Descarga finalizada: {len(ok)} correctos, {len(errors)} errores · {len(groups)} carpeta(s) LT\'))\n            archives=[p for p in ok if Path(p).suffix.lower() in (\'.zip\',\'.rar\')]\n            if archives:self.events.put((\'zip_downloaded\',archives))\n            if ok:self.events.put((\'download_completed\',len(ok)))\n            self.events.put((\'download_summary\',(ok,errors,\'\\n\'.join(reports))))\n        self.run_task(job)\n\nif __name__==\'__main__\':\n    root=tk.Tk(); root.title(\'Consulta Documental BDIT\'); App(root).pack(fill=\'both\',expand=True); root.mainloop()\n'), ('motor_conciliacion', '"""Motor canónico BDIT LDE ↔ BDATx. Sin IO, HTTP, Excel ni GUI.\n\nNODO1_ID/NODO2_ID de vano son IDs BDATx de TORRES. No son IDs de una\nentidad nodo adicional. No se deduce existencia desde semejanza nominal.\n"""\nfrom __future__ import annotations\nfrom collections import defaultdict, Counter\nfrom math import hypot\nimport re\nfrom functools import lru_cache\nfrom pyproj import Geod, Transformer\n\nUMBRAL_M = 5.0\n_GEOD=Geod(ellps=\'WGS84\')\n\n@lru_cache(maxsize=8)\ndef _to_wgs84(zone_number):\n    return Transformer.from_crs(f\'EPSG:327{zone_number}\', \'EPSG:4326\', always_xy=True)\n\ndef valid_lonlat(lon,lat):\n    return lon is not None and lat is not None and -180 <= lon <= 180 and -90 <= lat <= 90\n\n\n\ndef key(value):\n    if value is None: return \'\'\n    return str(value).strip().removesuffix(\'.0\')\n\n\ndef number(value):\n    try: return float(str(value).strip().replace(\',\', \'.\'))\n    except (ValueError, TypeError): return None\n\n\ndef zone(huso):\n    m = re.match(r\'^\\s*(18|19)\', str(huso or \'\'))\n    return int(m.group(1)) if m else None\n\n\ndef valid_utm(e, n):\n    return e is not None and n is not None and 100000 <= e <= 900000 and 1000000 <= n <= 10000000\n\n\ndef normalize_tower(tower, catalog):\n    raw = ((tower.get(\'datasheet\') or {}).get(\'coordenadasUtm\') or {})\n    original_e = number(raw.get(\'coordenadaEste\'))\n    original_n = number(raw.get(\'coordenadaNorte\'))\n    uuid = str(raw.get(\'zonaOHuso\') or \'\').strip().lower()\n    huso = catalog.get(uuid)\n    data = {\'id\': tower.get(\'id\'), \'name\': tower.get(\'name\') or tower.get(\'nombre\') or \'\',\n            \'este_raw\': original_e, \'norte_raw\': original_n, \'huso_uuid\': uuid,\n            \'huso\': huso, \'este\': None, \'norte\': None, \'lon\': None, \'lat\': None, \'metodo\': \'SIN_CORRECCION\',\n            \'estado\': \'NO_VERIFICADO\'}\n    if zone(huso) is None:\n        data[\'estado\'] = \'HUSO_NO_CATALOGADO\'\n        return data\n    if valid_utm(original_e, original_n):\n        data.update(este=original_e, norte=original_n, estado=\'UTM_VALIDO\')\n    elif valid_utm(original_n, original_e):\n        data.update(este=original_n, norte=original_e,\n                    metodo=\'INTERCAMBIO_ESTE_NORTE\', estado=\'UTM_NORMALIZADO\')\n    else:\n        data[\'estado\'] = \'COORDENADAS_UTM_INVALIDAS\'\n    if data[\'este\'] is not None:\n        z=zone(huso)\n        lon,lat=_to_wgs84(z).transform(data[\'este\'],data[\'norte\'])\n        if -85<=lon<=-60 and -58<=lat<=-15:\n            data[\'lon\'],data[\'lat\']=lon,lat\n        else:\n            data[\'estado\']=\'COORDENADAS_FUERA_ZONA_REVISAR\'\n    return data\n\n\ndef relation_ids(obj, singular, plural=None):\n    plural = plural or singular+\'s\'\n    vals=[]\n    for k in (singular+\'_id\', singular, plural, plural+\'_ids\'):\n        v=obj.get(k)\n        if v is None:continue\n        vals += v if isinstance(v,list) else [v]\n    found=set()\n    for v in vals:\n        if isinstance(v,dict):v=v.get(\'id\') or v.get(\'pk\')\n        if key(v): found.add(key(v))\n    return found\n\n\ndef tower_id_from_vano(v, end):\n    """Regla de negocio: NODO1_ID y NODO2_ID identifican TORRES BDATx."""\n    val=v.get(end+\'_id\')\n    if val not in (None,\'\'):\n        return key(val)\n    node=v.get(end)\n    if isinstance(node,dict):\n        return key(node.get(\'id\')) if str(node.get(\'type\') or \'torre\').lower() in (\'torre\',\'tower\',\'\') else \'\'\n    return key(node)\n\n\ndef is_frame(e):\n    return bool(e.get(\'marco\')) or bool(re.search(r\'\\b(?:ML|MARCO\\s+DE\\s+LINEA)\\b\',str(e.get(\'nombre\') or \'\'),re.I))\n\n\ndef nominal_number(text):\n    m=re.search(r\'\\bE\\s*(\\d+)\\s*$\',str(text or \'\'),re.I)\n    if m:return int(m.group(1))\n    m=re.fullmatch(r\'\\s*(\\d+)(?:\\.0+)?\\s*\',str(text or \'\'))\n    return int(m.group(1)) if m else None\n\n\ndef reconcile(lde, towers, tramos, vanos, catalog, *, threshold=UMBRAL_M,\n              linea_id=None, inventory_complete=True, only_towers=False):\n    """Un resultado por fila LDE y un ID físico estable para ST superpuestas.\n\n    Nunca confirma por nombre únicamente. Una torre puede pertenecer a múltiples\n    tramos, y una estructura LDE de dos ST puede compartir el mismo ID BDATx.\n    """\n    tower_by_id={key(t.get(\'id\')): t for t in towers if key(t.get(\'id\'))}\n    normalized={tid: normalize_tower(t,catalog) for tid,t in tower_by_id.items()}\n    tramo_by_id={key(t.get(\'id\')):t for t in tramos}\n    tramo_for_st=defaultdict(set)\n    for t in tramos:\n        if key(t.get(\'inf_id\')):tramo_for_st[key(t[\'inf_id\'])].add(key(t[\'id\']))\n    tower_tramos=defaultdict(set)\n    spans=defaultdict(list)\n    for t in towers:\n        tid=key(t.get(\'id\'))\n        for trid in (relation_ids(t,\'tramo\',\'tramos\') & set(tramo_by_id)):\n            tower_tramos[tid].add(trid)\n    for tramo in tramos:\n        tr_id=key(tramo.get(\'id\'))\n        for end in (\'nodo1\',\'nodo2\'):\n            value=tramo.get(end+\'_id\')\n            if value is None:\n                node=tramo.get(end)\n                value=node.get(\'id\') if isinstance(node,dict) and node.get(\'type\',\'torre\')==\'torre\' else None\n            tid=key(value)\n            if tid in tower_by_id:tower_tramos[tid].add(tr_id)\n    for v in ([] if only_towers else vanos):\n        ids=(tower_id_from_vano(v,\'nodo1\'),tower_id_from_vano(v,\'nodo2\'))\n        trids=relation_ids(v,\'tramo\',\'tramos\') & set(tramo_by_id)\n        for tid in ids:\n            if tid in tower_by_id:\n                tower_tramos[tid].update(trids)\n        if all(ids):\n            for trid in trids: spans[trid].append((frozenset(ids),v))\n\n    # Normalizar todas las filas y agrupar una torre física compartida por ST.\n    groups=[]; rows=[]\n    for input_row in lde:\n        item=dict(input_row)\n        item[\'st\']=key(item.get(\'st\'))\n        item[\'este\']=number(item.get(\'este\'))\n        item[\'norte\']=number(item.get(\'norte\'))\n        item[\'marco\']=is_frame(item)\n        item[\'huso_comparable\']=zone(item.get(\'huso\'))\n        item[\'lon\']=number(item.get(\'lon\'))\n        item[\'lat\']=number(item.get(\'lat\'))\n        item[\'coordenadas_validas\']=(valid_utm(item[\'este\'],item[\'norte\']) and item[\'huso_comparable\'] is not None\n                                     or valid_lonlat(item[\'lon\'],item[\'lat\']))\n        found=None\n        if item[\'coordenadas_validas\']:\n            for g in groups:\n                ref=g[\'rows\'][0]\n                same_physical=False\n                if ref[\'coordenadas_validas\'] and ref[\'st\'] != item[\'st\']:\n                    if valid_lonlat(ref[\'lon\'],ref[\'lat\']) and valid_lonlat(item[\'lon\'],item[\'lat\']):\n                        _,_,d=_GEOD.inv(ref[\'lon\'],ref[\'lat\'],item[\'lon\'],item[\'lat\'])\n                        same_physical=d<=threshold\n                    elif (ref[\'huso_comparable\']==item[\'huso_comparable\'] and\n                          valid_utm(ref[\'este\'],ref[\'norte\']) and valid_utm(item[\'este\'],item[\'norte\'])):\n                        same_physical=hypot(ref[\'este\']-item[\'este\'],ref[\'norte\']-item[\'norte\'])<=threshold\n                if same_physical:\n                    found=g;break\n        if found is None:\n            found={\'rows\':[],\'primary\':len(groups)+1}\n            groups.append(found)\n        found[\'rows\'].append(item)\n        item[\'physical_id\']=found[\'primary\']\n        rows.append(item)\n    assignments={}\n    assigned_tower={}\n    # geométrica espacial: ID único + coherencia de tramos cuando esté declarada\n    ordered=sorted(groups,key=lambda g:(not g[\'rows\'][0][\'coordenadas_validas\'],g[\'primary\']))\n    for g in ordered:\n        head=g[\'rows\'][0]\n        sts={r[\'st\'] for r in g[\'rows\']}\n        expected=set().union(*(tramo_for_st.get(st,set()) for st in sts))\n        record={\'id_torre\':None,\'nombre_torre\':\'\',\'id_candidato\':None,\'nombre_candidato\':\'\',\n                \'distancia_m\':None,\'distancia_candidato_m\':None,\'estado\':\'REVISAR\',\n                \'accion\':\'\',\'criterio\':\'\',\'observacion\':\'\',\n                \'tramos_torre\':[],\'tramos_lde\':sorted(expected),\'physical_id\':g[\'primary\']}\n        if all(is_frame(r) for r in g[\'rows\']):\n            record.update(estado=\'MARCO\',accion=\'\',criterio=\'MARCO_DOCUMENTADO\')\n            assignments[g[\'primary\']]=record\n            continue\n        datum=str(head.get(\'datum\') or \'\').upper().replace(\' \',\'\').replace(\'-\',\'\')\n        if datum and \'WGS84\' not in datum and datum not in (\'NOESPECIFICADO\',\'NOINFORMADO\',\'SININFORMACION\',\'DESCONOCIDO\'):\n            record.update(estado=\'REVISAR_DATUM_LDE\',criterio=\'DATUM_NO_COMPARABLE\',\n                observacion=f\'Datum LDE {head.get("datum")} no confirmado como WGS84; no asociar ni proponer creación\')\n            assignments[g[\'primary\']]=record\n            continue\n        if not head[\'coordenadas_validas\']:\n            record.update(estado=\'REVISAR_COORDENADAS_LDE\',criterio=\'LDE_UTM_INVALIDO\',observacion=\'Coordenadas LDE no comparables\')\n            assignments[g[\'primary\']]=record\n            continue\n        candidates=[]\n        for tid,t in normalized.items():\n            # Comparación espacial sobre un mismo sistema: geodésico WGS84 si el\n            # LDE ya se dibujó, UTM en huso idéntico como alternativa.\n            if valid_lonlat(head[\'lon\'],head[\'lat\']) and valid_lonlat(t.get(\'lon\'),t.get(\'lat\')):\n                _,_,dist=_GEOD.inv(head[\'lon\'],head[\'lat\'],t[\'lon\'],t[\'lat\'])\n            elif (valid_utm(head[\'este\'],head[\'norte\']) and\n                  head[\'huso_comparable\']==zone(t[\'huso\']) and t[\'este\'] is not None):\n                dist=hypot(t[\'este\']-head[\'este\'],t[\'norte\']-head[\'norte\'])\n            else:continue\n            if dist<=threshold:candidates.append((dist,tid))\n        candidates.sort(key=lambda p:(p[0],p[1]))\n        # La línea BDATx está verificada; NO excluir una torre por propietario ni\n        # exigir una relación tramo en la ficha de la torre para conciliarla.\n        eligible=list(candidates)\n        if len(candidates)==1 and len(eligible)==1 and eligible[0][1] not in assigned_tower:\n            d,tid=eligible[0]\n            record.update(id_torre=int(tid) if tid.isdigit() else tid,\n                nombre_torre=normalized[tid][\'name\'],distancia_m=round(d,3),\n                estado=\'EXISTENTE\',accion=\'\',\n                criterio=\'COINCIDENCIA_GEOMETRICA_UNICA\',tramos_torre=sorted(tower_tramos[tid]))\n            if normalized[tid][\'metodo\']==\'INTERCAMBIO_ESTE_NORTE\':\n                record[\'observacion\']=\'BDATx: Este/Norte normalizados por inversión verificada\'\n            assigned_tower[tid]=g[\'primary\']\n        elif candidates:\n            cand_id=candidates[0][1]\n            record.update(estado=\'REVISAR_ASOCIACION\',criterio=\'COINCIDENCIA_AMBIGUA\',\n                id_candidato=int(cand_id) if cand_id.isdigit() else cand_id,\n                nombre_candidato=normalized[cand_id][\'name\'],distancia_candidato_m=round(candidates[0][0],3),\n                id_candidatos=[tid for _,tid in candidates],\n                observacion=\'Torres dentro de 5 m, pero hay coincidencia múltiple o ID ya asignado; revisar\')\n        else:\n            if only_towers:\n                # Contraste V1 estrictamente geometrico: nunca propone altas,\n                # ni asigna una torre por su nombre o por el propietario.\n                if not inventory_complete:\n                    record.update(estado=\'CONSULTA_INCOMPLETA\', criterio=\'INVENTARIO_NO_VERIFICADO\',\n                                  observacion=\'No es posible confirmar coincidencias: inventario BDATx incompleto\')\n                elif not towers:\n                    record.update(estado=\'SIN_TORRES_BDATX\', criterio=\'INVENTARIO_SIN_TORRES\',\n                                  observacion=\'No hay torres BDATx recuperadas para la linea\')\n                elif any(t.get(\'lon\') is None or t.get(\'lat\') is None for t in normalized.values()):\n                    record.update(estado=\'REVISAR_INVENTARIO_BDATX\', criterio=\'TORRES_BDATX_NO_GEORREFERENCIABLES\',\n                                  observacion=\'Hay torres BDATx con coordenadas o huso no comparables; la ausencia de coincidencia no es concluyente\')\n                else:\n                    record.update(estado=\'SIN_COINCIDENCIA_BDATX\', criterio=\'SIN_TORRE_A_5M\',\n                                  observacion=\'No se encontro una torre BDATx a 5 m o menos\')\n                record[\'accion\']=\'\'\n                assignments[g[\'primary\']]=record\n                continue\n            # Evidence from topology: a nominal match in the SAME inventory,\n            # without spatial evidence, becomes REVIEW not CREATE.\n            n=nominal_number(head[\'nombre\'])\n            nominal=[]\n            if n is not None:\n                for tid,t in normalized.items():\n                    if nominal_number(t[\'name\']) == n and (not expected or tower_tramos[tid] & expected):\n                        nominal.append(tid)\n            if nominal:\n                nominal.sort()\n                tid=nominal[0]\n                record.update(estado=\'REVISAR_POSIBLE_DUPLICADO\',\n                    accion=\'REVISAR POSIBLE DUPLICADO - NO CREAR\',criterio=\'COINCIDENCIA_NOMINAL_NO_GEOMETRICA\',\n                    id_candidato=int(tid) if tid.isdigit() else tid,\n                    nombre_candidato=normalized[tid][\'name\'],\n                    observacion=\'Coincidencia nominal en torres de la línea; distancia no confirmada\' if only_towers else \'Coincidencia nominal en tramos relacionados; distancia no verificada\')\n            else:\n                # Topological neighbors: review rather than invent tower at unresolved junction.\n                if not inventory_complete:\n                    record.update(estado=\'CONSULTA_INCOMPLETA\',criterio=\'INVENTARIO_NO_VERIFICADO\',\n                        observacion=\'Inventario incompleto: no autoriza creación\')\n                elif not towers:\n                    record.update(estado=\'SIN_TORRES_BDATX\',criterio=\'INVENTARIO_SIN_TORRES\',\n                        observacion=\'Inventario BDATx sin torres asociadas a la línea; el LDE permanece válido, no crear automáticamente\')\n                elif only_towers and any(t.get(\'lon\') is None or t.get(\'lat\') is None for t in normalized.values()):\n                    record.update(estado=\'REVISAR_INVENTARIO_BDATX\',criterio=\'TORRES_BDATX_NO_GEORREFERENCIABLES\',\n                        accion=\'REVISAR DATOS BDATX - NO CREAR\',\n                        observacion=\'Hay torres BDATx con coordenadas o huso no interpretables. No se descarta coincidencia.\')\n                elif only_towers:\n                    record.update(estado=\'SIN_COINCIDENCIA_BDATX\',criterio=\'SIN_TORRE_A_5M\',\n                        accion=\'REVISAR DIFERENCIA - NO CREAR\',\n                        observacion=\'No hay torre BDATx dentro de 5 m. Revisar documentación y coordenadas; no proponer creación automática.\')\n                elif not expected:\n                    record.update(estado=\'TRAMO_NO_VERIFICADO\',criterio=\'SIN_TRAMO\',\n                        observacion=\'No se ha identificado tramo asociado a sección\')\n                elif any(t[\'este\'] is None and tower_tramos[tid]&expected\n                         for tid,t in normalized.items()):\n                    record.update(estado=\'REVISAR_INVENTARIO_BDATX\',criterio=\'TORRE_SIN_COORDENADAS_EN_TRAMO\',\n                        observacion=\'Existe torre BDATx vinculada al tramo sin geometría válida; descartar duplicado antes de proponer alta\')\n                else:\n                    record.update(estado=\'SIN_COINCIDENCIA_BDATX\',accion=\'\',\n                                  criterio=\'SIN_CANDIDATO_ESPACIAL_NI_NOMINAL\')\n        assignments[g[\'primary\']]=record\n    # Electrical-topology conflict detection: a nominal candidate with invalid UTM\n    # may coexist with a second tower that joins the two adjacent confirmed towers.\n    # NODO1_ID/NODO2_ID below are *tower IDs*, never another node namespace.\n    all_neighbors=defaultdict(set)\n    for v in ([] if only_towers else vanos):\n        a,b=tower_id_from_vano(v,\'nodo1\'),tower_id_from_vano(v,\'nodo2\')\n        if a and b:\n            all_neighbors[a].add(b)\n            all_neighbors[b].add(a)\n    by_st_for_conflict=defaultdict(list)\n    for r in rows:by_st_for_conflict[r[\'st\']].append(r)\n    for series in by_st_for_conflict.values():\n        series.sort(key=lambda r:r.get(\'fila\') or 0)\n    for g in groups:\n        assignment=assignments[g[\'primary\']]\n        if assignment[\'estado\']!=\'REVISAR_POSIBLE_DUPLICADO\':continue\n        unresolved_id=key(assignment.get(\'id_candidato\'))\n        for row in g[\'rows\']:\n            series=by_st_for_conflict[row[\'st\']]\n            i=next((j for j,rr in enumerate(series) if rr is row),None)\n            if i is None or not (0<i<len(series)-1):continue\n            left=assignments[series[i-1][\'physical_id\']]\n            right=assignments[series[i+1][\'physical_id\']]\n            a,b=key(left.get(\'id_torre\')),key(right.get(\'id_torre\'))\n            if not a or not b:continue\n            between=all_neighbors[a]&all_neighbors[b]\n            alternatives=sorted(tid for tid in between if tid in tower_by_id and tid!=unresolved_id)\n            if alternatives:\n                assignment.update(estado=\'REVISAR_CONFLICTO_BDATX\',\n                    accion=\'REVISAR CONFLICTO TOPOLOGICO - NO CREAR\',\n                    criterio=\'CANDIDATO_NOMINAL_Y_CAMINO_TOPOLOGICO_ALTERNATIVO\',\n                    observacion=f\'Candidato nominal {unresolved_id}; otro(s) registro(s) BDATx \' +\n                        \', \'.join(alternatives) + f\' conectan las torres vecinas {a} y {b}. \' +\n                        \'Revisar identidad, coordenadas y dependencias; no crear ni asignar automáticamente\')\n                break\n    # propagate canonical decisions to ALL documentary rows, including shared ST.\n    for row in rows:\n        a=assignments[row[\'physical_id\']]\n        row.update(id_torre=a[\'id_torre\'],nombre_torre=a[\'nombre_torre\'],\n                   id_bdatx_candidato=a[\'id_candidato\'],nombre_bdatx_candidato=a[\'nombre_candidato\'],\n                   distancia_candidato_m=a[\'distancia_candidato_m\'],distancia_m=a[\'distancia_m\'],\n                   estado=a[\'estado\'],accion=a[\'accion\'],criterio=a[\'criterio\'],\n                   observacion_conciliacion=a[\'observacion\'],tramos_torre=a[\'tramos_torre\'],\n                   tramos_lde=a[\'tramos_lde\'],\n                   estructura_limite_compartida=\'SI\' if len(next(g for g in groups if g[\'primary\']==row[\'physical_id\'])[\'rows\'])>1 else \'NO\')\n    # Los vanos se obtienen solo del LDE en el módulo de dibujo.\n    # Nunca realizar asociaciones topológicas BDATx si no se consultó esa API.\n    lde_spans=[]\n    if not only_towers:\n        by_st=defaultdict(list)\n        for r in rows:by_st[r[\'st\']].append(r)\n        for st,rs in by_st.items():\n            rs.sort(key=lambda x:(x.get(\'fila\') or 0))\n            for a,b in zip(rs,rs[1:]):\n                ta=key(a.get(\'id_torre\'));tb=key(b.get(\'id_torre\'))\n                span_rec={\'st\':st,\'estructura_1\':a.get(\'nombre\'),\'estructura_2\':b.get(\'nombre\'),\n                          \'id_torre_1\':a.get(\'id_torre\'),\'id_torre_2\':b.get(\'id_torre\'),\n                          \'id_vano\':None,\'accion\':\'\',\n                          \'criterio\':\'EXTREMOS_NO_CONCILIADOS\',\'tramo_id\':None}\n                if ta and tb and ta!=tb:\n                    candidate_tramos=set(a.get(\'tramos_lde\',[]))|set(b.get(\'tramos_lde\',[]))\n                    matches_by_vano={}\n                    for trid in candidate_tramos:\n                        for pair,v in spans.get(trid,[]):\n                            if pair==frozenset((ta,tb)):\n                                matches_by_vano.setdefault(key(v.get(\'id\')),(trid,v))\n                    if len(matches_by_vano)==1:\n                        trid,v=next(iter(matches_by_vano.values()))\n                        span_rec.update(id_vano=v.get(\'id\'),tramo_id=trid,\n                            accion=\'YA EXISTE EN BDATX - NO CREAR\',criterio=\'PAR_IDS_TORRES\')\n                    elif len(matches_by_vano)>1:\n                        span_rec.update(accion=\'REVISAR VANO COMPARTIDO - NO CREAR\',criterio=\'MULTIPLES_VANOS_MISMOS_EXTREMOS\')\n                    else:\n                        span_rec.update(accion=\'REVISAR VANO NO ENCONTRADO\',criterio=\'PAR_IDS_SIN_VANO_BDATX\')\n                elif is_frame(a) or is_frame(b):\n                    span_rec.update(criterio=\'EXTREMO_MARCO_DE_LINEA\')\n                lde_spans.append(span_rec)\n    return {\'rows\':rows,\'groups\':groups,\'tower_normalized\':normalized,\n            \'tower_tramos\':{k:sorted(v) for k,v in tower_tramos.items()},\n            \'spans\':lde_spans,\'summary\':dict(Counter(a[\'estado\'] for a in assignments.values())),\n            \'counts\':{\'lde_rows\':len(rows),\'physical_structures\':len(groups),\n                      \'towers\':len(towers),\'vanos\':len(vanos),\'spans\':len(lde_spans),\n                      \'matched_spans\':sum(x[\'criterio\']==\'PAR_IDS_TORRES\' for x in lde_spans)}}\n'), ('piloto_trazado', '"""GeoLínea Tx V1: trazado LDE y comparación exclusiva de TORRES por línea BDATx."""\nfrom __future__ import annotations\nimport json, re, math, zipfile, xml.etree.ElementTree as ET, webbrowser, threading, sys\nfrom pathlib import Path\nfrom collections import defaultdict, Counter\nfrom datetime import datetime\nfrom pyproj import Transformer\nfrom openpyxl import Workbook\nfrom openpyxl.styles import Font, PatternFill, Alignment\nfrom openpyxl.utils import get_column_letter\nfrom motor_conciliacion import (normalize_tower, reconcile, tower_id_from_vano, relation_ids)\n\nROOT=Path(__file__).resolve().parent\nINS=ROOT/\'DOCUMENTOS_BDIT\'  # Sin carpeta INSUMOS: solo se guardan resultados por línea\nDOCS=ROOT/\'DOCUMENTOS_BDIT\'\ndef line_folder(line_id, ins=INS):\n    """Una carpeta por línea, estable incluso sin ST consultadas."""\n    line_id=int(line_id)\n    if line_id<=0:raise ValueError(\'Indica un ID BDIT válido\')\n    return DOCS/f\'LT{line_id}\'\nCOLORS={588:\'#16a34a\',1721:\'#2563eb\'}\n# Catálogo de zonaOHuso BDATx: equivalencias aportadas y confirmadas en el proyecto.\n# NO se deduce el huso desde coordenadas, LDE ni cercanía espacial.\nCATALOGO_ZONA_HUSO = {\n    \'799d110c-44dc-4981-a26e-79d47e4bec1b\': \'19K\',\n    \'1e6d9fca-d1d4-4f8a-96ff-737168f787d0\': \'19J\',\n    \'5291431a-8812-4d12-9ed4-d37fb499fe26\': \'19H\',\n    \'97c4f949-7a10-4118-97dd-702f6a78aad9\': \'18H\',\n    \'fa958d30-dd0f-4258-93fa-5e8d512888be\': \'18\',\n    \'05a489e8-5a6b-48f2-859e-462df9a25ef8\': \'18\',\n    \'7cae7c49-b42f-4595-aa0e-d6d53ee6862a\': \'18\',\n    \'52bc65df-af98-46ce-88b0-7c3e323fc646\': \'18\',\n    \'cef97e4a-8586-4892-b7ca-8c8822cf421a\': \'18\',\n    \'fc745bdd-dd57-4cef-b85e-c62f1f0bcb67\': \'19\',\n    \'8d373e6d-6eaa-44d8-b06b-bd24ec46f954\': \'19\',\n    \'d2fd4143-bece-4e39-80f8-ca2e908fe127\': \'19\',\n    \'90029494-4b2c-4901-a79f-7813333a6444\': \'19\',\n}\n# La banda \'No registrada\' se representa como None: no inferir letras.\n# EPSG:32718/32719: UTM hemisferio sur para instalaciones chilenas.\n\ndef convertir_torre_bdatx(t):\n    """The same canonical UTM normalization used by reconciliation and exports."""\n    info=normalize_tower(t,CATALOGO_ZONA_HUSO)\n    z=info[\'huso\'];epsg=32700+int(z[:2]) if z and info[\'este\'] is not None else None\n    ll=(None,None)\n    estado=info[\'estado\']\n    if epsg is not None:\n        ll=Transformer.from_crs(f\'EPSG:{epsg}\',\'EPSG:4326\',always_xy=True).transform(info[\'este\'],info[\'norte\'])\n        if not (-80 <= ll[0] <= -60 and -57 <= ll[1] <= -17):\n            # Do not silently alter formally valid but geographically anomalous points.\n            estado=\'FUERA_CHILE_REVISAR\'\n            ll=(None,None)\n    return {\'huso_uuid\':info[\'huso_uuid\'],\'huso\':z,\'este\':info[\'este\'],\n            \'norte\':info[\'norte\'],\'este_raw\':info[\'este_raw\'],\'norte_raw\':info[\'norte_raw\'],\n            \'metodo_normalizacion\':info[\'metodo\'],\n            \'lon\':ll[0],\'lat\':ll[1],\'epsg\':f\'EPSG:{epsg}\' if epsg else None,\n            \'estado\':\'OK_CATALOGO\' if estado in (\'UTM_VALIDO\',\'UTM_NORMALIZADO\') else estado}\n\nNS={\'x\':\'http://schemas.openxmlformats.org/spreadsheetml/2006/main\',\'r\':\'http://schemas.openxmlformats.org/officeDocument/2006/relationships\'}\n\ndef read_xlsx_rows(path, sheet_number=1):\n    """Lee valores de la primera hoja sin depender de Excel instalado."""\n    with zipfile.ZipFile(path) as z:\n        ss=[]\n        if \'xl/sharedStrings.xml\' in z.namelist():\n            root=ET.fromstring(z.read(\'xl/sharedStrings.xml\'))\n            ss=[\'\'.join(t.text or \'\' for t in si.findall(\'.//x:t\',NS)) for si in root.findall(\'x:si\',NS)]\n        sheets=sorted([n for n in z.namelist() if re.match(r\'xl/worksheets/sheet\\d+\\.xml$\',n)])\n        if not sheets:raise ValueError(\'No hay hojas en \'+str(path))\n        root=ET.fromstring(z.read(sheets[sheet_number-1]))\n        for row in root.findall(\'.//x:sheetData/x:row\',NS):\n            vals={}\n            for c in row.findall(\'x:c\',NS):\n                ref=c.get(\'r\',\'A1\'); letters=re.match(\'[A-Z]+\',ref).group(); idx=0\n                for ch in letters:idx=idx*26+ord(ch)-64\n                v=c.find(\'x:v\',NS)\n                if c.get(\'t\')==\'inlineStr\':\n                    val=\'\'.join(x.text or \'\' for x in c.findall(\'.//x:t\',NS))\n                elif v is None:continue\n                elif c.get(\'t\')==\'s\':val=ss[int(v.text)]\n                elif c.get(\'t\') in (\'str\',\'e\'):val=v.text\n                else:\n                    try:val=float(v.text)\n                    except (ValueError,TypeError):val=v.text\n                vals[idx]=val\n            yield int(row.get(\'r\')),vals\n\ndef number(v):\n    try:return float(str(v).replace(\' \',\'\').replace(\',\',\'.\'))\n    except (ValueError,TypeError):return None\n\ndef norm(v):return re.sub(r\'[^A-Z0-9]\',\'\',str(v).upper())\n\ndef structure_key(v):\n    if isinstance(v,(int,float)) and float(v).is_integer():v=str(int(v))\n    elif isinstance(v,str) and re.fullmatch(r\'\\d+\\.0+\',v.strip()):v=v.strip().split(\'.\')[0]\n    s=norm(v)\n    if s.isdigit():return \'E\'+str(int(s))\n    if re.fullmatch(r\'\\d+[A-Z]+\',s):return \'E\'+s\n    m=re.search(r\'E(\\d+[A-Z]*)$\',s)\n    return \'E\'+m.group(1) if m else s\n\ndef valid_utm(e,n):return e is not None and n is not None and 100000<=e<=900000 and 1000000<=n<=10000000\n\ndef read_lde(path, st):\n    """Extrae LDE según encabezados reales y transforma UTM WGS84 a lon/lat.\n\n    Huso 19H => EPSG:32719. Rechaza filas con huso/datum no identificable,\n    en vez de asumir una zona y generar geometrías incorrectas.\n    """\n    from functools import lru_cache\n    import unicodedata\n\n    def label(value):\n        s = unicodedata.normalize(\'NFKD\', str(value or \'\'))\n        s = \'\'.join(c for c in s if not unicodedata.combining(c))\n        return re.sub(r\'\\s+\', \' \', s.lower().replace(\'_\', \' \')).strip()\n\n    @lru_cache(maxsize=20)\n    def transformer(epsg):\n        return Transformer.from_crs(f\'EPSG:{epsg}\', \'EPSG:4326\', always_xy=True)\n\n    from extractor_estructuras import resolver_huso_lde\n    headers = None\n    result = []\n    for rowno, values in read_xlsx_rows(path):\n        if headers is None:\n            normalized = {col: label(v) for col, v in values.items()}\n            def column(*terms):\n                return next((col for col, text in normalized.items()\n                             if any(term in text for term in terms)), None)\n            east = column(\'coordenada este\', \'coord. este\', \'easting\')\n            if east is None and \'norte\' in normalized.values():east=column(\'este\')\n            north = column(\'coordenada norte\', \'coord. norte\', \'northing\')\n            if north is None and \'este\' in normalized.values():north=column(\'norte\')\n            structure = column(\'n° de estructura\', \'nº de estructura\', \'n de estructura\',\n                               \'numero de estructura\', \'nro de estructura\', \'numeracion\')\n            if east is not None and north is not None and structure is not None:\n                headers = dict(east=east, north=north, structure=structure,\n                               zone=column(\'huso\', \'zona utm\'), datum=column(\'datum\'),\n                               kind=column(\'tipo de estructura\'), function=column(\'funcion de la estructura\'),\n                               code=column(\'codigo de estructura\'))\n            continue\n        def get(key):\n            col = headers.get(key)\n            return values.get(col) if col is not None else None\n        name = get(\'structure\')\n        if name is None or str(name).strip() in (\'\', \'-\'):\n            continue\n        e, n = number(get(\'east\')), number(get(\'north\'))\n        raw_zone = str(get(\'zone\') or \'\').strip().upper().replace(\' \', \'\')\n        raw_datum = label(get(\'datum\'))\n        alert = []\n        if not valid_utm(e, n) and valid_utm(n, e):\n            e, n = n, e\n            alert.append(\'Coordenadas Este/Norte invertidas en el documento\')\n        if not valid_utm(e, n):\n            alert.append(\'Coordenadas UTM inválidas o ausentes\')\n        match = re.fullmatch(r\'(1[7-9])([C-X])?\', raw_zone)\n        lon=lat=None\n        z_resuelto=raw_zone\n        if valid_utm(e,n):\n            lon,lat,z_resuelto,estado_huso,obs_huso=resolver_huso_lde(e,n,raw_zone)\n            if estado_huso!=\'DOCUMENTAL\':alert.append(obs_huso)\n            if raw_datum and (\'wgs\' not in raw_datum or \'84\' not in raw_datum):\n                alert.append(\'Datum distinto o no confirmado como WGS84: verificar antes de uso definitivo\')\n            elif not raw_datum:alert.append(\'Datum no informado; transformación preliminar WGS84\')\n        result.append(dict(st=st, fila=rowno, nombre=str(name).strip(),\n                           clave=structure_key(name), este=e, norte=n,\n                           lat=lat, lon=lon, marco=\'ML\' in norm(name) or norm(get(\'kind\'))==\'ML\',\n                           huso=z_resuelto, datum=get(\'datum\'),\n                           alerta=\'; \'.join(alert), tipo=str(get(\'kind\') or \'\'),\n                           funcion=str(get(\'function\') or \'\'), codigo=str(get(\'code\') or \'\')))\n    if headers is None:\n        raise ValueError(f\'No se identificaron encabezados de coordenadas UTM en {path.name}\')\n    return result\n\ndef load_data(ins, line_id=None, logger=print):\n    """Consulta la línea homóloga BDATx y su inventario sin depender del propietario.\n\n    Primero verifica filtros por línea y tramo; si el backend ignora los filtros,\n    recorre el recurso completo con paginación e integridad comprobadas,\n    reteniendo solamente los registros relacionados. No confunde 0 resultados\n    del filtro con ausencia demostrada de torres.\n    """\n    if line_id is None:\n        raise ValueError(\'Indica el ID de línea BDIT.\')\n    import requests, time, sys\n    from concurrent.futures import ThreadPoolExecutor, as_completed\n    from urllib.parse import urljoin\n    from math import ceil\n    session=__import__(\'__main__\').create_scoped_api_session()\n    bdit=\'https://api-infotecnica.coordinador.cl/v1/\'\n    bdatx=\'https://activos-tx-prod.appspot.com/api/v1/\'\n    tls_verify=getattr(sys.modules.get(\'__main__\'),\'TLS_VERIFY\',True)\n\n    def request_page(url, params=None, *, tag=\'API\'):\n        started=time.monotonic()\n        try:\n            response=session.get(url,params=params,timeout=(16,120))\n            response.raise_for_status()\n            obj=response.json()\n            return obj\n        except Exception as exc:\n            raise RuntimeError(f\'{tag}: {type(exc).__name__}: {exc}\') from exc\n        finally:\n            duration=time.monotonic()-started\n            if duration>=10:logger(f\'{tag}: respuesta tras {duration:.1f} s\')\n\n    def obj_line_id(obj):\n        v=obj.get(\'linea_id\')\n        if v is None:v=obj.get(\'linea\')\n        if isinstance(v,dict):v=v.get(\'id\')\n        return str(v).strip() if v is not None else \'\'\n\n    def obj_tramos(obj):\n        return relation_ids(obj,\'tramo\',\'tramos\')\n\n    def paginated(resource, params=None, *, tag=None, max_records=250000, expected=None):\n        """Consulta con paginación transparente y verifica count e IDs únicos."""\n        base=bdatx+resource+\'/\'\n        page=1;url=base;params=dict(params or {});params.setdefault(\'page_size\',500)\n        out=[];ids=set();visited=set();declared=None\n        while url:\n            if url in visited:raise RuntimeError(f\'{resource}: paginación circular\')\n            visited.add(url)\n            obj=request_page(url,params if page==1 else None,tag=tag or resource)\n            if isinstance(obj,list):\n                if page>1:raise RuntimeError(\'Paginación mixta inesperada\')\n                batch=obj;count=len(obj);next_url=None\n            elif isinstance(obj,dict):\n                batch=obj.get(\'results\')\n                count=obj.get(\'count\')\n                next_url=obj.get(\'next\')\n            else:raise RuntimeError(f\'{resource}: formato inesperado\')\n            if not isinstance(batch,list) or not isinstance(count,int):\n                raise RuntimeError(f\'{resource}: formato de página no verificable\')\n            if declared is None:declared=count\n            if declared!=count:raise RuntimeError(f\'{resource}: count cambió durante la descarga\')\n            if count>max_records:raise RuntimeError(f\'{resource}: {count} supera el límite {max_records}\')\n            for item in batch:\n                if not isinstance(item,dict) or item.get(\'id\') is None:\n                    raise RuntimeError(f\'{resource}: fila sin ID\')\n                if expected is not None and not expected(item):\n                    raise RuntimeError(f\'{resource}: filtro {params} ignorado, primera discordancia ID {item["id"]} (página {page})\')\n                sid=str(item[\'id\'])\n                if sid in ids:raise RuntimeError(f\'{resource}: ID repetido {sid}\')\n                ids.add(sid);out.append(item)\n            logger(f\'BDATx | {tag or resource} | Página {page}: {len(ids)}/{declared}\')\n            url=urljoin(base,str(next_url)) if next_url else None\n            page+=1;params=None\n            if page>10000:raise RuntimeError(f\'{resource}: paginación excesiva\')\n        if len(ids)!=declared:\n            raise RuntimeError(f\'{resource}: descarga incompleta {len(ids)}/{declared}\')\n        return out\n\n    def scan_all_filtered(resource, predicate, *, max_records, tag):\n        """Barrido integral incremental: conserva IDs para integridad, no 85 mil torres en RAM."""\n        base=bdatx+resource+\'/\'\n        first=request_page(base,{\'page_size\':500,\'page\':1},tag=tag+\' página 1\')\n        if not isinstance(first,dict) or not isinstance(first.get(\'results\'),list):\n            raise RuntimeError(f\'{resource}: API no paginada\')\n        total=first.get(\'count\')\n        if not isinstance(total,int) or total<0 or total>max_records:\n            raise RuntimeError(f\'{resource}: total inválido {total}\')\n        effective=len(first[\'results\'])\n        if total and not effective:raise RuntimeError(f\'{resource}: página inicial vacía con count positivo\')\n        page_size=effective or 500\n        n_pages=ceil(total/page_size) if total else 1\n        ids=set();selected={};read=0\n        def add_page(items,i):\n            nonlocal read\n            for row in items:\n                if not isinstance(row,dict) or row.get(\'id\') is None:\n                    raise RuntimeError(f\'{resource}: registro sin ID en página {i}\')\n                k=str(row[\'id\'])\n                if k in ids:raise RuntimeError(f\'{resource}: ID duplicado {k} en el inventario\')\n                ids.add(k);read+=1\n                if predicate(row):selected[k]=row\n        add_page(first[\'results\'],1)\n        logger(f\'BDATx | {tag} | Verificando inventario general: {total} registros, {n_pages} páginas; seleccionados {len(selected)}\')\n        def page(number):\n            last=None\n            for retry in range(3):\n                try:\n                    # requests.get directo para no compartir una sesión entre hilos.\n                    r=requests.get(base,params={\'page_size\':page_size,\'page\':number},\n                                   headers={\'Accept\':\'application/json\'},timeout=(15,120),verify=tls_verify)\n                    r.raise_for_status();data=r.json()\n                    if not isinstance(data,dict) or not isinstance(data.get(\'results\'),list):\n                        raise RuntimeError(\'Página no paginada\')\n                    if data.get(\'count\')!=total:raise RuntimeError(\'Total cambió\')\n                    return number,data[\'results\']\n                except Exception as exc:\n                    last=exc\n                    if retry<2:time.sleep(1+retry)\n            raise RuntimeError(f\'{tag} página {number}: {last}\')\n        # Controlar memoria: máximo 8 páginas en vuelo, no acumular todos los JSON.\n        with ThreadPoolExecutor(max_workers=8) as pool:\n            inflight={}\n            next_page=2\n            while next_page<=n_pages or inflight:\n                while next_page<=n_pages and len(inflight)<8:\n                    inflight[pool.submit(page,next_page)]=next_page\n                    next_page+=1\n                done=next(as_completed(inflight))\n                pn=inflight.pop(done)\n                _,items=done.result()\n                add_page(items,pn)\n                if pn%10==0 or not inflight and next_page>n_pages:\n                    logger(f\'BDATx | {tag} | {len(ids)}/{total} registros verificados; {len(selected)} asociados\')\n        if read!=total or len(ids)!=total:\n            raise RuntimeError(f\'{tag}: integridad fallida {read}/{total} registros\')\n        logger(f\'BDATx | {tag} | Integridad OK: {read}/{total}; línea seleccionada: {len(selected)}\')\n        return list(selected.values())\n\n    # Línea BDIT (API de detalle puntual, sin escanear el catálogo).\n    try:\n        bdline_obj=request_page(bdit+f\'lineas/{line_id}/\',tag=\'Línea BDIT\')\n        if not isinstance(bdline_obj,dict) or str(bdline_obj.get(\'id\'))!=str(line_id):\n            raise ValueError(\'Ficha de línea BDIT con ID inesperado\')\n    except Exception as exc:\n        logger(f\'AVISO: detalle BDIT de línea {line_id} no disponible ({exc}); probando filtro por ID\')\n        # Un filtro ignorado no puede autorizar una asociación arbitraria.\n        response=request_page(bdit+\'lineas/\',{\'id\':line_id,\'page_size\':100},tag=\'Línea BDIT por ID\')\n        items=response.get(\'results\') if isinstance(response,dict) else response\n        if not isinstance(items,list):raise RuntimeError(\'BDIT: respuesta de línea sin registros\')\n        matches=[x for x in items if str(x.get(\'id\'))==str(line_id)]\n        if len(matches)!=1:raise RuntimeError(f\'BDIT: línea {line_id} no se verificó de forma única\')\n        bdline_obj=matches[0]\n    bd_lines=paginated(\'lineas\',{\'inf_id\':line_id},tag=\'LINEA HOMOLOGA\',max_records=50000,\n                       expected=lambda x:str(x.get(\'inf_id\'))==str(line_id))\n    bd_lines=[x for x in bd_lines if str(x.get(\'inf_id\'))==str(line_id)]\n    if len(bd_lines)!=1:\n        raise RuntimeError(f\'BDATx: inf_id {line_id} generó {len(bd_lines)} líneas homólogas verificadas\')\n    id_linea=str(bd_lines[0][\'id\'])\n    logger(f\'BDATx | LÍNEA | BDIT {line_id} → BDATx {id_linea}\')\n\n    # La comparación básica utiliza exclusivamente /lineas/ y /torres/ de BDATx.\n    # NO consultar /tramos/ ni /vanos/; no filtrar torres por propietario.\n    logger(\'BDATx | CONSULTA SIMPLIFICADA | Se omiten tramos y vanos: solo torres de la línea.\')\n\n    def belongs_tower(t):return obj_line_id(t)==id_linea\n    logger(f\'BDATx | TORRES | Consultando línea {id_linea}, sin filtro de propietario\')\n    # Un filtro vacío no prueba que la línea carezca de torres. Verificar con barrido\n    # integral, solamente si hace falta, sin guardar las 85 mil torres en memoria.\n    torres=None;reason=\'\'\n    for param in (\'linea_id\',\'linea\'):\n        try:\n            received=paginated(\'torres\',{param:id_linea},tag=\'TORRES FILTRADAS\',max_records=200000,\n                               expected=belongs_tower)\n            outsiders=[t.get(\'id\') for t in received if not belongs_tower(t)]\n            if outsiders:raise RuntimeError(f\'La API ignoró {param}: registros ajenos {outsiders[:3]}\')\n            if received:\n                torres=received\n                logger(f\'BDATx | TORRES | {len(torres)} verificadas usando {param}={id_linea}\')\n                break\n            logger(f\'BDATx | TORRES | {param}={id_linea} sin registros; verificando alternativas\')\n        except RuntimeError as exc:\n            reason+=f\'{param}: {exc}; \'\n            logger(f\'BDATx | TORRES | Filtro {param} no verificable; probando alternativa\')\n    if torres is None:\n        logger(\'BDATx | TORRES | Los filtros no permitieron confirmar un inventario; se verificará el índice completo.\')\n        torres=scan_all_filtered(\'torres\',belongs_tower,max_records=200000,tag=\'TORRES\')\n    torres=list({str(t[\'id\']):t for t in torres}.values())\n    logger(f\'BDATx | TORRES | {len(torres)} torres de la línea {id_linea}, cualquier propietario\')\n\n    # La lista de secciones BDIT se obtiene del trazado LDE ya leído y de\n    # las carpetas ST existentes. No depende de tramos BDATx.\n    secciones=[]\n    sid_set=set()\n    folder=line_folder(line_id)\n    snapshot=folder/\'.cache\'/f\'Analisis_LT{line_id}.json\'\n    if snapshot.is_file():\n        try:\n            doc=json.loads(snapshot.read_text(encoding=\'utf-8\'))\n            for kind in (\'results\',\'paths\',\'segments\'):\n                for entry in (doc.get(kind) or []):\n                    if not isinstance(entry,dict):continue\n                    raw=entry.get(\'st\') or entry.get(\'seccion_bdit\') or entry.get(\'id_seccion\')\n                    sid=str(raw or \'\').strip().removesuffix(\'.0\')\n                    if sid.isdigit():sid_set.add(sid)\n        except (OSError,ValueError,TypeError) as exc:\n            logger(f\'AVISO BDIT | No se pudo leer ST del trazado almacenado: {exc}\')\n    for subfolder in folder.iterdir() if folder.is_dir() else []:\n        if subfolder.is_dir():\n            match=re.fullmatch(r\'ST[_ -]?(\\d+)\',subfolder.name,re.I)\n            if match:sid_set.add(match.group(1))\n    # Las referencias de sección en la ficha BDIT de la línea son auxiliares.\n    for field in (\'secciones_tramos\',\'seccionesTramos\',\'secciones\'):\n        entries=bdline_obj.get(field) or []\n        if isinstance(entries,list):\n            for entry in entries:\n                sid=str((entry.get(\'id\') if isinstance(entry,dict) else entry) or \'\')\n                if sid.isdigit():sid_set.add(sid)\n    logger(f\'BDIT | SECCIONES | {len(sid_set)} ID(s) identificados desde LDE y documentación local: {", ".join(sorted(sid_set)) or "ninguno"}\')\n    for sid in sorted(sid_set,key=int):\n        try:\n            obj=request_page(bdit+f\'secciones-tramos/{sid}/\',tag=f\'ST BDIT {sid}\')\n            if not isinstance(obj,dict) or str(obj.get(\'id\'))!=sid:\n                raise ValueError(\'ID de sección inesperado\')\n            # Solo validar la relación cuando el campo está presente en la ficha.\n            relation=obj.get(\'id_linea\',obj.get(\'linea_id\',obj.get(\'linea\')))\n            if isinstance(relation,dict):relation=relation.get(\'id\')\n            if relation is not None and str(relation)!=str(line_id):\n                logger(f\'AVISO BDIT | ST {sid} indica línea {relation}; revisar relación, no atribuir propietario.\')\n                continue\n            secciones.append(obj)\n            logger(f\'BDIT | ST {sid} | Propietario {obj.get("propietario_nombre") or "no informado"}\')\n        except Exception as exc:\n            logger(f\'AVISO BDIT | ST {sid} no disponible: {exc}. El LDE y la comparación siguen disponibles.\')\n    logger(f\'BDATx | RESUMEN | Línea {id_linea}: {len(torres)} torres, sin consultar tramos ni vanos.\')\n    return {\'lineas_bdit\':[bdline_obj],\'st_bdit\':secciones,\'lineas_bdatx\':bd_lines,\n            \'tramos_bdatx\':[],\'torres_bdatx\':torres,\'vanos_bdatx\':[],\n            \'inventario_torres_completo\':True,\'inventario_vanos_completo\':False,\n            \'criterio_consulta_torres\':\'linea_id o inventario general validado; sin propietario\',\n            \'modo_comparacion\':\'SOLO_TORRES\'}\n\ndef dist(a,b):\n    """Distancia geodésica para el trazado ya dibujado en WGS84."""\n    if not a or not b:return None\n    if all(v.get(k) is not None for v in (a,b) for k in (\'lon\',\'lat\')):\n        from pyproj import Geod\n        _,_,meters=Geod(ellps=\'WGS84\').inv(a[\'lon\'],a[\'lat\'],b[\'lon\'],b[\'lat\'])\n        return abs(meters)\n    if a.get(\'este\') is None or b.get(\'este\') is None:return None\n    if not (a.get(\'huso\') and b.get(\'huso\') and str(a[\'huso\'])[:2]==str(b[\'huso\'])[:2]):return None\n    return math.hypot(a[\'este\']-b[\'este\'],a[\'norte\']-b[\'norte\'])\n\ndef generate_from_documents(line_id, logger=print):\n    """Vista preliminar de coordenadas de documentos de cualquier línea.\n    No atribuye relaciones BDATx si no están disponibles.\n    """\n    from extractor_estructuras import run as extract_documents\n    from pyproj import Transformer\n    import csv\n    folder=line_folder(line_id)\n    if not folder.is_dir():\n        raise ValueError(f\'No existen documentos para LT{line_id}. Primero descarga documentos en la pestaña 1.\')\n    dest,count,errors=extract_documents(folder)\n    source=Path(dest)/\'01_COORDENADAS_EXTRAIDAS.csv\'\n    points=[]\n    with source.open(encoding=\'utf-8-sig\',newline=\'\') as f:\n        for r in csv.DictReader(f,delimiter=\';\'):\n            try:\n                lat=float(r[\'latitud\']);lon=float(r[\'longitud\'])\n            except (ValueError,TypeError):\n                try:\n                    este=float(r[\'este\']);norte=float(r[\'norte\'])\n                    z=re.search(r\'(18|19)\',r.get(\'huso\',\'\'))\n                    if not z:continue\n                    lon,lat=Transformer.from_crs(f\'EPSG:327{z.group(1)}\',\'EPSG:4326\',always_xy=True).transform(este,norte)\n                except (ValueError,TypeError):continue\n            if not (-56<=lat<=-17 and -76<=lon<=-66):continue\n            points.append({\'lat\':lat,\'lon\':lon,\'id_seccion\':r[\'id_seccion\'],\'name\':r.get(\'estructura\',\'\'), \'archivo\':r[\'archivo\']})\n    if not points:raise ValueError(f\'No se encontraron coordenadas georreferenciables en LT{line_id}. Revisa .cache/REPORTE_ESTRUCTURAS/03_ERRORES_LECTURA.csv y los LDE descargados.\')\n    cache=line_folder(line_id)/\'.cache\';cache.mkdir(parents=True,exist_ok=True)\n    payload={\'results\':[], \'paths\':[], \'segments\':[], \'bd_paths\':[], \'bd_points\':[], \'bd_segments\':[], \'document_points\':points,\'mode\':\'DOCUMENTOS_SIN_BDATX\'}\n    (cache/f\'Analisis_LT{line_id}.json\').write_text(json.dumps(payload,ensure_ascii=False),encoding=\'utf-8\')\n    logger(f\'Vista documental: {len(points)} coordenadas de {len(set(p["id_seccion"] for p in points))} secciones; BDATx NO evaluada.\')\n    return folder\n\ndef exportar_geojson_documental(line_id, logger=print):\n    """Exporta línea, ST, vanos y vértices desde LDE, sin depender de BDATx."""\n    import hashlib\n    line_id=int(line_id)\n    folder=line_folder(line_id);folder.mkdir(parents=True,exist_ok=True)\n    candidates=[]\n    for file in folder.rglob(\'*.xlsx\'):\n        if any(part.lower() in (\'.cache\',\'clasificacion\',\'reportes\',\'reporte\',\'salidas\') for part in file.relative_to(folder).parts):continue\n        if file.name.startswith(\'~$\') or file.name.lower().startswith(\'reporte_\'):continue\n        st=None\n        for part in file.relative_to(folder).parts:\n            m=re.search(r\'^ST[_ -]?(\\d+)$\',part,re.I)\n            if m:st=int(m.group(1));break\n        if st is None:\n            m=re.search(r\'^ST[_ -]?(\\d+)(?:[_ -]|$)\',file.name,re.I)\n            if m:st=int(m.group(1))\n        if st is not None:candidates.append((st,file))\n    by_st={};fingerprints=set()\n    for st,path in sorted(candidates,key=lambda x:str(x[1])):\n        try:\n            fingerprint=(st,hashlib.sha256(path.read_bytes()).hexdigest())\n            if fingerprint in fingerprints:continue\n            fingerprints.add(fingerprint)\n            records=read_lde(path,st)\n            valid=sum(p.get(\'lat\') is not None and p.get(\'lon\') is not None for p in records)\n            if valid and (st not in by_st or valid>by_st[st][0]):by_st[st]=(valid,path,records)\n        except Exception as exc:logger(f\'LDE no legible {path.name}: {exc}\')\n    features=[];parts=[];issues=[];all_points=[];all_segments=[]\n    for st,(valid,path,records) in sorted(by_st.items()):\n        logger(f\'ST {st}: {valid} coordenadas LDE desde {path.name}\')\n        runs=[];run=[]\n        for p in records:\n            if p.get(\'lat\') is None or p.get(\'lon\') is None:\n                issues.append({\'ST\':st,\'tipo\':\'COORDENADA_INVALIDA\',\'estructura\':p.get(\'nombre\'),\'detalle\':p.get(\'alerta\')})\n                if run:runs.append(run);run=[]\n                continue\n            xy=[p[\'lon\'],p[\'lat\']]\n            all_points.append(p)\n            features.append({\'type\':\'Feature\',\'properties\':{\'tipo\':\'estructura_LDE\',\'fuente\':\'BDIT_LDE\',\'id_linea_bdit\':line_id,\'id_seccion\':st,\'estructura\':p.get(\'nombre\'),\'este\':p.get(\'este\'),\'norte\':p.get(\'norte\'),\'huso\':p.get(\'huso\'),\'datum\':p.get(\'datum\'),\'archivo\':path.name},\'geometry\':{\'type\':\'Point\',\'coordinates\':xy}})\n            run.append(p)\n        if run:runs.append(run)\n        for seq in runs:\n            if len(seq)<2:continue\n            coords=[[p[\'lon\'],p[\'lat\']] for p in seq];parts.append(coords)\n            features.append({\'type\':\'Feature\',\'properties\':{\'fuente\':\'BDIT_LDE\',\'tipo\':\'seccion_tramo\',\'id_linea_bdit\':line_id,\'id_seccion\':st,\'archivo\':path.name},\'geometry\':{\'type\':\'LineString\',\'coordinates\':coords}})\n            for a,b in zip(seq,seq[1:]):\n                length=dist(a,b);status=\'REVISAR_LONGITUD\' if length is not None and length>1000 else \'REFERENCIAL\'\n                all_segments.append({\'st\':st,\'a\':[a[\'lon\'],a[\'lat\']],\'b\':[b[\'lon\'],b[\'lat\']],\'nodo1\':a[\'nombre\'],\'nodo2\':b[\'nombre\'],\'longitud_m\':length,\'estado\':status})\n                features.append({\'type\':\'Feature\',\'properties\':{\'tipo\':\'vano_LDE\',\'fuente\':\'BDIT_LDE\',\'id_linea_bdit\':line_id,\'id_seccion\':st,\'nodo1\':a[\'nombre\'],\'nodo2\':b[\'nombre\'],\'longitud_m\':round(length,2) if length is not None else None,\'estado\':status},\'geometry\':{\'type\':\'LineString\',\'coordinates\':[[a[\'lon\'],a[\'lat\']],[b[\'lon\'],b[\'lat\']]]}})\n                if status==\'REVISAR_LONGITUD\':issues.append({\'ST\':st,\'tipo\':\'SALTO_POTENCIAL\',\'estructura\':a[\'nombre\']+\' → \'+b[\'nombre\'],\'detalle\':f\'{length:.1f} m; umbral de alerta referencial 1000 m\'})\n    if parts:\n        features.insert(0,{\'type\':\'Feature\',\'properties\':{\'fuente\':\'BDIT_LDE\',\'tipo\':\'linea\',\'id_linea_bdit\':line_id,\'nota\':\'MultiLineString por ST; no se conectan secciones artificialmente\'},\'geometry\':{\'type\':\'MultiLineString\',\'coordinates\':parts}})\n    output=folder/f\'Trazado_BDIT_LDE_LT{line_id}.geojson\'\n    output.write_text(json.dumps({\'type\':\'FeatureCollection\',\'features\':features},ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    logger(f\'GeoJSON BDIT/LDE: {output} ({len(features)} entidades, {len(issues)} alertas)\')\n    if not features:logger(\'ALERTA: No se encontraron LDE Excel georreferenciables para esta línea.\')\n    return output,len(features)\n\n\n\ndef crear_mapa_interactivo(line_id, logger=print, abrir=True):\n    # Mapa Leaflet con GeoJSON local incrustado; teselas requieren internet.\n    from pathlib import Path\n    import html as _html\n    line_id=int(line_id)\n    folder=line_folder(line_id)\n    lde=folder/f\'Trazado_BDIT_LDE_LT{line_id}.geojson\'\n    if not lde.exists():\n        exportar_geojson_documental(line_id,logger=logger)\n    if not lde.exists():raise FileNotFoundError(\'No existe trazado LDE para esta línea. Descarga primero los LDE.\')\n    def leer(path):\n        if not path.exists():return {\'type\':\'FeatureCollection\',\'features\':[]}\n        obj=json.loads(path.read_text(encoding=\'utf-8\'))\n        return obj if obj.get(\'type\')==\'FeatureCollection\' else {\'type\':\'FeatureCollection\',\'features\':[]}\n    a=leer(lde)\n    b=leer(folder/f\'Trazado_BDATX_LT{line_id}.geojson\')\n    # Incrustar los GeoJSON: abrir HTML local sin servidor ni llamadas a API.\n    ja=json.dumps(a,ensure_ascii=False).replace(\'<\',\'\\\\u003c\')\n    jb=json.dumps(b,ensure_ascii=False).replace(\'<\',\'\\\\u003c\')\n    template=r\'\'\'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Visor BDIT/BDATx LT__ID__</title>\n<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" crossorigin="">\n<style>html,body{margin:0;height:100%;font-family:Segoe UI,Arial,sans-serif;color:#162b45}#map{height:100vh;width:100%}\n#panel{position:absolute;top:12px;left:55px;z-index:900;background:white;padding:13px 16px;border-radius:9px;box-shadow:0 2px 16px #0003;max-width:345px}#panel h3{margin:0 0 7px;font-size:17px}#panel p{margin:4px 0;font-size:12px}#search{width:95%;padding:7px;margin:8px 0;border:1px solid #b6c3d1;border-radius:5px}#results{max-height:155px;overflow:auto;font-size:12px}#results div{padding:5px;cursor:pointer;border-bottom:1px solid #eee}#results div:hover{background:#eaf2ff}.legend{background:white;padding:10px;border-radius:6px;line-height:1.8;font-size:12px}button{padding:6px;cursor:pointer}</style></head><body>\n<div id="map"></div><div id="panel"><h3>Control de Calidad · LT__ID__</h3><p>LDE: <b id="nlde">0</b> estructuras · BDATx: <b id="nbd">0</b> torres</p><p>Selecciona elementos para ver sus atributos. Activa/desactiva capas en el control superior derecho.</p><input id="search" placeholder="Buscar ID, nombre o estructura..." aria-label="Buscar elemento"><div id="results"></div><button id="fit">Ajustar a la línea</button><p id="status"></p></div>\n<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script>\n<script>const LDE=__LDE__;const BD=__BD__;\nif(typeof L===\'undefined\'){document.getElementById(\'status\').textContent=\'Sin conexión a Leaflet: conecta internet para cargar el mapa.\';}else{\nconst map=L.map(\'map\',{preferCanvas:true}).setView([-33.45,-70.65],5);\nconst esri=L.tileLayer(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}\',{maxZoom:19,attribution:\'Tiles © Esri — World Imagery\'});\nconst esriTopo=L.tileLayer(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}\',{maxZoom:19,attribution:\'Tiles © Esri — World Topographic Map\'});\nconst carto=L.tileLayer(\'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\',{maxZoom:19,attribution:\'© CARTO, © OpenStreetMap contributors\'});\nconst relief=L.tileLayer(\'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png\',{maxZoom:17,attribution:\'© OpenTopoMap / OpenStreetMap\'});\nesri.addTo(map);\nconst layers={"Secciones LDE":L.layerGroup(),"Vanos LDE":L.layerGroup(),"Estructuras LDE":L.layerGroup(),"Alertas LDE >1 km":L.layerGroup(),"Vanos BDATx":L.layerGroup(),"Torres BDATx":L.layerGroup()};\nconst entries=[];let ldeCount=0,bdCount=0;\nfunction safe(s){return String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));}\nfunction info(p){return \'<table>\'+Object.entries(p||{}).filter(([k,v])=>v!==null&&v!==\'\'&&typeof v!==\'object\').map(([k,v])=>\'<tr><td><b>\'+safe(k)+\'</b></td><td>\'+safe(v)+\'</td></tr>\').join(\'\')+\'</table>\';}\nfunction add(fc,source){(fc.features||[]).forEach(f=>{if(!f.geometry)return;const p=f.properties||{},type=String(p.tipo||\'\').toLowerCase(),g=f.geometry;\nif(source===\'LDE\'&&type===\'linea\')return;if(source===\'BDATx\'&&type===\'linea_bdatx\')return;\nlet group,style={color:\'#2563eb\',weight:3,opacity:.85};\nif(source===\'LDE\'){\nif(type===\'estructura_lde\'){group=layers[\'Estructuras LDE\'];ldeCount++;}\nelse if(type===\'vano_lde\'){group=p.estado===\'REVISAR_LONGITUD\'?layers[\'Alertas LDE >1 km\']:layers[\'Vanos LDE\'];style={color:p.estado===\'REVISAR_LONGITUD\'?\'#dc2626\':\'#60a5fa\',weight:3,dashArray:p.estado===\'REVISAR_LONGITUD\'?\'7,5\':\'3,5\'};}\nelse if(type===\'seccion_tramo\'){group=layers[\'Secciones LDE\'];style={color:\'#1d4ed8\',weight:4,opacity:.8};}else return;\n}else{\nif(g.type===\'Point\'){group=layers[\'Torres BDATx\'];bdCount++;}\nelse if(type.includes(\'vano\')){group=layers[\'Vanos BDATx\'];style={color:\'#ea580c\',weight:3,dashArray:\'5,4\'};}else return;\n}\nlet layer=L.geoJSON(f,{style:()=>style,pointToLayer:(feat,ll)=>L.circleMarker(ll,{radius:source===\'LDE\'?4:6,color:source===\'LDE\'?\'#15803d\':\'#7c3aed\',fillColor:source===\'LDE\'?\'#22c55e\':\'#a78bfa\',fillOpacity:.95,weight:1})});\nlayer.bindPopup(\'<b>\'+safe(source)+\'</b>\'+info(p),{maxWidth:440});group.addLayer(layer);\nif(g.type===\'Point\'&&Array.isArray(g.coordinates)){const ll=[g.coordinates[1],g.coordinates[0]];entries.push({ll,txt:Object.values(p).join(\' \').toLowerCase(),title:String(p.estructura||p.nombre||p.id_torre||p.id||\'Torre\'),layer});}\n});}\nadd(LDE,\'LDE\');add(BD,\'BDATx\');Object.values(layers).forEach(x=>x.addTo(map));L.control.layers({\'Esri · Satelital\':esri,\'Esri · Topográfico\':esriTopo,\'CARTO · Claro\':carto,\'Relieve OpenTopoMap\':relief},layers,{collapsed:false}).addTo(map);\nconst all=L.featureGroup(Object.values(layers));function fit(){const b=all.getBounds();if(b.isValid())map.fitBounds(b.pad(.12),{maxZoom:16});}document.getElementById(\'fit\').onclick=fit;fit();\ndocument.getElementById(\'nlde\').textContent=ldeCount;document.getElementById(\'nbd\').textContent=bdCount;\nif(!bdCount)document.getElementById(\'status\').textContent=\'Sin torres BDATx en el GeoJSON: ejecuta la comparación para agregarlas.\';\nconst inp=document.getElementById(\'search\'),res=document.getElementById(\'results\');inp.addEventListener(\'input\',()=>{res.replaceChildren();const q=inp.value.trim().toLowerCase();if(q.length<2)return;entries.filter(e=>e.txt.includes(q)).slice(0,30).forEach(e=>{const d=document.createElement(\'div\');d.textContent=e.title;d.onclick=()=>{map.setView(e.ll,17);e.layer.eachLayer(x=>x.openPopup());};res.appendChild(d);});});\nconst legend=L.control({position:\'bottomright\'});legend.onAdd=()=>{const d=L.DomUtil.create(\'div\',\'legend\');d.innerHTML=\'<b>Leyenda</b><br>🔵 Secciones LDE<br>🟢 Estructuras LDE<br>🟣 Torres BDATx<br>🟠 Vanos BDATx<br>🔴 Saltos LDE > 1 km\';return d;};legend.addTo(map);\n}</script></body></html>\'\'\'\n    result=template.replace(\'__ID__\',str(line_id)).replace(\'__LDE__\',ja).replace(\'__BD__\',jb)\n    target=folder/f\'Mapa_Interactivo_LT{line_id}.html\'\n    target.write_text(result,encoding=\'utf-8\')\n    logger(\'Mapa interactivo guardado: \'+str(target))\n    if abrir:webbrowser.open(target.resolve().as_uri())\n    return target\n\n\ndef exportar_reporte_lde_sin_bdatx(line_id,reason,logger=print):\n    """Informe verificable cuando BDATx falla; jamás afirma coincidencias."""\n    line_id=int(line_id);folder=line_folder(line_id)\n    geo_path,_=exportar_geojson_documental(line_id,logger)\n    feats=json.loads(geo_path.read_text(encoding=\'utf-8\'))[\'features\']\n    wb=Workbook();ws=wb.active;ws.title=\'00_ESTADO\'\n    for row in [(\'CONCEPTO\',\'RESULTADO\'),(\'LINEA_BDIT\',line_id),(\'ESTADO_BDATX\',\'NO CONSULTADO / ERROR\'),(\'DETALLE\',str(reason)),(\'ARCHIVO_GEOJSON_LDE\',str(geo_path))]:ws.append(row)\n    ws=wb.create_sheet(\'01_LINEA_ST_VERTICES\');ws.append([\'LINEA_BDIT\',\'ID_SECCION\',\'ESTRUCTURA\',\'ESTE\',\'NORTE\',\'HUSO\',\'DATUM\',\'LATITUD\',\'LONGITUD\',\'ARCHIVO\'])\n    for f in feats:\n        p=f[\'properties\'];geom=f.get(\'geometry\') or {}\n        if geom.get(\'type\')==\'Point\':\n            lon,lat=geom[\'coordinates\'];ws.append([line_id,p.get(\'id_seccion\'),p.get(\'estructura\'),p.get(\'este\'),p.get(\'norte\'),p.get(\'huso\'),p.get(\'datum\'),lat,lon,p.get(\'archivo\')])\n    for name in (\'02_TRAMOS_VANOS_BDATX\',\'03_TRAMOS_TORRES_BDATX\',\'04_COMPARACION\'):\n        w=wb.create_sheet(name);w.append([\'ESTADO\',\'DETALLE\']);w.append([\'NO DISPONIBLE\',str(reason)[:30000]])\n    for sheet in wb:\n        sheet.freeze_panes=\'A2\'\n        for cell in sheet[1]:cell.fill=PatternFill(\'solid\',fgColor=\'17365D\');cell.font=Font(color=\'FFFFFF\',bold=True)\n    report=folder/f\'Reporte_LT{line_id}.xlsx\';wb.save(report)\n    status={\'id_linea_bdit\':line_id,\'estado_bdatx\':\'ERROR_CONSULTA\',\'detalle\':str(reason),\'geojson_lde\':str(geo_path),\'geojson_bdatx\':None}\n    (folder/f\'Estado_Consulta_LT{line_id}.json\').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    logger(f\'ALERTA: BDATx no disponible; reporte documental guardado en {report}\')\n    return report\n\ndef vista_desde_geojson(line_id, logger=print):\n    """Transforma el GeoJSON documental en capas del visor, sin datos BDATx inventados."""\n    path,count=exportar_geojson_documental(line_id,logger=logger)\n    collection=json.loads(path.read_text(encoding=\'utf-8\'))\n    paths=[];points=[];segments=[];by_st={}\n    for feature in collection.get(\'features\',[]):\n        p=feature.get(\'properties\',{});geom=feature.get(\'geometry\') or {}\n        if geom.get(\'type\')==\'LineString\' and p.get(\'tipo\')==\'seccion_tramo\':\n            st=int(p[\'id_seccion\']);coords=geom[\'coordinates\']\n            paths.append({\'st\':st,\'coords\':coords,\'nombre\':\'ST \'+str(st)})\n            for j,(a,b) in enumerate(zip(coords,coords[1:]),1):\n                # Umbral 1 km referencial; se destaca como posible salto, no como error confirmado.\n                dlon=(a[0]-b[0])*111320*math.cos(math.radians((a[1]+b[1])/2))\n                dlat=(a[1]-b[1])*111320\n                distance=math.hypot(dlon,dlat)\n                segments.append({\'st\':st,\'a\':a,\'b\':b,\'nodo1\':j,\'nodo2\':j+1,\'longitud_m\':round(distance,1),\'estado\':\'REVISAR_LONGITUD\' if distance>1000 else \'VANO_RECONSTRUIDO_LDE\'})\n        elif geom.get(\'type\')==\'Point\':\n            xy=geom.get(\'coordinates\',[])\n            if len(xy)<2:continue\n            st=int(p.get(\'id_seccion\',0));name=str(p.get(\'estructura\') or \'\')\n            points.append({\'st\':st,\'lon\':xy[0],\'lat\':xy[1],\'nombre\':name,\'estado\':\'SIN_CONTRASTE_BDATX\',\n                           \'este\':p.get(\'este\'),\'norte\':p.get(\'norte\'),\'archivo\':p.get(\'archivo\'),\n                           \'marco\':bool(\'MARCO\' in name.upper())})\n            by_st[st]=by_st.get(st,0)+1\n    payload={\'results\':points,\'paths\':paths,\'segments\':segments,\'bd_paths\':[],\n             \'bd_points\':[],\'bd_segments\':[],\'document_points\':[],\n             \'mode\':\'DOCUMENTOS_SIN_BDATX\'}\n    cache=line_folder(line_id)/\'.cache\';cache.mkdir(parents=True,exist_ok=True)\n    (cache/f\'Analisis_LT{line_id}.json\').write_text(json.dumps(payload,ensure_ascii=False),encoding=\'utf-8\')\n    logger(f\'Visor LDE: {len(points)} estructuras, {len(paths)} segmentos de ST y {len(segments)} vanos reconstruidos.\')\n    return path\n\ndef _lde_num(value):\n    if value in (\'\',None):return None\n    try:return float(str(value).replace(\',\',\'.\'))\n    except (TypeError,ValueError):return None\n\n\ndef leer_lde_consolidado(line_id, st_bdit, logger=print):\n    """ÚNICA fuente LDE para mapa y contraste: primero el resultado ya dibujado.\n\n    Si la lectura anterior provenía de un RAR/ZIP en carpeta temporal, no vuelve\n    a buscar archivos ni invalida el trazado. Sólo si no hay trazado persistido\n    intenta interpretar los anexos originales disponibles en disco.\n    """\n    folder=line_folder(line_id)\n    cache=folder/\'.cache\'/f\'Analisis_LT{line_id}.json\'\n    if cache.is_file():\n        try:\n            snapshot=json.loads(cache.read_text(encoding=\'utf-8\'))\n            points=snapshot.get(\'results\') or []\n            if points:\n                records=[]\n                for i,p in enumerate(points,1):\n                    if not isinstance(p,dict):continue\n                    lat=_lde_num(p.get(\'lat\'));lon=_lde_num(p.get(\'lon\'))\n                    if lat is None or lon is None or not (-90<=lat<=90 and -180<=lon<=180):continue\n                    records.append({\'st\':str(p.get(\'st\') or p.get(\'seccion_bdit\') or \'\'),\n                        \'fila\':p.get(\'fila\') or p.get(\'orden_global\') or i,\n                        \'nombre\':str(p.get(\'nombre\') or p.get(\'name\') or \'Estructura \'+str(i)),\n                        \'este\':_lde_num(p.get(\'este\')),\'norte\':_lde_num(p.get(\'norte\')),\n                        \'huso\':p.get(\'huso\') or \'\', \'datum\':p.get(\'datum\') or \'\',\n                        \'lat\':lat,\'lon\':lon,\'marco\':bool(p.get(\'marco\')),\n                        \'alerta\':p.get(\'alerta\') or \'\', \'archivo\':p.get(\'archivo\') or \'\',\n                        \'orden_lde\':p.get(\'orden_global\') or i})\n                if records:\n                    logger(f\'LDE | Se reutilizan {len(records)} estructuras del trazado ya dibujado; no se releen los ZIP/RAR.\')\n                    return records,snapshot\n        except Exception as exc:\n            logger(f\'AVISO: no se pudo reutilizar caché LDE ({exc}); intentando leer documentos.\')\n\n    # El GeoJSON de anexos es una segunda fuente válida y conserva la geometría.\n    geo=folder/f\'Trazado_Anexos_LT{line_id}.geojson\'\n    if geo.exists():\n        try:\n            fc=json.loads(geo.read_text(encoding=\'utf-8\'))\n            records=[]\n            for feature in fc.get(\'features\',[]):\n                prop=feature.get(\'properties\') or {};geom=feature.get(\'geometry\') or {}\n                if prop.get(\'tipo\')!=\'estructura_LDE\' or geom.get(\'type\')!=\'Point\':continue\n                coords=geom.get(\'coordinates\') or []\n                if len(coords)<2:continue\n                records.append({\'st\':str(prop.get(\'seccion_bdit\') or \'\'),\n                    \'fila\':prop.get(\'fila\') or len(records)+1,\n                    \'nombre\':str(prop.get(\'estructura\') or \'Estructura\'),\n                    \'este\':_lde_num(prop.get(\'este\')),\'norte\':_lde_num(prop.get(\'norte\')),\n                    \'huso\':prop.get(\'huso\') or \'\', \'datum\':prop.get(\'datum\') or \'\',\n                    \'lat\':_lde_num(coords[1]),\'lon\':_lde_num(coords[0]),\n                    \'marco\':bool(prop.get(\'marco\')),\'archivo\':prop.get(\'archivo\') or \'\',\n                    \'orden_lde\':prop.get(\'orden\') or len(records)+1})\n            if records:\n                logger(f\'LDE | {len(records)} estructuras recuperadas del GeoJSON de anexos ya procesados.\')\n                return records,{\'results\':records,\'paths\':[],\'segments\':[],\'document_points\':[]}\n        except Exception as exc:logger(f\'AVISO: GeoJSON LDE no utilizable: {exc}\')\n\n    # Tercera alternativa: documentos legibles seleccionados de las ST oficiales.\n    from visor_lde_archivos import build_trace,EXTENSIONS\n    paths=[]\n    seen=set()\n    for st in st_bdit:\n        sid=str(st[\'id\'])\n        root=folder/(\'ST_\'+sid)\n        if not root.is_dir():continue\n        for p in root.rglob(\'*\'):\n            if not p.is_file() or p.suffix.lower() not in EXTENSIONS:continue\n            if \'.cache\' in p.parts or p.name.startswith(\'~$\'):continue\n            if p.name.lower().startswith((\'reporte_\',\'control_\')):continue\n            if p not in seen:paths.append(p);seen.add(p)\n    if not paths:raise ValueError(\'No existe un trazado LDE procesado ni anexos LDE legibles de las ST de esta línea.\')\n    result=build_trace(paths,progress=lambda i,n,msg:logger(f\'LDE | {i}/{n}: {msg}\'))\n    if not result[\'points\']:raise ValueError(\'Los documentos disponibles no contienen coordenadas LDE georreferenciables.\')\n    from visor_lde_archivos import save_trace\n    save_trace(result,folder/f\'Trazado_Anexos_LT{line_id}.geojson\')\n    rows=[]\n    for i,p in enumerate(result[\'points\'],1):\n        row=dict(p)\n        row[\'st\']=str(p.get(\'seccion_bdit\') or p.get(\'st\') or \'\')\n        row[\'fila\']=p.get(\'fila\') or i\n        row[\'orden_lde\']=p.get(\'orden_global\') or i\n        rows.append(row)\n    snapshot={\'results\':rows,\n      \'paths\':[{\'st\':q.get(\'seccion\') or \'\', \'coords\':q[\'coords\'],\n               \'nombre\':q.get(\'archivo\') or \'\'} for q in result[\'paths\']],\n      \'segments\':[{\'st\':v.get(\'seccion\') or \'\', \'a\':v[\'a\'],\'b\':v[\'b\'],\n                   \'nodo1\':v[\'desde\'],\'nodo2\':v[\'hasta\'],\n                   \'longitud_m\':v[\'longitud_m\'],\'estado\':v[\'estado\']} for v in result[\'spans\']],\n      \'bd_paths\':[],\'bd_points\':[],\'bd_segments\':[],\'document_points\':[],\'mode\':\'DOCUMENTOS_SIN_BDATX\'}\n    cache.parent.mkdir(parents=True,exist_ok=True)\n    cache.write_text(json.dumps(snapshot,ensure_ascii=False),encoding=\'utf-8\')\n    logger(f\'LDE | Nuevo trazado leído: {len(rows)} estructuras, {len(result["spans"])} vanos.\')\n    return rows,snapshot\n\n\ndef propietario_bdit(st):\n    """Propietario registrado en la sección BDIT: nunca se sustituye por coordinado."""\n    if not isinstance(st,dict):return \'\', \'\'\n    value=st.get(\'propietario_nombre\')\n    pid=st.get(\'id_propietario\')\n    if not value:\n        p=st.get(\'propietario\')\n        if isinstance(p,dict):\n            value=p.get(\'nombre\') or p.get(\'name\') or \'\'\n            if not pid:pid=p.get(\'id\')\n    return str(pid) if pid not in (None,\'\') else \'\',str(value or \'\')\n\n\ndef propietario_bdatx(t):\n    """Propietario del registro TORRE BDATx (no el del tramo)."""\n    p=t.get(\'propietario\') or {}\n    if not isinstance(p,dict):p={\'name\':p}\n    pid=t.get(\'propietario_id\') or p.get(\'id\') or \'\'\n    return str(pid),str(p.get(\'name\') or p.get(\'nombre\') or \'\')\n\n\ndef generate(line_id, ins=INS, out=None, logger=print):\n    line_id=int(line_id)\n    if out is None:out=line_folder(line_id,ins)\n    # El LDE es la referencia y nunca se reemplaza por una descarga BDATx.\n    lde=None;snapshot=None\n    try:\n        lde,snapshot=leer_lde_consolidado(line_id,[],logger)\n    except ValueError:\n        logger(\'LDE: no existe un trazado previo; se buscarán anexos por ST tras consultar la línea.\')\n    d=load_data(ins,line_id,logger)\n    line=next((x for x in d[\'lineas_bdit\'] if str(x.get(\'id\'))==str(line_id)),None)\n    if not line:raise ValueError(f"Línea {line_id} no disponible en BDIT")\n    st_bdit=sorted(d[\'st_bdit\'],key=lambda x:int(x[\'id\']))\n    if lde is None:\n        lde,snapshot=leer_lde_consolidado(line_id,st_bdit,logger)\n    # Respetar las ST del LDE incluso si una ficha de BDIT no pudo consultarse.\n    existing_st={str(st[\'id\']) for st in st_bdit}\n    for st_code in dict.fromkeys(str(x.get(\'st\') or \'\') for x in lde):\n        if st_code and st_code not in existing_st:\n            st_bdit.append({\'id\':st_code,\'nombre\':\'ST de anexo LDE (propietario BDIT no consultado)\'})\n            logger(f\'AVISO: ST {st_code} proviene del LDE pero no hay ficha BDIT; propietario no verificado.\')\n            existing_st.add(st_code)\n    # Nunca se reordena el LDE según el nombre de las torres BDATx.\n\n    bdline=next((x for x in d[\'lineas_bdatx\'] if str(x.get(\'inf_id\'))==str(line_id)),None)\n    if not bdline:raise ValueError(f\'Línea BDIT {line_id} sin correspondencia en BDATx: no se inventan relaciones\')\n    lid=bdline[\'id\']; logger(f\'Línea BDATx {lid}; ST BDIT {[x["id"] for x in st_bdit]}\')\n    # Contraste SOLO TORRES: no se consultan ni procesan tramos/vanos BDATx.\n    tramos=[]\n    vanos=[]\n    torres=d[\'torres_bdatx\']\n    if not torres:\n        logger(f\'AVISO BDATx | Línea {lid}: inventario de torres vacío tras verificar filtros y paginación. Se conserva el LDE.\')\n    associations=defaultdict(set)\n    # lde proviene del trazado almacenado en la lectura inicial, no se vuelve\n    # a buscar un Excel por patrón de nombre ni se pierde un LDE extraído de RAR.\n    if not lde:raise ValueError(\'No hay estructuras LDE georreferenciables; conserva el mapa y revisa los anexos\')\n    out.mkdir(parents=True,exist_ok=True)\n    logger(f\'Comparación geográfica: {len(lde)} estructuras LDE y {len(torres)} torres BDATx; sin tramos ni vanos BDATx\')\n    # Canonical single-pass reconciliation. No other UI/Excel function may reassign IDs.\n    canonical=reconcile(lde,torres,tramos,vanos,CATALOGO_ZONA_HUSO,\n                        threshold=5.0,linea_id=lid,inventory_complete=d.get(\'inventario_torres_completo\',False),\n                        only_towers=True)\n    logger(\'CONCILIACION TORRES | \'+str(canonical[\'summary\'])+\n           f" | LDE: {canonical[\'counts\'][\'lde_rows\']} estructuras documentales; BDATx: {len(torres)} torres")\n    results=[]\n    groups=defaultdict(list)\n    for src in canonical[\'rows\']:\n        x=dict(src)\n        x[\'clave\']=structure_key(x.get(\'nombre\'))\n        bdit_st=next((st for st in st_bdit if str(st.get(\'id\'))==str(x.get(\'st\'))),None)\n        x[\'id_propietario_bdit\'],x[\'propietario_bdit\']=propietario_bdit(bdit_st)\n        bd_tower=next((t for t in torres if str(t.get(\'id\'))==str(x.get(\'id_torre\'))),None)\n        x[\'id_propietario_bdatx\'],x[\'propietario_bdatx\']=propietario_bdatx(bd_tower or {})\n        x[\'tramos_torre\']=\',\'.join(map(str,x.get(\'tramos_torre\') or []))\n        x[\'tramos_asociados_ids\']=list(x.get(\'tramos_lde\') or [])\n        x[\'torre_bdatx_compartida\']=\'SI\' if len(x.get(\'tramos_torre\') or [])>1 else \'NO\'\n        x[\'referencia_estructura_compartida\']=\'\'\n        x[\'alerta\']=\'; \'.join(z for z in (str(x.get(\'alerta\') or \'\'),x.get(\'observacion_conciliacion\') or \'\') if z)\n        results.append(x)\n        groups[x[\'physical_id\']].append(x)\n    for rs in groups.values():\n        if len(rs)>1:\n            ref=\'; \'.join(\'ST\'+str(x[\'st\'])+\' \'+str(x[\'nombre\']) for x in rs)\n            for x in rs:x[\'referencia_estructura_compartida\']=ref\n    associations=defaultdict(set)\n    for tid,trs in canonical[\'tower_tramos\'].items():\n        tid=int(tid) if str(tid).isdigit() else tid\n        for tr in trs:associations[tid].add(int(tr) if str(tr).isdigit() else tr)\n    tower_coords={}\n    for tid,t in canonical[\'tower_normalized\'].items():\n        if t[\'este\'] is not None:\n            tower_coords[int(tid) if str(tid).isdigit() else tid]=(t[\'este\'],t[\'norte\'])\n    st_groups=defaultdict(list)\n    for x in results:st_groups[str(x[\'st\'])].append(x)\n    # No hay propuestas de creacion ni nombres de nuevas torres: solo contraste.\n    for x in results:\n        x[\'criterio_nombre\']=\'\'\n        x[\'nombre_sugerido\']=\'\'\n    # GEOMETRIAS: exclusivamente desde los LDE. BDATx aporta atributos/estados, nunca vertices.\n    segments=[]; geo=[]; paths=[]; st_lookup={x[\'id\']:x for x in st_bdit}\n    for st in st_bdit:\n        stid=st[\'id\']; group=[x for x in results if str(x[\'st\'])==str(stid)]\n        valid=[x for x in group if x[\'lat\'] is not None and x[\'lon\'] is not None]\n        bdit_owner_id,bdit_owner_name=propietario_bdit(st)\n        for p in group:\n            geo.append({\'type\':\'Feature\',\'properties\':{\n                \'tipo\':\'torre_LDE\' if not p[\'marco\'] else \'marco_LDE\',\n                \'st_bdit\':stid,\'linea_bdit\':line_id,\'estructura\':p[\'nombre\'],\n                \'fila_lde\':p[\'fila\'],\'estado_bdatx\':p[\'estado\'],\n                \'id_torre_bdatx\':p[\'id_torre\'],\'id_fisico_lde\':p[\'physical_id\'], \'accion_bdatx\':p[\'accion\'],\'este_lde\':p[\'este\'],\n                \'norte_lde\':p[\'norte\'],\'huso_lde\':p[\'huso\'],\n                \'id_propietario_bdit\':bdit_owner_id,\'propietario_bdit\':bdit_owner_name,\n                \'id_propietario_bdatx\':propietario_bdatx(next((t for t in torres if str(t.get(\'id\'))==str(p.get(\'id_torre\'))),{}))[0],\n                \'propietario_bdatx\':propietario_bdatx(next((t for t in torres if str(t.get(\'id\'))==str(p.get(\'id_torre\'))),{}))[1],\n                \'origen_geometria\':\'LDE\'},\n                \'geometry\':{\'type\':\'Point\',\'coordinates\':[p[\'lon\'],p[\'lat\']]} if p[\'lat\'] is not None else None})\n        # Separa la geometria si hay coordenadas invalidas entre dos filas del LDE.\n        runs=[]; run=[]\n        current_doc=None\n        for p in group:\n            doc=p.get(\'archivo\') or \'\'\n            if current_doc is not None and doc!=current_doc and run:\n                runs.append(run);run=[]\n            current_doc=doc\n            if p[\'lat\'] is None:\n                if run:runs.append(run);run=[]\n            else:run.append(p)\n        if run:runs.append(run)\n        for seq in runs:\n            if len(seq)<2:continue\n            coords=[[p[\'lon\'],p[\'lat\']] for p in seq]\n            paths.append({\'st\':stid,\'coords\':coords,\'nombres\':[p[\'nombre\'] for p in seq]})\n            geo.append({\'type\':\'Feature\',\'properties\':{\'tipo\':\'seccion_LDE\',\'st_bdit\':stid,\n                \'linea_bdit\':line_id,\'nombre\':st[\'nombre\'],\n                \'id_propietario_bdit\':bdit_owner_id,\'propietario_bdit\':bdit_owner_name,\n                \'origen_geometria\':\'LDE\'},\n                \'geometry\':{\'type\':\'LineString\',\'coordinates\':coords}})\n            for a,b in zip(seq,seq[1:]):\n                dd=dist(a,b)\n                status=\'REVISAR_LONGITUD\' if dd is not None and dd>1000 else \'REFERENCIAL\'\n                segments.append(dict(st=stid,origen=a[\'nombre\'],destino=b[\'nombre\'],\n                    longitud_m=round(dd,2) if dd is not None else None,estado=status))\n                geo.append({\'type\':\'Feature\',\'properties\':{\'tipo\':\'vano_LDE\',\n                    \'linea_bdit\':line_id,\'st_bdit\':stid,\'nodo1_lde\':a[\'nombre\'],\n                    \'nodo2_lde\':b[\'nombre\'],\'longitud_m\':round(dd,2) if dd is not None else None,\n                    \'estado\':status,\'origen_geometria\':\'LDE\',\'vano_bdatx_id\':None},\n                    \'geometry\':{\'type\':\'LineString\',\'coordinates\':[[a[\'lon\'],a[\'lat\']],[b[\'lon\'],b[\'lat\']]]}})\n    # No unir extremos de ST distintas por proximidad ni crear vanos no documentados.\n    section_lines=[f[\'geometry\'][\'coordinates\'] for f in geo if f[\'properties\'][\'tipo\']==\'seccion_LDE\']\n    if section_lines:\n        geo.insert(0,{\'type\':\'Feature\',\'properties\':{\'tipo\':\'linea_LDE\',\'linea_bdit\':line_id,\n            \'nombre\':line[\'nombre\'],\'origen_geometria\':\'LDE\',\'nota\':\'Partes por ST; no se inventan conexiones entre secciones\'},\n            \'geometry\':{\'type\':\'MultiLineString\',\'coordinates\':section_lines}})\n    bd_geo=[];bd_paths=[];bd_points=[];bd_segments=[]\n    tower_map={t[\'id\']:t for t in torres}\n    st_by_tramo={t[\'id\']:t.get(\'inf_id\') for t in tramos}\n    for t in torres:\n        tid=t[\'id\'];coord=tower_coords.get(tid)\n        st_ids=sorted({st_by_tramo[k] for k in associations.get(tid,set()) if k in st_by_tramo and st_by_tramo[k] is not None})\n        info=convertir_torre_bdatx(t)\n        ll=[info[\'lon\'],info[\'lat\']] if info[\'lon\'] is not None else None\n        owner_id_bd,owner_name_bd=propietario_bdatx(t)\n        rec={\'id\':tid,\'nombre\':t.get(\'name\') or t.get(\'nombre\') or \'\',\n             \'id_propietario_bdatx\':owner_id_bd,\'propietario_bdatx\':owner_name_bd,\n             \'st\':st_ids,\'este\':info[\'este\'],\'norte\':info[\'norte\'],\n             \'huso\':info[\'huso\'],\'huso_uuid\':info[\'huso_uuid\'],\'epsg\':info[\'epsg\'],\n             \'lon\':info[\'lon\'],\'lat\':info[\'lat\'],\'estado\':info[\'estado\']}\n        if info[\'estado\']!=\'OK_CATALOGO\':\n            logger(f\'ALERTA TORRE BDATx {tid}: {info["estado"]}; zonaOHuso={info["huso_uuid"]}. No se inferirán coordenadas.\')\n        bd_points.append(rec)\n        bd_geo.append({\'type\':\'Feature\',\'properties\':{\'tipo\':\'torre_BDATX\',\'origen_geometria\':\'BDATX\',\'id_torre\':tid,\'nombre\':t.get(\'name\') or t.get(\'nombre\') or \'\',\n            \'id_propietario_bdatx\':owner_id_bd,\'propietario_bdatx\':owner_name_bd,\n            \'st_bdit\':st_ids,\'linea_bdatx\':lid,\'estado\':rec[\'estado\'],\'huso\':rec[\'huso\'],\'huso_uuid\':rec[\'huso_uuid\'],\'epsg\':rec[\'epsg\'],\'este\':rec[\'este\'],\'norte\':rec[\'norte\']},\'geometry\':{\'type\':\'Point\',\'coordinates\':ll} if ll else None})\n    # El GeoJSON BDATx contiene exclusivamente puntos de TORRE. El trazado\n    # polilineal y los vanos dibujados siguen siendo los reconstruidos del LDE.\n    bd_fc={\'type\':\'FeatureCollection\',\'features\':bd_geo}\n    # Entregables independientes en WGS84, lon/lat.\n    (out/f\'Trazado_BDIT_LDE_LT{line_id}.geojson\').write_text(\n        json.dumps({\'type\':\'FeatureCollection\',\'features\':geo},ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    bd_path=out/f\'Trazado_BDATX_LT{line_id}.geojson\'\n    if not any(f.get(\'geometry\') for f in bd_geo):\n        bd_fc[\'metadata\']={\'estado\':\'SIN_GEOMETRIAS_BDATX\',\'detalle\':\'No se obtuvieron torres BDATx con coordenadas válidas; el trazado LDE se mantiene.\'}\n    bd_path.write_text(json.dumps(bd_fc,ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    logger(f\'GeoJSON BDATx: {bd_path} ({len(bd_geo)} entidades)\')\n    legacy=out/f\'Trazados_LDE_BDATX_LT{line_id}.geojson\'\n    if legacy.exists():legacy.unlink()\n    logger(f\'Geometría BDATx: {len(bd_points)} torres ({sum(x["lon"] is not None for x in bd_points)} con coordenadas); sin consultas de vanos.\')\n    # Archivo de trabajo interno para volver a abrir el visor sin recalcular.\n    cache=line_folder(line_id)/\'.cache\';cache.mkdir(parents=True,exist_ok=True)\n    (cache/f\'Analisis_LT{line_id}.json\').write_text(json.dumps(\n        {\'results\':results,\'paths\':paths,\'segments\':segments,\'bd_paths\':bd_paths,\n         \'bd_points\':bd_points,\'bd_segments\':bd_segments,\'mode\':\'CONTRASTE_BDATX\',\n         \'documentos_lde_validos\':len(lde)},ensure_ascii=False),encoding=\'utf-8\')\n    # Export: one workbook produced from immutable canonical decisions.\n    wb=Workbook()\n    wb.remove(wb.active)\n    organizar_reporte_consultor(wb,canonical=canonical,line=line,bdline=bdline,\n        st_bdit=st_bdit,tramos=tramos,torres=torres,vanos=vanos,\n        segments=segments,catalog=CATALOGO_ZONA_HUSO)\n    wb.save(out/f\'Reporte_LT{line_id}.xlsx\')\n    logger(\'Resultados: \'+str(Counter(x[\'estado\'] for x in results)))\n    return out\n\n\n\ndef organizar_reporte_consultor(wb, *, canonical, line, bdline, st_bdit, tramos, torres, vanos, segments, catalog):\n    """Reporte V1 sencillo: inventario LDE por ST + torres BDATx sin pareja.\n\n    No propone creaciones, no consulta tramos/vanos BDATx y solo informa\n    coincidencias espaciales únicas (<= 5 m). Una torre LDE compartida entre\n    distintas ST se muestra en cada ST para conservar el orden documental.\n    """\n    from collections import Counter\n    from openpyxl.styles import PatternFill, Font, Alignment\n    from openpyxl.utils import get_column_letter\n\n    rows_lde=canonical[\'rows\']\n    tower_info=canonical[\'tower_normalized\']\n    owners_st={str(st.get(\'id\')):st for st in st_bdit}\n    towers_by_id={str(t.get(\'id\')):t for t in torres if t.get(\'id\') is not None}\n    line_bdit=line.get(\'id\')\n    line_bdatx=bdline.get(\'id\')\n\n    # Orden: primera aparición de cada sección en el LDE, y luego sus filas\n    # en el orden original. NO ordenar por nombre ni por ID de torre BDATx.\n    st_order={}\n    for row in rows_lde:\n        st_order.setdefault(str(row.get(\'st\') or \'\'), len(st_order))\n    ordered=sorted(enumerate(rows_lde),\n                   key=lambda item:(st_order[str(item[1].get(\'st\') or \'\')],item[0]))\n    matched_ids={str(r[\'id_torre\']) for r in rows_lde if r.get(\'id_torre\') not in (None,\'\')}\n    adicionales=[t for t in torres if str(t.get(\'id\')) not in matched_ids]\n\n    def blank(v):\n        return \'\' if v is None else v\n\n    def estado(r):\n        state=r.get(\'estado\') or \'\'\n        if state==\'EXISTENTE\':return \'COINCIDE\'\n        if state==\'REVISAR_ASOCIACION\':return \'AMBIGUO (<=5 m)\'\n        if state==\'SIN_COINCIDENCIA_BDATX\':return \'NO COINCIDE\'\n        if state==\'SIN_TORRES_BDATX\':return \'SIN TORRES BDATX\'\n        if state==\'MARCO\':return \'MARCO LDE\'\n        if state in (\'REVISAR_COORDENADAS_LDE\',\'REVISAR_DATUM_LDE\'):\n            return \'COORDENADAS LDE NO COMPARABLES\'\n        if state in (\'REVISAR_INVENTARIO_BDATX\',\'CONSULTA_INCOMPLETA\'):\n            return \'NO VERIFICABLE\'\n        return \'REVISAR COORDENADAS\'\n\n    headers=[\n        \'ORIGEN\',\'ID_SECCION_BDIT\',\'NOMBRE_SECCION_BDIT\',\'ORDEN_LDE\',\'ESTRUCTURA_LDE\',\n        \'PROPIETARIO_BDIT_ST\',\n        \'ESTE_LDE\',\'NORTE_LDE\',\'HUSO_LDE\',\'LAT_LDE\',\'LON_LDE\',\n        \'ID_TORRE_BDATX\',\'NOMBRE_TORRE_BDATX\',\'PROPIETARIO_BDATX_TORRE\',\n        \'ESTE_BDATX\',\'NORTE_BDATX\',\'HUSO_BDATX\',\'LAT_BDATX\',\'LON_BDATX\',\n        \'DISTANCIA_M\',\'COINCIDENCIA\',\'OBSERVACION\'\n    ]\n    records=[]; counts=Counter()\n    for original_index,r in ordered:\n        sid=str(r.get(\'st\') or \'\')\n        st=owners_st.get(sid,{})\n        _bid, bdit_owner=propietario_bdit(st)\n        tid=r.get(\'id_torre\')\n        t=towers_by_id.get(str(tid)) if tid not in (None,\'\') else None\n        n=tower_info.get(str(tid),{}) if t else {}\n        _id, tower_owner=propietario_bdatx(t or {})\n        current_state=estado(r)\n        counts[current_state]+=1\n        # Los IDs candidatos por proximidad son solo orientativos si el cruce\n        # no es único. No se escriben como ID_TORRE_BDATX confirmado.\n        possible=r.get(\'id_candidatos\') or []\n        note=str(r.get(\'observacion_conciliacion\') or \'\').strip()\n        if current_state==\'AMBIGUO (<=5 m)\':\n            if not possible and r.get(\'id_bdatx_candidato\') is not None:\n                possible=[r[\'id_bdatx_candidato\']]\n            if possible:\n                note=(note+\' | \' if note else \'\')+\'IDs BDATx cercanos: \'+\', \'.join(map(str,possible))\n        if r.get(\'alerta\'):\n            note=(note+\' | \' if note else \'\')+str(r[\'alerta\'])\n        records.append([\n            \'LDE\',sid,st.get(\'nombre\') or st.get(\'name\') or \'\',\n            blank(r.get(\'fila\') or r.get(\'orden_lde\') or original_index+1),\n            r.get(\'nombre\') or \'\',bdit_owner,\n            blank(r.get(\'este\')),blank(r.get(\'norte\')),blank(r.get(\'huso\')),\n            blank(r.get(\'lat\')),blank(r.get(\'lon\')),\n            blank(tid),t.get(\'name\') or t.get(\'nombre\') or \'\' if t else \'\',tower_owner,\n            blank(n.get(\'este\')),blank(n.get(\'norte\')),blank(n.get(\'huso\')),\n            blank(n.get(\'lat\')),blank(n.get(\'lon\')),\n            blank(r.get(\'distancia_m\')),current_state,note\n        ])\n\n    # Sin consultar tramos BDATx no es posible adjudicar una torre adicional\n    # a una ST: estos campos permanecen vacíos, sin suposiciones por cercanía.\n    for t in adicionales:\n        tid=str(t.get(\'id\'))\n        n=tower_info.get(tid,{})\n        _owner_id,tower_owner=propietario_bdatx(t)\n        records.append([\n            \'SOLO BDATX\',\'\',\'\',\'\',\'\',\'\',\n            \'\',\'\',\'\',\'\',\'\',\n            blank(t.get(\'id\')),t.get(\'name\') or t.get(\'nombre\') or \'\',tower_owner,\n            blank(n.get(\'este\')),blank(n.get(\'norte\')),blank(n.get(\'huso\')),\n            blank(n.get(\'lat\')),blank(n.get(\'lon\')),\n            \'\',\'SOLO BDATX\',\'Sin coincidencia LDE confirmada; ST no atribuida automáticamente\'\n        ])\n    counts[\'SOLO BDATX\']=len(adicionales)\n\n    for sheet in list(wb):\n        del wb[sheet.title]\n    help_sheet=wb.create_sheet(\'00_GUIA\')\n    guide=[\n        (\'CAMPO\',\'EXPLICACION\'),\n        (\'01_COMPARACION_TORRES\',\'Una fila por estructura de cada sección LDE, seguida de las torres BDATx adicionales.\'),\n        (\'ORDEN\',\'Secciones agrupadas en el orden del LDE; se mantiene el orden original de las estructuras.\'),\n        (\'COINCIDE\',\'Una única torre BDATx a 5 metros o menos de la estructura LDE.\'),\n        (\'NO COINCIDE\',\'No se encontró torre BDATx a 5 m; solo cuando el inventario es comparable.\'),\n        (\'AMBIGUO (<=5 m)\',\'Hay más de un candidato o conflicto de asignación; no se asigna ID arbitrariamente.\'),\n        (\'SOLO BDATX\',\'Torre recuperada de BDATx sin asociación geométrica confirmada al LDE.\'),\n        (\'PROPIETARIOS\',\'El propietario de ST se toma de BDIT; el propietario de torre se toma de BDATx.\'),\n        (\'SECCION EN SOLO BDATX\',\'Queda sin asignar porque no se consultan tramos ni vanos BDATx.\'),\n        (\'COORDENADAS\',\'Las coordenadas Este/Norte corresponden a UTM y LAT/LON a WGS84. BDATx usa el catálogo UUID de husos.\'),\n        (\'CONTROL\',\'Este reporte NO genera propuestas de creación de torres.\'),\n    ]\n    for row in guide:help_sheet.append(row)\n\n    sheet=wb.create_sheet(\'01_COMPARACION_TORRES\')\n    sheet.append(headers)\n    for row in records:sheet.append(row)\n\n    summary=wb.create_sheet(\'02_RESUMEN\')\n    facts=[\n        (\'INDICADOR\',\'VALOR\'),\n        (\'Línea BDIT\',line_bdit),\n        (\'Línea BDATx\',line_bdatx),\n        (\'Secciones BDIT en LDE\',len(st_order)),\n        (\'Estructuras documentales LDE\',len(rows_lde)),\n        (\'Torres BDATx de la línea\',len(torres)),\n        (\'Coincidencias por coordenadas\',counts[\'COINCIDE\']),\n        (\'LDE sin coincidencia\',counts[\'NO COINCIDE\']),\n        (\'Coincidencias ambiguas\',counts[\'AMBIGUO (<=5 m)\']),\n        (\'Otros estados LDE\',len(rows_lde)-counts[\'COINCIDE\']-counts[\'NO COINCIDE\']-counts[\'AMBIGUO (<=5 m)\']),\n        (\'Torres BDATx adicionales\',len(adicionales)),\n        (\'Tolerancia\', \'5 m\'),\n        (\'Propuestas de creación\', \'NO SE GENERAN\'),\n        (\'API tramos y vanos BDATx\', \'NO CONSULTADAS\'),\n    ]\n    for row in facts:summary.append(row)\n\n    widths={\n        \'ORIGEN\':15,\'ID_SECCION_BDIT\':17,\'NOMBRE_SECCION_BDIT\':36,\'ORDEN_LDE\':14,\n        \'ESTRUCTURA_LDE\':24,\'PROPIETARIO_BDIT_ST\':35,\n        \'ESTE_LDE\':17,\'NORTE_LDE\':17,\'HUSO_LDE\':13,\'LAT_LDE\':17,\'LON_LDE\':17,\n        \'ID_TORRE_BDATX\':19,\'NOMBRE_TORRE_BDATX\':30,\'PROPIETARIO_BDATX_TORRE\':35,\n        \'ESTE_BDATX\':17,\'NORTE_BDATX\':17,\'HUSO_BDATX\':14,\'LAT_BDATX\':17,\'LON_BDATX\':17,\n        \'DISTANCIA_M\':16,\'COINCIDENCIA\':29,\'OBSERVACION\':65,\n    }\n    color={\'COINCIDE\':\'E1F2E2\',\'NO COINCIDE\':\'FFF1CF\',\'AMBIGUO (<=5 m)\':\'FFE3BA\',\n           \'SOLO BDATX\':\'E7EDF4\',\'NO VERIFICABLE\':\'FFE7D6\',\n           \'SIN TORRES BDATX\':\'FFE7D6\',\'COORDENADAS LDE NO COMPARABLES\':\'FFE7D6\'}\n    for sh in (help_sheet,sheet,summary):\n        sh.sheet_view.showGridLines=False\n        sh.freeze_panes=\'A2\'\n        sh.row_dimensions[1].height=31\n        for cell in sh[1]:\n            cell.fill=PatternFill(\'solid\',fgColor=\'17365D\')\n            cell.font=Font(name=\'Aptos\',size=10,bold=True,color=\'FFFFFF\')\n            cell.alignment=Alignment(wrap_text=True,vertical=\'center\')\n        if sh.max_row>1:\n            sh.auto_filter.ref=sh.dimensions if sh is sheet else None\n        for col,header in enumerate([c.value for c in sh[1]],1):\n            if sh is sheet:width=widths.get(header,18)\n            else:width=27 if col==1 else (94 if sh is help_sheet else 25)\n            sh.column_dimensions[get_column_letter(col)].width=width\n    status_col=headers.index(\'COINCIDENCIA\')+1\n    for i in range(2,sheet.max_row+1):\n        state=sheet.cell(i,status_col).value\n        if state in color:\n            for cell in sheet[i]:cell.fill=PatternFill(\'solid\',fgColor=color[state])\n        # Mostrar valores métricos con una precisión razonable.\n        for colname in (\'ESTE_LDE\',\'NORTE_LDE\',\'ESTE_BDATX\',\'NORTE_BDATX\',\'DISTANCIA_M\'):\n            col=headers.index(colname)+1\n            if isinstance(sheet.cell(i,col).value,(int,float)):\n                sheet.cell(i,col).number_format=\'#,##0.000\'\n        for colname in (\'LAT_LDE\',\'LON_LDE\',\'LAT_BDATX\',\'LON_BDATX\'):\n            col=headers.index(colname)+1\n            if isinstance(sheet.cell(i,col).value,(int,float)):\n                sheet.cell(i,col).number_format=\'0.00000000\'\n    return dict(counts)\n\ndef draw_map(ax,results,paths,segments,show_labels=False,show_towers=True,show_vanos=True,show_sections=True,show_chile=True,bd_paths=None,bd_points=None,mode=\'Ambos\'):\n    """Representación métrica en WGS84; sin teselas externas ni geometría BDATx."""\n    # Eliminar ejes auxiliares de localización creados en redibujos anteriores.\n    for extra in list(ax.figure.axes):\n        if extra is not ax: extra.remove()\n    ax.clear();ax.set_facecolor(\'#f8fafc\')\n    if mode in (\'BDATx\',\'Ambos\') and bd_paths and show_vanos:\n        for bp in bd_paths:\n            if not isinstance(bp,dict):continue\n            for j,line in enumerate(bp.get(\'lines\') or []):\n                if not line:continue\n                ax.plot([q[0] for q in line],[q[1] for q in line],color=\'#e11d48\',linewidth=1.4,alpha=.65,linestyle=\'--\',zorder=4,label=\'Vanos BDATx\' if j==0 and bp==bd_paths[0] else None)\n    if mode in (\'BDATx\',\'Ambos\') and bd_points and show_towers:\n        q=[p for p in bd_points if isinstance(p,dict) and p.get(\'lon\') is not None and p.get(\'lat\') is not None]\n        if q:ax.scatter([p[\'lon\'] for p in q],[p[\'lat\'] for p in q],s=21,marker=\'x\',c=\'#be123c\',zorder=7,label=f\'Torres BDATx ({len(q)})\')\n    if mode in (\'LDE\',\'Ambos\'):\n        for p in (paths or []):\n            if not isinstance(p,dict):continue\n            xy=p.get(\'coords\') or []\n            if len(xy)<2:continue\n            from matplotlib import colormaps\n            st_ids=sorted({z[\'st\'] for z in (paths or []) if isinstance(z,dict) and z.get(\'st\') is not None})\n            color=COLORS.get(p[\'st\'],colormaps[\'tab10\'](st_ids.index(p[\'st\'])%10))\n            if show_sections:\n                ax.plot([v[0] for v in xy],[v[1] for v in xy],\n                    color=color,linewidth=2.3,alpha=.75,zorder=2,\n                    label=f\'Sección {p["st"]} · LDE\')\n                if show_labels:\n                    center=xy[len(xy)//2]\n                    ax.annotate(\'ST \'+str(p[\'st\']),center,xytext=(7,9),\n                        textcoords=\'offset points\',fontsize=9,fontweight=\'bold\',color=color,\n                        bbox=dict(boxstyle=\'round,pad=.2\',facecolor=\'white\',alpha=.8,edgecolor=\'none\'))\n            if show_vanos:\n                for i,(a,b) in enumerate(zip(xy,xy[1:]),1):\n                    dlon=(a[0]-b[0])*111320*math.cos(math.radians((a[1]+b[1])/2))\n                    dlat=(a[1]-b[1])*111320\n                    gap=math.hypot(dlon,dlat)>1000\n                    ax.plot([a[0],b[0]],[a[1],b[1]],color=\'#dc2626\' if gap else \'#f59e0b\',\n                        linewidth=3 if gap else 1.4,alpha=.95,zorder=4 if gap else 3,linestyle=\'--\',\n                        label=\'POSIBLE SALTO (>1 km)\' if gap else (\'Vanos reconstruidos desde LDE\' if i==1 and p is paths[0] else None))\n                    if show_labels and i % max(1,len(xy)//18)==0:\n                        ax.annotate(str(i),((a[0]+b[0])/2,(a[1]+b[1])/2),\n                                    fontsize=6,color=\'#92400e\')\n    pts=[p for p in (results or []) if isinstance(p,dict) and p.get(\'lon\') is not None and p.get(\'lat\') is not None]\n    color_state={\'EXISTENTE\':\'#15803d\',\'MARCO\':\'#64748b\',\'REVISAR_POSIBLE_DUPLICADO\':\'#f59e0b\',\'REVISAR_ASOCIACION\':\'#dc2626\',\'OK\':\'#15803d\',\'COMPLETAR_COORDENADAS\':\'#f59e0b\',\n        \'REVISAR_COORDENADAS\':\'#dc2626\',\n        \'REVISAR_COINCIDENCIA_MULTIPLE\':\'#b91c1c\',\'MARCO_EXCLUIDO\':\'#64748b\'}\n    if mode in (\'LDE\',\'Ambos\') and show_towers:\n        for state in sorted(set(p[\'estado\'] for p in pts)):\n            q=[p for p in pts if p[\'estado\']==state]\n            ax.scatter([p[\'lon\'] for p in q],[p[\'lat\'] for p in q],s=24,\n                c=color_state.get(state,\'#2563eb\'),edgecolors=\'white\',linewidths=.45,\n                zorder=5,label=f\'{state} ({len(q)})\',picker=5)\n        if show_labels:\n            step=max(1,math.ceil(len(pts)/35))\n            for p in pts[::step]:\n                ax.annotate(str(p[\'nombre\']), (p[\'lon\'],p[\'lat\']),\n                            xytext=(4,3),textcoords=\'offset points\',fontsize=7)\n    if pts or bd_points or paths:\n        allcoords=[(p[\'lon\'],p[\'lat\']) for p in pts if p.get(\'lon\') is not None and p.get(\'lat\') is not None]\n        allcoords += [(p[\'lon\'],p[\'lat\']) for p in (bd_points or []) if isinstance(p,dict) and p.get(\'lon\') is not None and p.get(\'lat\') is not None]\n        if not allcoords:allcoords=[xy for path in (paths or []) if isinstance(path,dict) for xy in (path.get(\'coords\') or [])]\n        lons=[p[0] for p in allcoords];lats=[p[1] for p in allcoords]\n        dx=max(max(lons)-min(lons),.025);dy=max(max(lats)-min(lats),.025)\n        ax.set_xlim(min(lons)-dx*.12,max(lons)+dx*.12)\n        ax.set_ylim(min(lats)-dy*.12,max(lats)+dy*.12)\n        lat0=sum(lats)/len(lats)\n        ax.set_aspect(\'auto\')  # Evita comprimir el trazado en una franja al utilizar ventanas panorámicas\n    ax.grid(True,alpha=.2)\n    ax.set_xlabel(\'Longitud (° O) · WGS84\');ax.set_ylabel(\'Latitud (° S) · WGS84\')\n    ax.set_title(\'Secciones y vanos LDE · comparación BDATx\',fontsize=11)\n    handles,labels=ax.get_legend_handles_labels()\n    if handles:ax.legend(loc=\'best\',fontsize=7,framealpha=.88)\n    if show_chile:\n        # Localizador por extensión geográfica de Chile; no simula frontera política.\n        from matplotlib.patches import Rectangle\n        from mpl_toolkits.axes_grid1.inset_locator import inset_axes\n        inset=inset_axes(ax,width=\'17%\',height=\'32%\',loc=\'lower left\',borderpad=1.4)\n        inset.set_facecolor(\'#eaf4fa\')\n        inset.set_xlim(-81,-65);inset.set_ylim(-57,-16)\n        inset.add_patch(Rectangle((-76,-56),10,39,facecolor=\'#d5e8d1\',edgecolor=\'#779b75\',alpha=.75))\n        if pts:\n            inset.scatter([sum(p[\'lon\'] for p in pts)/len(pts)],\n                [sum(p[\'lat\'] for p in pts)/len(pts)],s=30,c=\'#dc2626\',zorder=5)\n        inset.set_title(\'Chile · ubicación aprox.\',fontsize=7)\n        inset.set_xticks([]);inset.set_yticks([])\n        for spine in inset.spines.values():spine.set_edgecolor(\'#94a3b8\')\n    return pts\n\ndef main(parent=None, embedded=False):\n    import argparse\n    parser=argparse.ArgumentParser();parser.add_argument(\'--linea\',type=int,default=None)\n    parser.add_argument(\'--sin-interfaz\',action=\'store_true\');args=parser.parse_args([] if embedded else None)\n    if args.sin_interfaz:\n        if args.linea is None:parser.error(\'Falta --linea ID\')\n        generate(args.linea);return\n    import tkinter as tk\n    from tkinter import ttk,messagebox\n    from matplotlib.figure import Figure\n    from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg,NavigationToolbar2Tk\n    root=ttk.Frame(parent) if embedded else tk.Tk()\n    if not embedded:\n        root.title(\'Piloto · Visor integrado de trazado LDE\');root.geometry(\'1180x780\')\n    # Acción principal única y opciones contextuales: mapa es el área central.\n    header=ttk.Frame(root,padding=(17,11,17,5));header.pack(fill=\'x\')\n    ttk.Label(header,text=\'Analizar línea\',style=\'PageTitle.TLabel\').pack(anchor=\'w\')\n    ttk.Label(header,text=\'Primero dibuja los anexos LDE. Después compara las torres existentes BDATx usando la línea homóloga por inf_id.\',style=\'Subtitle.TLabel\').pack(anchor=\'w\')\n    controls=ttk.Frame(root,style=\'Card.TFrame\',padding=(14,10));controls.pack(fill=\'x\',padx=13,pady=(5,8))\n    line_actions=ttk.Frame(controls,style=\'Card.TFrame\');line_actions.pack(fill=\'x\')\n    ttk.Label(line_actions,text=\'ID de línea BDIT\',style=\'CardLabel.TLabel\').pack(side=\'left\',padx=(0,9))\n    lid=tk.StringVar(value=str(args.linea) if args.linea is not None else \'\')\n    line_entry=ttk.Entry(line_actions,textvariable=lid,width=13)\n    line_entry.pack(side=\'left\',padx=(0,17))\n    action_choice=tk.StringVar(value=\'Solo LDE\')\n    ttk.Label(line_actions,text=\'Primero dibuja · después compara\',style=\'Subtitle.TLabel\').pack(side=\'left\',padx=(0,12))\n    extra_actions=ttk.Frame(controls,style=\'Card.TFrame\')\n    line_entry.bind(\'<Return>\',lambda e:run_selected())\n    show_sections=tk.BooleanVar(value=True);show_vanos=tk.BooleanVar(value=True)\n    show_towers=tk.BooleanVar(value=True);show_chile=tk.BooleanVar(value=False)\n    show_labels=tk.BooleanVar(value=False)\n    body=ttk.PanedWindow(root,orient=\'horizontal\');body.pack(fill=\'both\',expand=True,padx=6,pady=(2,6))\n    left=ttk.Frame(body);body.add(left,weight=8)\n    right=ttk.Frame(body,width=310,padding=(4,1));body.add(right,weight=2)\n    _pane_ready=[False]\n    def _initial_pane_layout(event=None):\n        if not _pane_ready[0] and body.winfo_width()>900:\n            _pane_ready[0]=True\n            body.after_idle(lambda:body.sashpos(0,int(body.winfo_width()*.76)))\n    body.bind(\'<Configure>\',_initial_pane_layout,add=\'+\')\n    # Panel de capas compacto; el registro de actividad ocupa la mayor parte del lateral.\n    options=ttk.Frame(right,padding=9)  # Se muestra solo al abrir la pestaña «Capas»\n    map_tabs=ttk.Notebook(left);map_tabs.pack(fill=\'both\',expand=True)\n    plot_frame=ttk.Frame(map_tabs);esri_frame=ttk.Frame(map_tabs)\n    map_tabs.add(plot_frame,text=\'Mapa de análisis\')\n    map_tabs.add(esri_frame,text=\'Esri · mapa integrado\')\n    fig=Figure(figsize=(9,7),dpi=100);ax=fig.add_subplot(111)\n    canvas=FigureCanvasTkAgg(fig,master=plot_frame);canvas.get_tk_widget().pack(fill=\'both\',expand=True)\n    # TkinterMapView se incrusta de verdad en la pestaña Tkinter; no abre navegador\n    # ni lanza procesos pywebview. La librería es opcional y se detecta al abrir.\n    esri_widget=[None]\n    esri_objects=[]\n    esri_icon_cache={}\n    esri_message=ttk.Label(esri_frame,text=\'Selecciona esta pestaña para cargar Esri.\',\n                           anchor=\'center\',justify=\'center\',wraplength=520)\n    esri_message.pack(fill=\'both\',expand=True,padx=16,pady=16)\n    def initialize_esri():\n        if esri_widget[0] is not None:return True\n        try:\n            from tkintermapview import TkinterMapView\n            esri_message.pack_forget()\n            w=TkinterMapView(esri_frame,corner_radius=0)\n            w.pack(fill=\'both\',expand=True)\n            w.set_tile_server(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}\',max_zoom=19)\n            w.set_position(-33.45,-70.66);w.set_zoom(5)\n            esri_widget[0]=w\n            say(\'Mapa Esri integrado disponible. Las teselas requieren acceso al servidor de Esri.\')\n            return True\n        except ImportError:\n            esri_message.configure(text=\'Para visualizar Esri dentro del aplicativo instala:\\n\\n\'\n                \'python -m pip install tkintermapview\\n\\n\'\n                \'Después reinicia el aplicativo. El mapa de análisis sigue funcionando sin esta biblioteca.\')\n            say(\'Mapa Esri integrado: falta tkintermapview (python -m pip install tkintermapview).\')\n            return False\n        except Exception as exc:\n            esri_message.configure(text=\'No se pudo inicializar Esri:\\n\'+str(exc))\n            say(\'ERROR inicializando Esri integrado: \'+str(exc))\n            return False\n    def refresh_esri(reset_view=True):\n        if esri_widget[0] is None:return\n        w=esri_widget[0]\n        for obj in esri_objects:\n            try:obj.delete()\n            except Exception:pass\n        esri_objects.clear()\n        coords_all=[]\n        def point_icon(source):\n            # Iconos pequeños de 8 px: evita las enormes burbujas predeterminadas.\n            if source not in esri_icon_cache:\n                from PIL import Image, ImageDraw, ImageTk\n                color={\'LDE\':\'#2563eb\',\'BDATx\':\'#ea580c\',\'DOCUMENTO\':\'#16a34a\'}.get(source,\'#475569\')\n                im=Image.new(\'RGBA\',(14,14),(0,0,0,0))\n                d=ImageDraw.Draw(im);d.ellipse((3,3,11,11),fill=color,outline=\'white\',width=1)\n                esri_icon_cache[source]=ImageTk.PhotoImage(im,master=w)\n            return esri_icon_cache[source]\n        def add_path(xy,color,width=3):\n            good=[]\n            for x in (xy or []):\n                try:\n                    lon,lat=float(x[0]),float(x[1])\n                    if -180<=lon<=180 and -90<=lat<=90:\n                        good.append((lat,lon));coords_all.append((lat,lon))\n                except (TypeError,ValueError,IndexError):pass\n            if len(good)>1:esri_objects.append(w.set_path(good,color=color,width=width))\n        if mode.get() in (\'LDE\',\'Ambos\'):\n            if show_sections.get():\n                for path in (state.get(\'paths\') or []):add_path((path or {}).get(\'coords\') or [],\'#2563eb\',3)\n            if show_vanos.get():\n                for path in (state.get(\'paths\') or []):\n                    xy=(path or {}).get(\'coords\') or []\n                    for a,b in zip(xy,xy[1:]):\n                        try:\n                            lon1,lat1=map(float,a);lon2,lat2=map(float,b)\n                            meters=math.hypot((lon1-lon2)*111320*math.cos(math.radians((lat1+lat2)/2)),(lat1-lat2)*111320)\n                            add_path([a,b],\'#dc2626\' if meters>1000 else \'#f59e0b\',3 if meters>1000 else 2)\n                        except (TypeError,ValueError):pass\n        if mode.get() in (\'BDATx\',\'Ambos\'):\n            for path in (state.get(\'bd_paths\') or []):add_path((path or {}).get(\'coords\') or [],\'#ea580c\',3)\n            for seg in (state.get(\'bd_segments\') or []):add_path((seg or {}).get(\'coords\') or [],\'#7c3aed\',2)\n        if show_towers.get():\n            candidates=[]\n            if mode.get() in (\'LDE\',\'Ambos\'):\n                candidates.extend((\'LDE\',p) for p in (state.get(\'pts\') or []) if isinstance(p,dict))\n                candidates.extend((\'DOCUMENTO\',p) for p in (state.get(\'document_points\') or []) if isinstance(p,dict))\n            if mode.get() in (\'BDATx\',\'Ambos\'):\n                candidates.extend((\'BDATx\',p) for p in (state.get(\'bd_points\') or []) if isinstance(p,dict))\n            # A escala regional se muestran puntos representativos para evitar\n            # superposición; con zoom cercano aparecen todas las estructuras.\n            zoom=w.zoom if hasattr(w,\'zoom\') else 12\n            if zoom<=9 and len(candidates)>180:\n                step=max(1,math.ceil(len(candidates)/180))\n                visible_candidates=candidates[::step]\n            else:\n                visible_candidates=candidates\n            for source,p in visible_candidates:\n                try:\n                    lat,lon=float(p[\'lat\']),float(p[\'lon\'])\n                    if not (-90<=lat<=90 and -180<=lon<=180):continue\n                    label=str(p.get(\'nombre\') or p.get(\'name\') or p.get(\'id\') or source)\n                    marker=w.set_marker(lat,lon,text=(label if show_labels.get() and zoom>=14 else \'\'),\n                        icon=point_icon(source),icon_anchor=\'center\',\n                        command=lambda marker,src=source,rec=p:show_esri_detail(src,rec))\n                    esri_objects.append(marker);coords_all.append((lat,lon))\n                except (TypeError,ValueError,KeyError):continue\n        if reset_view and coords_all:\n            lat_min=min(x[0] for x in coords_all);lat_max=max(x[0] for x in coords_all)\n            lon_min=min(x[1] for x in coords_all);lon_max=max(x[1] for x in coords_all)\n            if len(coords_all)>1 and (lat_max-lat_min+lon_max-lon_min)>0.0001:\n                w.fit_bounding_box((lat_max+0.005,lon_min-0.005),(lat_min-0.005,lon_max+0.005))\n            else:w.set_position(coords_all[0][0],coords_all[0][1]);w.set_zoom(14)\n        say(f\'Esri integrado: {len(esri_objects)} elementos visibles. Acerca el zoom para consultar estructuras individuales.\')\n    def on_map_tab_changed(event=None):\n        if map_tabs.select()==str(esri_frame) and initialize_esri():\n            try:refresh_esri()\n            except Exception as exc:\n                import traceback\n                say(\'ERROR visor Esri (mapa de análisis disponible): \'+str(exc))\n                say(traceback.format_exc())\n    map_tabs.bind(\'<<NotebookTabChanged>>\',on_map_tab_changed)\n    def safe_refresh_esri():\n        try:refresh_esri(reset_view=False)\n        except Exception as exc:say(\'AVISO visor Esri: \'+str(exc))\n    def schedule_esri_refresh(event=None):\n        if esri_widget[0] is None:return\n        if getattr(schedule_esri_refresh,\'pending\',None):\n            try:root.after_cancel(schedule_esri_refresh.pending)\n            except Exception:pass\n        schedule_esri_refresh.pending=root.after(350,lambda:safe_refresh_esri())\n    esri_frame.bind(\'<MouseWheel>\',schedule_esri_refresh,add=\'+\')\n\n    # Navegación siempre activa: rueda = zoom, arrastrar = desplazar, clic = consultar.\n    # Los paneles de detalle se colocan después de los controles y la leyenda.\n    # Panel derecho compacto: actividad por defecto, detalle y filtros a demanda.\n    side_tabs=ttk.Notebook(right)\n    detail_frame=ttk.Frame(side_tabs,padding=9)\n    ttk.Label(detail_frame,text=\'Selecciona un elemento sobre el mapa para ver sus atributos.\',style=\'Subtitle.TLabel\',wraplength=260).pack(anchor=\'w\',pady=(0,7))\n    details=tk.Text(detail_frame,height=5,wrap=\'word\',font=(\'Segoe UI\',10))\n    details.pack(fill=\'both\',expand=True)\n    activity_frame=ttk.Frame(side_tabs,padding=7)\n    log_area=ttk.Frame(activity_frame);log_area.pack(fill=\'both\',expand=True)\n    log=tk.Text(log_area,height=19,wrap=\'word\',font=(\'Consolas\',9),state=\'normal\')\n    log_scroll=ttk.Scrollbar(log_area,orient=\'vertical\',command=log.yview)\n    log.configure(yscrollcommand=log_scroll.set)\n    log_scroll.pack(side=\'right\',fill=\'y\');log.pack(side=\'left\',fill=\'both\',expand=True)\n    def mount_sidebar():\n        side_tabs.add(activity_frame,text=\'Actividad\')\n        side_tabs.add(detail_frame,text=\'Detalle\')\n        side_tabs.add(options,text=\'Capas\')\n        side_tabs.pack(fill=\'both\',expand=True,pady=(2,0))\n        side_tabs.select(activity_frame)\n    ax.text(.5,.5,\'Ingresa el ID BDIT y elige dibujar LDE o comparar con BDATx.\',ha=\'center\',va=\'center\',transform=ax.transAxes,fontsize=11,color=\'#475569\')\n    canvas.draw_idle()\n    state={\'pts\':[],\'paths\':[],\'segments\':[],\'bd_paths\':[],\'bd_points\':[],\'bd_segments\':[],\'document_points\':[]}\n    def say(msg):\n        from datetime import datetime\n        message=f\'[{datetime.now():%H:%M:%S}] {msg}\\n\'\n        def add():\n            log.insert(\'end\',message);log.see(\'end\')\n        root.after(0,add)\n    mode=tk.StringVar(value=\'Ambos\')\n    def redraw(preserve=False):\n        old_limits=(ax.get_xlim(),ax.get_ylim()) if preserve and (state[\'pts\'] or state[\'paths\'] or state[\'bd_points\']) else None\n        try:\n            draw_map(ax,state[\'pts\'],state[\'paths\'],state[\'segments\'],show_labels.get(),\n                     show_towers.get(),show_vanos.get(),show_sections.get(),show_chile.get(),\n                     state[\'bd_paths\'],state[\'bd_points\'],mode.get())\n            if not (state[\'pts\'] or state[\'paths\'] or state[\'bd_points\'] or state[\'bd_paths\'] or state[\'document_points\']):\n                ax.clear()\n                ax.set_facecolor(\'#F7FAFC\')\n                ax.text(.5,.52,\'Ingresa una línea y pulsa «Ejecutar análisis»\',\n                        ha=\'center\',va=\'center\',transform=ax.transAxes,\n                        fontsize=12,color=\'#64748B\')\n                ax.set_axis_off()\n            else:\n                ax.set_axis_on()\n            if state.get(\'document_points\') and show_towers.get() and mode.get() in (\'LDE\',\'Ambos\'):\n                pp=state[\'document_points\']\n                ax.scatter([p[\'lon\'] for p in pp],[p[\'lat\'] for p in pp],s=35,c=\'#16a34a\',zorder=9,label=\'Estructuras documentales\')\n                ax.set_xlim(min(p[\'lon\'] for p in pp)-0.008,max(p[\'lon\'] for p in pp)+0.008)\n                ax.set_ylim(min(p[\'lat\'] for p in pp)-0.008,max(p[\'lat\'] for p in pp)+0.008)\n                ax.set_title(\'Coordenadas de documentos BDIT · sin contraste BDATx\')\n            if old_limits:\n                ax.set_xlim(*old_limits[0]);ax.set_ylim(*old_limits[1])\n            canvas.draw_idle()\n            if esri_widget[0] is not None:\n                try:\n                    refresh_esri(reset_view=not preserve)\n                except Exception as esri_exc:\n                    import traceback\n                    say(\'AVISO Esri: error independiente del mapa de análisis: \'+str(esri_exc))\n                    say(traceback.format_exc())\n        except Exception as exc:\n            say(\'ERROR AL DIBUJAR: \'+str(exc))\n            messagebox.showerror(\'Error del visor integrado\',str(exc))\n    def load_view():\n        p=line_folder(lid.get())/\'.cache\'/f\'Analisis_LT{lid.get()}.json\'\n        if not p.exists():return\n        d=json.loads(p.read_text(encoding=\'utf-8\'))\n        state.update(pts=d.get(\'results\') or [],paths=d.get(\'paths\') or [],segments=d.get(\'segments\') or [],bd_paths=d.get(\'bd_paths\') or [],bd_points=d.get(\'bd_points\') or [],bd_segments=d.get(\'bd_segments\') or [],document_points=d.get(\'document_points\') or []);redraw()\n    def worker():\n        try:\n            if not lid.get().strip():raise ValueError(\'Ingresa el ID de la línea BDIT.\')\n            line_id=int(lid.get())\n            try:\n                generate(line_id,logger=say)\n                crear_mapa_interactivo(line_id,logger=say,abrir=False)\n                root.after(0,lambda:(load_view(),say(\'Listo: Excel, GeoJSON y mapa HTML actualizados.\')))\n            except Exception as api_exc:\n                import traceback\n                trace=traceback.format_exc()\n                logpath=line_folder(line_id)/\'ERROR_CONTRASTE_BDATX.log\'\n                logpath.parent.mkdir(parents=True,exist_ok=True)\n                logpath.write_text(trace,encoding=\'utf-8\')\n                say(\'No se completó el contraste BDATx: \'+str(api_exc)+\' | Detalle: \'+str(logpath))\n                # Nunca sobrescribir cache ni GeoJSON LDE válido por un error BDATx.\n                cached=line_folder(line_id)/\'.cache\'/f\'Analisis_LT{line_id}.json\'\n                if cached.exists():\n                    say(\'Se mantiene el trazado LDE previamente dibujado; no se reemplaza por un GeoJSON vacío.\')\n                    root.after(0,load_view)\n                else:\n                    say(\'No hay trazado almacenado. Utiliza «Dibujar LDE» antes de comparar.\')\n                root.after(0,lambda msg=str(api_exc):messagebox.showwarning(\'LDE conservado · BDATx pendiente\',\n                    \'No se completó el contraste BDATx. El trazado LDE anterior se conserva.\\n\\n\'+msg))\n        except Exception as e:\n            error_text=str(e)\n            root.after(0,lambda msg=error_text:messagebox.showerror(\'Error de análisis\',msg))\n\n    def solo_lde():\n        try:\n            line_id=int(lid.get().strip())\n            cached=line_folder(line_id)/\'.cache\'/f\'Analisis_LT{line_id}.json\'\n            if cached.is_file() and (json.loads(cached.read_text(encoding=\'utf-8\')).get(\'results\') or []):\n                load_view()\n                say(\'Trazado LDE previamente procesado; no se reemplaza con una lectura vacía.\')\n            else:\n                path=vista_desde_geojson(line_id,logger=say)\n                load_view()\n                say(\'Mapa LDE actualizado. Archivo: \'+str(path))\n        except Exception as exc:\n            messagebox.showerror(\'No se pudo abrir el trazado LDE\',str(exc))\n    def abrir_resultados():\n        try:\n            carpeta=line_folder(lid.get().strip())\n            if not carpeta.is_dir():\n                messagebox.showinfo(\'Sin resultados\',f\'No existe la carpeta de resultados:\\n{carpeta}\\n\\nPrimero ejecuta el análisis.\')\n                return\n            import os,subprocess,sys\n            if sys.platform==\'win32\':os.startfile(str(carpeta))\n            elif sys.platform==\'darwin\':subprocess.Popen([\'open\',str(carpeta)])\n            else:subprocess.Popen([\'xdg-open\',str(carpeta)])\n        except Exception as exc:messagebox.showerror(\'No se pudo abrir la carpeta\',str(exc))\n    action_menu_button=ttk.Menubutton(line_actions,text=\'⋯  Opciones\')\n    action_menu_button.pack(side=\'right\',padx=(8,0))\n    action_menu=tk.Menu(action_menu_button,tearoff=0)\n    action_menu.add_command(label=\'Ajustar mapa\',command=lambda:redraw(False))\n    action_menu.add_command(label=\'Ver mapa satelital Esri\',command=lambda:map_tabs.select(esri_frame))\n    action_menu.add_command(label=\'Abrir carpeta de resultados\',command=abrir_resultados)\n    action_menu_button[\'menu\']=action_menu\n    execute_button=ttk.Button(line_actions,text=\'6 · Comparar torres BDATx\',style=\'Primary.TButton\')\n    execute_button.pack(side=\'right\')\n    def run_selected():\n        if not lid.get().strip().isdigit():\n            messagebox.showwarning(\'ID requerido\',\'Selecciona una línea BDIT en «Documentos» o introduce su ID.\',parent=root);return\n        execute_button.configure(state=\'disabled\')\n        say(\'BDATx | Validando línea homóloga por inf_id=\'+lid.get().strip()+\'. Consultando solo torres por linea_id, sin tramos ni vanos.\')\n        def job():\n            try:worker()\n            finally:root.after(0,lambda:execute_button.configure(state=\'normal\') if execute_button.winfo_exists() else None)\n        threading.Thread(target=job,daemon=True).start()\n    execute_button.configure(command=run_selected)\n    draw_button=ttk.Button(line_actions,text=\'Dibujar LDE\',command=solo_lde)\n    draw_button.pack(side=\'right\',padx=(0,8))\n    def show_loaded():\n        if lid.get().strip() and (line_folder(lid.get())/\'.cache\'/f\'Analisis_LT{lid.get()}.json\').exists():\n            load_view()\n            say(\'Mostrando trazado LDE de la línea \'+lid.get()+\'. La comparación BDATx es opcional.\')\n        else:\n            solo_lde()\n    def set_line_id(line_id):\n        lid.set(str(line_id))\n    root.set_line_id=set_line_id\n    root.show_loaded=show_loaded\n    root.compare_line=run_selected\n    ttk.Label(options,text=\'Fuente\').pack(anchor=\'w\',pady=(0,2))\n    source_combo=ttk.Combobox(options,textvariable=mode,values=[\'Ambos\',\'LDE\',\'BDATx\'],state=\'readonly\',width=20)\n    source_combo.pack(fill=\'x\',pady=(0,4))\n    mode.trace_add(\'write\',lambda *_:redraw(True))\n    layer_options=[(\'Secciones LDE\',show_sections),(\'Vanos LDE\',show_vanos),\n                   (\'Torres / estructuras\',show_towers),(\'Chile de referencia\',show_chile),\n                   (\'Mostrar etiquetas\',show_labels)]\n    layer_grid=ttk.Frame(options);layer_grid.pack(fill=\'x\',pady=(4,2))\n    for idx,(label,var) in enumerate(layer_options):\n        ttk.Checkbutton(layer_grid,text=label,variable=var,command=lambda:redraw(True)).grid(\n            row=idx//2,column=idx%2,sticky=\'w\',padx=(1,9),pady=2)\n    layer_grid.columnconfigure(0,weight=1);layer_grid.columnconfigure(1,weight=1)\n    ttk.Label(options,text=\'Azul: LDE · Naranja: BDATx · Rojo: alertas\',style=\'Subtitle.TLabel\',wraplength=270).pack(fill=\'x\',pady=(10,3))\n    mount_sidebar()\n    # La selección utiliza distancia en píxeles, no grados: funciona a cualquier zoom.\n    # Se inspeccionan AMBAS fuentes para que también respondan las torres aisladas BDATx.\n    def valid_points():\n        candidates=[]\n        if mode.get() in (\'LDE\',\'Ambos\') and show_towers.get():\n            candidates.extend((\'LDE\',p) for p in state[\'pts\'] if p.get(\'lon\') is not None and p.get(\'lat\') is not None)\n        if mode.get() in (\'BDATx\',\'Ambos\') and show_towers.get():\n            candidates.extend((\'BDATx\',p) for p in state[\'bd_points\'] if p.get(\'lon\') is not None and p.get(\'lat\') is not None)\n        if state.get(\'document_points\') and show_towers.get():\n            candidates.extend((\'DOCUMENTO\',p) for p in (state.get(\'document_points\') or []) if isinstance(p,dict))\n        return candidates\n    def describe(source,p):\n        if source==\'DOCUMENTO\':\n            return (f\'FUENTE: DOCUMENTO BDIT (sin contraste BDATx)\\nST BDIT: {p.get("id_seccion","-")}\\n\'\n                    f\'Estructura: {p.get("name","-")}\\nLat/Lon: {p["lat"]:.7f} / {p["lon"]:.7f}\\n\'\n                    f\'Archivo: {p.get("archivo","-")}\')\n        if source==\'BDATx\':\n            return (\'FUENTE: BDATx\\n\'\n                f\'ID torre BDATx: {p.get("id", "-")}\\n\'\n                f\'Nombre: {p.get("nombre", "-")}\\n\'\n                f\'Propietario BDATx: {p.get("propietario_bdatx","No informado")}\\n\'\n                f\'Secciones BDIT asociadas: {p.get("st", "-")}\\n\'\n                f\'Estado: {p.get("estado", "-")}\\n\'\n                f\'Este/Norte BDATx: {p.get("este", "-")} / {p.get("norte", "-")}\\n\'\n                f\'Lat/Lon BDATx: {p.get("lat", 0):.7f} / {p.get("lon", 0):.7f}\\n\')\n        return (\'FUENTE: LDE\\n\'\n            f\'ST BDIT: {p.get("st", "-")}\\n\'\n            f\'Estructura: {p.get("nombre", "-")}\\n\'\n            f\'Propietario BDIT de ST: {p.get("propietario_bdit","No informado")}\\n\'\n            f\'Propietario torre BDATx: {p.get("propietario_bdatx","Sin asociación")}\\n\'\n            f\'Estado: {p.get("estado", "-")}\\n\'\n            f\'Torre BDATx asociada: {p.get("id_torre", "-")}\\n\'\n            f\'Este/Norte LDE: {p.get("este", "-")} / {p.get("norte", "-")}\\n\'\n            f\'Lat/Lon LDE: {p.get("lat", 0):.7f} / {p.get("lon", 0):.7f}\\n\'\n            f\'Distancia BDATx: {p.get("distancia_m", "-")} m\\n\'\n            f\'Observación: {p.get("alerta", "-")}\\n\')\n    def show_esri_detail(source,p):\n        details.delete(\'1.0\',\'end\')\n        details.insert(\'1.0\',describe(source,p))\n\n    def segment_candidates():\n        items=[]\n        if mode.get() in (\'LDE\',\'Ambos\') and show_vanos.get():\n            for path in state[\'paths\']:\n                coords=path.get(\'coords\',[])\n                names=path.get(\'nombres\',[])\n                for i,(a,b) in enumerate(zip(coords,coords[1:])):\n                    info={\'st\':path.get(\'st\'),\'origen\':names[i] if i<len(names) else \'-\',\n                          \'destino\':names[i+1] if i+1<len(names) else \'-\',\n                          \'coords\':[a,b]}\n                    items.append((\'VANO LDE\',info))\n        if mode.get() in (\'BDATx\',\'Ambos\'):\n            for seg in state.get(\'bd_segments\',[]):\n                if seg.get(\'coords\'):items.append((\'VANO BDATx\',seg))\n        return items\n    def describe_segment(source,p):\n        if source==\'VANO LDE\':\n            a,b=p[\'coords\']\n            from math import radians,sin,cos,atan2,sqrt\n            dlat=radians(b[1]-a[1]);dlon=radians(b[0]-a[0]);lat1=radians(a[1]);lat2=radians(b[1])\n            h=sin(dlat/2)**2+cos(lat1)*cos(lat2)*sin(dlon/2)**2\n            distance=6371000*2*atan2(sqrt(h),sqrt(max(0,1-h)))\n            return (f\'FUENTE: LDE\\nTIPO: Vano reconstruido desde LDE\\nST BDIT: {p.get("st")}\\n\'\n                    f\'Estructura origen: {p.get("origen")}\\nEstructura destino: {p.get("destino")}\\n\'\n                    f\'Longitud aproximada: {distance:.2f} m\\n\'\n                    f\'Origen (lon, lat): {a[0]:.7f}, {a[1]:.7f}\\n\'\n                    f\'Destino (lon, lat): {b[0]:.7f}, {b[1]:.7f}\\n\'\n                    \'Este vano es geométrico, no un registro oficial BDATx.\')\n        return (f\'FUENTE: BDATx\\nTIPO: Vano registrado\\nID vano BDATx: {p.get("id_vano", "-")}\\n\'\n                f\'Nombre: {p.get("nombre", "-")}\\nTramo BDATx: {p.get("tramo_id", "-")}\\n\'\n                f\'ST BDIT: {p.get("st", "-")}\\nNodo 1 ID: {p.get("nodo1", "-")}\\n\'\n                f\'Nombre nodo 1: {p.get("nodo1_nombre", "-")}\\n\'\n                f\'Nodo 2 ID: {p.get("nodo2", "-")}\\nNombre nodo 2: {p.get("nodo2_nombre", "-")}\\n\'\n                f\'Estado: {p.get("estado", "-")}\\n\'\n                f\'Extremos WGS84: {p.get("coords", "-")}\')\n    drag={\'start\':None,\'limits\':None,\'moved\':False}\n    def mouse_down(event):\n        if event.inaxes is not ax or event.button!=1:return\n        drag[\'start\']=(event.x,event.y)\n        drag[\'limits\']=(ax.get_xlim(),ax.get_ylim())\n        drag[\'moved\']=False\n    def mouse_move(event):\n        if drag[\'start\'] is None or event.x is None or event.y is None:return\n        sx,sy=drag[\'start\'];dx=event.x-sx;dy=event.y-sy\n        if abs(dx)+abs(dy)<5 and not drag[\'moved\']:return\n        drag[\'moved\']=True\n        (x0,x1),(y0,y1)=drag[\'limits\']\n        bbox=ax.bbox\n        scale_x=(x1-x0)/max(1,bbox.width)\n        scale_y=(y1-y0)/max(1,bbox.height)\n        ax.set_xlim(x0-dx*scale_x,x1-dx*scale_x)\n        ax.set_ylim(y0-dy*scale_y,y1-dy*scale_y)\n        canvas.draw_idle()\n    def mouse_up(event):\n        if drag[\'start\'] is None:return\n        moved=drag[\'moved\'];drag[\'start\']=None;drag[\'limits\']=None;drag[\'moved\']=False\n        if not moved:select_at(event)\n    def select_at(event):\n        if event.inaxes is not ax or event.x is None or event.y is None:return\n        best=None\n        for source,p in valid_points():\n            x,y=ax.transData.transform((p[\'lon\'],p[\'lat\']))\n            distance=((x-event.x)**2+(y-event.y)**2)**.5\n            if best is None or distance<best[0]:best=(distance,\'punto\',source,p)\n        nearest_point=best\n        for source,p in segment_candidates():\n            a,b=p[\'coords\']\n            x1,y1=ax.transData.transform(a);x2,y2=ax.transData.transform(b)\n            dx=x2-x1;dy=y2-y1\n            t=max(0,min(1,((event.x-x1)*dx+(event.y-y1)*dy)/(dx*dx+dy*dy))) if dx*dx+dy*dy>0 else 0\n            distance=((event.x-x1-t*dx)**2+(event.y-y1-t*dy)**2)**.5\n            # Si el clic cae cerca de una torre, dar preferencia al punto.\n            if best is None or distance<best[0]:best=(distance,\'vano\',source,p)\n        details.delete(\'1.0\',\'end\')\n        if best is None or best[0]>14:\n            details.insert(\'end\',\'Haz clic sobre una torre o sobre el segmento de un vano LDE/BDATx. Acércate con la rueda para seleccionar elementos superpuestos.\')\n            return\n        if nearest_point is not None and nearest_point[0]<=9:\n            best=nearest_point\n        _,kind,source,p=best\n        details.insert(\'end\',describe(source,p) if kind==\'punto\' else describe_segment(source,p))\n        details.see(\'1.0\')\n    def on_scroll(event):\n        if event.inaxes is not ax or event.xdata is None or event.ydata is None:return\n        direction=getattr(event,\'step\',0)\n        if not direction:direction=1 if event.button==\'up\' else -1\n        factor=1/1.35 if direction>0 else 1.35\n        x0,x1=ax.get_xlim();y0,y1=ax.get_ylim()\n        x,y=event.xdata,event.ydata\n        ax.set_xlim(x+(x0-x)*factor,x+(x1-x)*factor)\n        ax.set_ylim(y+(y0-y)*factor,y+(y1-y)*factor)\n        canvas.draw_idle()\n    canvas.mpl_connect(\'button_press_event\',mouse_down)\n    canvas.mpl_connect(\'motion_notify_event\',mouse_move)\n    canvas.mpl_connect(\'button_release_event\',mouse_up)\n    canvas.mpl_connect(\'scroll_event\',on_scroll)\n    \n    redraw()\n    if args.linea is not None and (line_folder(args.linea)/\'.cache\'/f\'Analisis_LT{args.linea}.json\').exists():\n        try:\n            load_view()\n            say(\'Trazado de la línea \'+str(args.linea)+\' cargado automáticamente en el panel central.\')\n        except Exception as exc:\n            say(\'No se pudo cargar el trazado guardado: \'+str(exc))\n            root.after(200,lambda:threading.Thread(target=worker,daemon=True).start())\n    if not embedded:root.mainloop()\n    return root\n\n\n# Canonical motor and passive report are registered before any UI callback.\n'), ('visor_lde_archivos', '"""Construir y visualizar trazados LDE desde archivos locales, sin cuentas ni API.\n\nNunca une extremos de archivos por numeración supuesto ni inventa husos UTM.\nLos GeoJSON mantienen las partes georreferenciadas por documento y los vanos\nreferenciales; los segmentos interrumpidos por filas sin coordenadas se separan.\n"""\nfrom __future__ import annotations\nimport csv\nimport hashlib\nimport json\nimport math\nimport os\nimport queue\nimport re\nimport threading\nimport tkinter as tk\nfrom collections import Counter\nfrom datetime import datetime\nfrom pathlib import Path\nimport tempfile\nfrom archivo_zip import choose_archive_members, extract_archive_selected, new_extraction_destination, LDE_FORMATS\nfrom tkinter import ttk, filedialog, messagebox\n\nfrom extractor_estructuras import tables, parse_table, resolver_huso_lde\nfrom piloto_trazado import read_lde\n\nEXTENSIONS={\'.xlsx\',\'.xlsm\',\'.csv\',\'.txt\',\'.docx\',\'.pdf\'}\n\ndef document_section(path):\n    """Source ST only if named explicitly; otherwise use the file identity, never a fake ST."""\n    path=Path(path)\n    # Incluye carpetas de ZIP descargado en ST_<ID> sin atribuir un ST inventado.\n    for text in (path.stem, *(parent.name for parent in list(path.parents)[:5])):\n        hit=re.search(r\'(?:^|[\\s_\\-])ST[\\s_\\-]?(\\d+)(?=$|[\\s_\\-])\',text,re.I)\n        if hit:return str(int(hit.group(1)))\n    return \'\'\n\ndef _num(x):\n    try:\n        if x in (\'\',None):return None\n        return float(str(x).replace(\',\',\'.\'))\n    except (ValueError,TypeError,OverflowError):return None\n\ndef _document_records(path,manual_zone=\'auto\'):\n    """Reuse canonical LDE parser; support labeled tabular documents conservatively."""\n    path=Path(path)\n    section=document_section(path)\n    tag=section or path.stem\n    rows=[];kind=\'\'\n    if path.suffix.lower() in (\'.xlsx\',\'.xlsm\'):\n        try:\n            rows=read_lde(path,tag)\n            if rows:kind=\'LDE estructurado\'\n        except (OSError,ValueError,KeyError,IndexError,TypeError,RuntimeError) as exc:\n            if \'No se identificaron encabezados\' not in str(exc):\n                raise\n    if not rows:\n        kind=\'Tabla genérica\'\n        for origin, data in tables(path):\n            found=parse_table(data,path,origin,section,\'LDE cargado manualmente\')\n            for r in found:\n                lat=_num(r.get(\'latitud\'));lon=_num(r.get(\'longitud\'))\n                rows.append({\'st\':tag,\'nombre\':str(r.get(\'estructura\') or f\'Fila {r.get("fila", "")}\'),\n                             \'fila\':r.get(\'fila\'),\'este\':_num(r.get(\'este\')),\n                             \'norte\':_num(r.get(\'norte\')),\'huso\':r.get(\'huso\') or \'\',\n                             \'lat\':lat,\'lon\':lon,\'datum\':\'No especificado\',\n                             \'tipo\':\'\',\'codigo\':\'\',\'funcion\':\'\',\'marco\':False,\n                             \'alerta\':r.get(\'observacion\') or \'\'})\n    result=[]\n    for r in rows:\n        r=dict(r)\n        r[\'st\']=tag\n        r[\'archivo\']=path.name\n        lon=_num(r.get(\'lon\'));lat=_num(r.get(\'lat\'))\n        e=_num(r.get(\'este\'));n=_num(r.get(\'norte\'))\n        zone=str(r.get(\'huso\') or \'\').strip()\n        alert=str(r.get(\'alerta\') or \'\').strip()\n        r[\'huso_original\']=zone\n        # Only override a *missing/ambiguous* zone at the explicit user\'s request;\n        # never silently supersede a recorded 18/19 zone or other declared CRS.\n        if (lon is None or lat is None) and manual_zone in (\'18\',\'19\') and e is not None and n is not None and not re.match(r\'^\\s*(18|19)\\s*[C-X]?\\s*$\',zone,re.I):\n            lo,la,z,status,obs=resolver_huso_lde(e,n,manual_zone)\n            if lo is not None and la is not None:\n                lon,lat=lo,la;r[\'huso\']=z\n                alert=(\'; \'.join(x for x in (alert,f\'Huso {manual_zone} aplicado manualmente: REVISAR\') if x))\n            else:alert=(\'; \'.join(x for x in (alert,obs) if x))\n        if lon is not None and lat is not None and not (-56<=lat<=-17 and -76<=lon<=-66):\n            alert=(\'; \'.join(x for x in (alert,\'Ubicación fuera de rango continental de Chile\') if x))\n            lon=lat=None\n        r[\'lat\']=lat;r[\'lon\']=lon;r[\'alerta\']=alert\n        r[\'valido\']=lon is not None and lat is not None\n        result.append(r)\n    if not result:raise ValueError(\'No se identificaron filas de estructuras con coordenadas; revisar encabezados o formato.\')\n    return result,kind\n\ndef _distance_m(a,b):\n    """Haversine distance, suitable for alerts rather than cadastral surveying."""\n    radius=6371008.8\n    p1=math.radians(a[\'lat\']);p2=math.radians(b[\'lat\'])\n    dphi=p2-p1;dlambda=math.radians(b[\'lon\']-a[\'lon\'])\n    h=math.sin(dphi/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dlambda/2)**2\n    return 2*radius*math.asin(min(1,math.sqrt(h)))\n\ndef build_trace(paths,zone=\'auto\',progress=None,source_map=None):\n    """Pure result, independent of GUI and external BDIT/BDATx APIs."""\n    source_map=source_map or {}\n    unique=[];seen=set()\n    for p in paths:\n        x=Path(p).expanduser().resolve()\n        if x in seen:continue\n        seen.add(x)\n        if not x.is_file():raise FileNotFoundError(str(x))\n        if x.suffix.lower() not in EXTENSIONS:raise ValueError(\'Formato no admitido: \'+x.name)\n        unique.append(x)\n    if not unique:raise ValueError(\'Selecciona al menos un LDE.\')\n    features=[];paths_data=[];points=[];spans=[];alerts=[];per_file=[]\n    valid_unique={};order=0;seen_contents={}\n    for idx,path in enumerate(unique,1):\n        visible_name=source_map.get(str(path),path.name)\n        if progress:progress(idx,len(unique),\'Leyendo \'+visible_name)\n        try:\n            if path.stat().st_size>35*1024*1024:\n                raise ValueError(\'Archivo supera el límite de lectura de 35 MB\')\n            digest=hashlib.sha256(path.read_bytes()).hexdigest()\n            if digest in seen_contents:\n                prev=seen_contents[digest]\n                per_file.append({\'archivo\':visible_name,\'ruta\':str(path),\'st\':document_section(path) or \'No indicada\',\n                    \'filas\':0,\'vertices\':0,\'vanos\':0,\'alertas\':0,\'tipo\':\'Duplicado de \'+prev,\n                    \'estado\':\'DUPLICADO\',\'detalle\':\'Contenido idéntico al archivo \'+prev})\n                if progress:progress(idx,len(unique),f\'{path.name}: duplicado de {prev}, omitido\')\n                continue\n            seen_contents[digest]=visible_name\n            rows,kind=_document_records(path,zone)\n        except Exception as exc:\n            per_file.append({\'archivo\':visible_name,\'ruta\':str(path),\'st\':document_section(path) or \'No indicada\',\'filas\':0,\'vertices\':0,\'vanos\':0,\'alertas\':1,\'tipo\':\'No reconocido\',\'estado\':\'ERROR\', \'detalle\':str(exc)})\n            alerts.append({\'archivo\':visible_name,\'fila\':\'\',\'tipo\':\'ERROR_LECTURA\',\'detalle\':str(exc)})\n            continue\n        doc_id=f\'DOC_{idx:03d}\';section=document_section(path)\n        for r in rows:r[\'archivo\']=visible_name\n        valid=0;span_num=0;warn=0;runs=[];run=[]\n        for r in rows:\n            order+=1\n            p=dict(r);p[\'documento_id\']=doc_id;p[\'seccion_bdit\']=section or None;p[\'orden_global\']=order\n            if not p[\'valido\']:\n                warn+=1\n                alerts.append({\'archivo\':visible_name,\'fila\':p.get(\'fila\'),\'tipo\':\'SIN_COORDENADAS\',\'detalle\':p.get(\'alerta\') or p.get(\'nombre\')})\n                if run:runs.append(run);run=[]\n                continue\n            valid+=1\n            points.append(p)\n            key=(round(p[\'lat\'],6),round(p[\'lon\'],6))\n            valid_unique.setdefault(key,[]).append({\'archivo\':visible_name,\'estructura\':p[\'nombre\']})\n            if p.get(\'alerta\'):\n                warn+=1\n                alerts.append({\'archivo\':visible_name,\'fila\':p.get(\'fila\'),\'tipo\':\'REVISAR_DATO\',\'detalle\':p[\'alerta\']})\n            coord=[p[\'lon\'],p[\'lat\']]\n            props={\'fuente\':\'LDE_LOCAL\',\'tipo\':\'estructura_LDE\',\'documento_id\':doc_id,\n                   \'archivo\':visible_name,\'seccion_bdit\':section or None,\n                   \'estructura\':p[\'nombre\'],\'orden\':len(points),\'fila\':p.get(\'fila\'),\n                   \'este\':p.get(\'este\'),\'norte\':p.get(\'norte\'),\n                   \'huso\':p.get(\'huso\'),\'huso_original\':p.get(\'huso_original\'),\n                   \'datum\':p.get(\'datum\'),\'marco\':p.get(\'marco\',False),\n                   \'tipo_estructura\':p.get(\'tipo\'),\'funcion\':p.get(\'funcion\'),\n                   \'codigo\':p.get(\'codigo\'),\'observacion\':p.get(\'alerta\') or \'\'}\n            features.append({\'type\':\'Feature\',\'properties\':props,\'geometry\':{\'type\':\'Point\',\'coordinates\':coord}})\n            run.append(p)\n        if run:runs.append(run)\n        for j,segment in enumerate(runs,1):\n            if len(segment)<2:continue\n            coords=[[p[\'lon\'],p[\'lat\']] for p in segment]\n            paths_data.append({\'documento_id\':doc_id,\'archivo\':visible_name,\'seccion\':section,\n                               \'puntos\':segment,\'coords\':coords})\n            features.append({\'type\':\'Feature\',\'properties\':{\'fuente\':\'LDE_LOCAL\',\'tipo\':\'seccion_tramo\',\n                      \'documento_id\':doc_id,\'archivo\':visible_name,\'seccion_bdit\':section or None,\'parte\':j},\n                      \'geometry\':{\'type\':\'LineString\',\'coordinates\':coords}})\n            for a,b in zip(segment,segment[1:]):\n                span_num+=1;distance=_distance_m(a,b)\n                caution=distance>1000\n                if caution:\n                    warn+=1\n                    alerts.append({\'archivo\':visible_name,\'fila\':a.get(\'fila\'), \'tipo\':\'SALTO_MAYOR_1000M\',\n                                   \'detalle\':f\'{a["nombre"]} → {b["nombre"]}: {distance:.1f} m (revisar)\'})\n                info={\'documento_id\':doc_id,\'archivo\':visible_name,\'seccion\':section,\'desde\':a[\'nombre\'],\n                      \'hasta\':b[\'nombre\'],\'a\':[a[\'lon\'],a[\'lat\']],\'b\':[b[\'lon\'],b[\'lat\']],\n                      \'longitud_m\':round(distance,2),\'estado\':\'REVISAR_SALTO\' if caution else \'REFERENCIAL\'}\n                spans.append(info)\n                features.append({\'type\':\'Feature\',\'properties\':{\'fuente\':\'LDE_LOCAL\',\'tipo\':\'vano_LDE\',\n                    \'documento_id\':doc_id,\'archivo\':visible_name,\'seccion_bdit\':section or None,\n                    \'nodo1\':a[\'nombre\'],\'nodo2\':b[\'nombre\'],\'longitud_m\':round(distance,2),\n                    \'estado\':info[\'estado\']},\'geometry\':{\'type\':\'LineString\',\'coordinates\':[info[\'a\'],info[\'b\']]}})\n        per_file.append({\'archivo\':visible_name,\'ruta\':str(path),\'st\':section or \'No indicada\',\n                         \'filas\':len(rows),\'vertices\':valid,\'vanos\':span_num,\'alertas\':warn,\n                         \'tipo\':kind,\'estado\':\'OK\' if valid>=2 and not warn else (\'REVISAR\' if valid else \'SIN_TRAZADO\'),\n                         \'detalle\':f\'{len(rows)} estructuras detectadas; {len(runs)} tramos continuos con coordenadas\'})\n        if progress:progress(idx,len(unique),f\'{path.name}: {valid} vértices, {span_num} vanos, {warn} alertas\')\n    if paths_data:\n        features.insert(0,{\'type\':\'Feature\',\'properties\':{\'fuente\':\'LDE_LOCAL\',\'tipo\':\'linea\',\n            \'nota\':\'MultiLineString documental, conserva trazados por archivo. No une extremos sin evidencia\',\n            \'documentos\':len(unique)},\n            \'geometry\':{\'type\':\'MultiLineString\',\'coordinates\':[p[\'coords\'] for p in paths_data]}})\n    result={\'type\':\'FeatureCollection\',\'features\':features}\n    totals={\'archivos\':len(unique),\'archivos_con_trazado\':sum(f[\'vanos\']>0 for f in per_file),\n            \'vertices\':len(points),\'vertices_unicos_aprox\':len(valid_unique),\n            \'tramos_continuos\':len(paths_data),\'vanos_reconstruidos\':len(spans),\n            \'alertas\':len(alerts),\'errores_archivos\':sum(f[\'estado\']==\'ERROR\' for f in per_file)}\n    return {\'geojson\':result,\'paths\':paths_data,\'points\':points,\'spans\':spans,\n            \'files\':per_file,\'alerts\':alerts,\'totals\':totals}\n\ndef save_trace(result,filename):\n    filename=Path(filename)\n    if filename.suffix.lower() not in (\'.geojson\',\'.json\'):filename=filename.with_suffix(\'.geojson\')\n    filename.write_text(json.dumps(result[\'geojson\'],ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    csvpath=filename.with_name(filename.stem+\'_CONTROL.csv\')\n    with csvpath.open(\'w\',newline=\'\',encoding=\'utf-8-sig\') as f:\n        cols=[\'archivo\',\'seccion\',\'fila\',\'estructura\',\'este\',\'norte\',\'huso\',\'latitud\',\'longitud\',\'observacion\']\n        w=csv.DictWriter(f,fieldnames=cols,delimiter=\';\');w.writeheader()\n        for p in result[\'points\']:\n            w.writerow({\'archivo\':p.get(\'archivo\'),\'seccion\':p.get(\'seccion_bdit\') or \'\',\n                \'fila\':p.get(\'fila\'),\'estructura\':p.get(\'nombre\'),\'este\':p.get(\'este\'),\n                \'norte\':p.get(\'norte\'),\'huso\':p.get(\'huso\'),\'latitud\':p.get(\'lat\'),\n                \'longitud\':p.get(\'lon\'),\'observacion\':p.get(\'alerta\',\'\')})\n    return filename,csvpath\n\nclass LDEFilesApp(ttk.Frame):\n    """Third module: choose multiple LDEs -> construct -> inspect -> export."""\n    def __init__(self,parent):\n        super().__init__(parent)\n        self.paths=[];self.data=None;self.current={};self.events=queue.Queue()\n        self.zip_temporary=tempfile.TemporaryDirectory(prefix=\'lineatx_lde_zip_\')\n        self.zip_sources={}  # extracted path -> ZIP / internal document\n        self.zip_loaded={}   # ZIP path -> selected extracted paths\n        self.busy=False;self.esri=None;self.esri_layers=[];self.last_view=None;self._esri_icon=None\n        self.show_points=tk.BooleanVar(value=True)\n        self.show_labels=tk.BooleanVar(value=False)\n        self.zone=tk.StringVar(value=\'Automático (del documento)\')\n        self.summary=tk.StringVar(value=\'Agrega uno o varios listados de distribución de estructuras.\')\n        self.detail=tk.StringVar(value=\'Haz clic sobre un vértice para consultar la estructura y sus coordenadas.\')\n        self._build_ui()\n        self.after(100,self._poll)\n\n    def _build_ui(self):\n        from matplotlib.figure import Figure\n        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg\n        header=ttk.Frame(self,padding=(18,11,18,6));header.pack(fill=\'x\')\n        ttk.Label(header,text=\'Dibujar desde LDE\',style=\'PageTitle.TLabel\').pack(anchor=\'w\')\n        ttk.Label(header,text=\'Selecciona varios listados de distribución de estructuras y construye el trazado sin usar API.\',style=\'Subtitle.TLabel\').pack(anchor=\'w\')\n        action=ttk.Frame(self,style=\'Card.TFrame\',padding=(13,11));action.pack(fill=\'x\',padx=13,pady=(4,7))\n        bar=ttk.Frame(action,style=\'Card.TFrame\');bar.pack(fill=\'x\')\n        ttk.Button(bar,text=\'＋  Agregar LDE / ZIP\',command=self.add_files).pack(side=\'left\',padx=(0,10))\n        self.files_toggle=ttk.Button(bar,text=\'Archivos  ▴\',command=self.toggle_files)\n        self.files_toggle.pack(side=\'left\',padx=(0,9))\n        advanced=ttk.Menubutton(bar,text=\'⋯  Opciones\')\n        advanced.pack(side=\'left\')\n        menu=tk.Menu(advanced,tearoff=0)\n        menu.add_command(label=\'Quitar archivos seleccionados\',command=self.remove_files)\n        menu.add_command(label=\'Limpiar lista de archivos\',command=self.clear_files)\n        menu.add_separator()\n        menu.add_command(label=\'Ajustar vista del mapa\',command=lambda:self._draw(False))\n        menu.add_command(label=\'Exportar GeoJSON y CSV\',command=self.export)\n        advanced[\'menu\']=menu\n        self.build_btn=ttk.Button(bar,text=\'Construir trazado\',style=\'Primary.TButton\',command=self.start_build)\n        self.build_btn.pack(side=\'right\')\n        self.files_container=ttk.Frame(action,style=\'Card.TFrame\')\n        self.files_container.pack(fill=\'x\',pady=(9,1))\n        tree_wrap=ttk.Frame(self.files_container,style=\'Card.TFrame\');tree_wrap.pack(fill=\'x\')\n        self.files_tree=ttk.Treeview(tree_wrap,columns=(\'file\',\'ext\',\'st\',\'points\',\'state\'),show=\'headings\',height=4,selectmode=\'extended\')\n        for key,title,width in [(\'file\',\'Documento LDE / contenido ZIP\',505),(\'ext\',\'Ext.\',80),(\'st\',\'ST identificada\',120),(\'points\',\'Vértices\',80),(\'state\',\'Lectura\',130)]:\n            self.files_tree.heading(key,text=title);self.files_tree.column(key,width=width,stretch=(key==\'file\'),anchor=\'w\')\n        sc=ttk.Scrollbar(tree_wrap,orient=\'vertical\',command=self.files_tree.yview)\n        self.files_tree.configure(yscrollcommand=sc.set)\n        sc.pack(side=\'right\',fill=\'y\');self.files_tree.pack(fill=\'x\',expand=True)\n        status=ttk.Frame(self,padding=(16,0,16,6));status.pack(fill=\'x\')\n        ttk.Label(status,textvariable=self.summary,style=\'Status.TLabel\').pack(side=\'left\',fill=\'x\',expand=True)\n        self.progress=ttk.Progressbar(status,mode=\'determinate\',maximum=100,length=140)\n        self.progress.pack(side=\'right\',padx=(10,0))\n\n        body=ttk.Panedwindow(self,orient=\'horizontal\');body.pack(fill=\'both\',expand=True,padx=12,pady=(0,10))\n        left=ttk.Frame(body);right=ttk.Frame(body,width=305)\n        body.add(left,weight=8);body.add(right,weight=2)\n        self._pane_ready=False\n        def _arrange_map(event=None):\n            if not self._pane_ready and body.winfo_width()>900:\n                self._pane_ready=True\n                body.after_idle(lambda:body.sashpos(0,int(body.winfo_width()*.76)))\n        body.bind(\'<Configure>\',_arrange_map,add=\'+\')\n        maps=ttk.Notebook(left);maps.pack(fill=\'both\',expand=True)\n        self.plot_frame=ttk.Frame(maps);self.esri_frame=ttk.Frame(maps)\n        maps.add(self.plot_frame,text=\'Mapa de trazado\');maps.add(self.esri_frame,text=\'Esri · satélite\')\n        self.map_tabs=maps\n        self.esri_msg=ttk.Label(self.esri_frame,text=\'Mapa satelital opcional Esri.\\nRequiere tkintermapview y acceso al servidor cartográfico.\',justify=\'center\',anchor=\'center\')\n        self.esri_msg.pack(fill=\'both\',expand=True,padx=20,pady=20)\n        fig=Figure(figsize=(9,6),dpi=100,facecolor=\'white\')\n        self.fig=fig;self.ax=fig.add_subplot(111)\n        self.canvas=FigureCanvasTkAgg(fig,master=self.plot_frame)\n        self.canvas.get_tk_widget().pack(fill=\'both\',expand=True)\n        self._draw()\n        self.canvas.mpl_connect(\'button_press_event\',self._pick)\n        self.canvas.mpl_connect(\'scroll_event\',self._wheel)\n        self.map_tabs.bind(\'<<NotebookTabChanged>>\',self._tab_changed)\n\n        results=ttk.Frame(right,padding=(8,3,5,5));results.pack(fill=\'x\')\n        self.metrics=ttk.Label(results,text=\'0 vértices  ·  0 vanos  ·  0 alertas\',style=\'Section.TLabel\',wraplength=270)\n        self.metrics.pack(anchor=\'w\',pady=(0,4))\n        self.save_btn=ttk.Button(results,text=\'Guardar trazado\',style=\'Primary.TButton\',command=self.export,state=\'disabled\')\n        # Solo se muestra cuando exista un trazado válido.\n        self.result_frame=results\n        tabs=ttk.Notebook(right)\n        tabs.pack(fill=\'both\',expand=True)\n        activity=ttk.Frame(tabs,padding=7)\n        inspector=ttk.Frame(tabs,padding=9)\n        layers=ttk.Frame(tabs,padding=10)\n        tabs.add(activity,text=\'Actividad\');tabs.add(inspector,text=\'Detalle\');tabs.add(layers,text=\'Opciones\')\n        tabs.select(activity)\n        logcontainer=ttk.Frame(activity);logcontainer.pack(fill=\'both\',expand=True)\n        self.log=tk.Text(logcontainer,wrap=\'word\',height=16,font=(\'Consolas\',9),borderwidth=0)\n        scrollbar=ttk.Scrollbar(logcontainer,command=self.log.yview)\n        self.log.configure(yscrollcommand=scrollbar.set)\n        scrollbar.pack(side=\'right\',fill=\'y\');self.log.pack(side=\'left\',fill=\'both\',expand=True)\n        ttk.Label(inspector,text=\'Selecciona una estructura sobre el mapa para ver sus coordenadas.\',style=\'Subtitle.TLabel\',wraplength=245).pack(anchor=\'w\',pady=(0,8))\n        self.inspector=tk.Text(inspector,height=7,wrap=\'word\',font=(\'Segoe UI\',10),borderwidth=0)\n        self.inspector.pack(fill=\'both\',expand=True)\n        self.inspector.insert(\'1.0\',\'Ninguna estructura seleccionada.\')\n        self.inspector.configure(state=\'disabled\')\n        ttk.Checkbutton(layers,text=\'Mostrar vértices\',variable=self.show_points,command=self._draw).pack(anchor=\'w\',pady=(0,8))\n        ttk.Checkbutton(layers,text=\'Mostrar etiquetas\',variable=self.show_labels,command=self._draw).pack(anchor=\'w\',pady=(0,14))\n        ttk.Label(layers,text=\'Huso UTM cuando no está declarado\',style=\'Subtitle.TLabel\',wraplength=260).pack(anchor=\'w\',pady=(0,6))\n        ttk.Combobox(layers,textvariable=self.zone,values=[\'Automático (del documento)\',\'18\',\'19\'],state=\'readonly\',width=27).pack(fill=\'x\')\n        ttk.Label(layers,text=\'Los LDE se mantienen como trazados documentales independientes.\',style=\'Subtitle.TLabel\',wraplength=260).pack(anchor=\'w\',pady=(14,0))\n\n    def toggle_files(self,visible=None):\n        show=not bool(self.files_container.winfo_manager()) if visible is None else bool(visible)\n        if show:\n            self.files_container.pack(fill=\'x\',pady=(9,1))\n            self.files_toggle.configure(text=\'Archivos  ▴\')\n        else:\n            self.files_container.pack_forget()\n            self.files_toggle.configure(text=f\'Archivos ({len(self.paths)})  ▾\')\n\n    def _log(self,msg):\n        self.log.insert(\'end\',f\'[{datetime.now():%H:%M:%S}] {msg}\\n\');self.log.see(\'end\')\n\n    def add_files(self):\n        paths=filedialog.askopenfilenames(parent=self,title=\'Seleccionar uno o varios documentos LDE\',\n            filetypes=[(\'LDE y archivos comprimidos\',\'*.xlsx *.xlsm *.csv *.txt *.docx *.pdf *.zip *.rar\'),(\'ZIP y RAR\',\'*.zip *.rar\'),(\'Excel\',\'*.xlsx *.xlsm\'),(\'Todos los archivos\',\'*.*\')])\n        if not paths:return\n        found={str(x.resolve()) for x in self.paths}\n        for p in paths:\n            path=Path(p).resolve()\n            if path.suffix.lower() in (\'.zip\',\'.rar\'):\n                try:\n                    selected=choose_archive_members(self,path)\n                    if selected is None:\n                        self._log(\'Archivo cancelado: \'+path.name);continue\n                    if not selected:\n                        self._log(\'Archivo sin documentos LDE seleccionados: \'+path.name);continue\n                    # Extraer primero a una carpeta exclusiva y después sustituir\n                    # la selección en la UI. Así se preservan los LDE previos si\n                    # una extracción falla y no es necesario borrar directorios.\n                    dest,aviso=new_extraction_destination(path,Path(self.zip_temporary.name))\n                    extracted=extract_archive_selected(path,selected,dest)\n                    previous=self.zip_loaded.get(str(path),set())\n                    for old in previous:\n                        self.paths=[p for p in self.paths if str(p)!=old]\n                        self.zip_sources.pop(old,None);found.discard(old)\n                    self.zip_loaded[str(path)]={str(p.resolve()) for p in extracted}\n                    if aviso:self._log(\'AVISO: \'+aviso)\n                    for file,member in zip(extracted,selected):\n                        self.zip_sources[str(file.resolve())]=f\'{path.name} → {member}\'\n                        if str(file.resolve()) not in found:\n                            self.paths.append(file.resolve());found.add(str(file.resolve()))\n                    self._log(f\'Archivo {path.name}: {len(extracted)} documento(s) seleccionado(s).\')\n                except Exception as exc:\n                    self._log(\'No se pudo abrir archivo comprimido \'+path.name+\': \'+str(exc))\n                    messagebox.showerror(\'Error al leer ZIP/RAR\',str(exc),parent=self)\n                continue\n            if path.suffix.lower() not in EXTENSIONS:\n                self._log(f\'Formato no admitido: {path.name}\');continue\n            if str(path) in found:continue\n            self.paths.append(path);found.add(str(path))\n        self._refresh_files()\n        self.files_toggle.configure(text=f\'Archivos ({len(self.paths)})  ▴\')\n        if not self.files_container.winfo_manager():self.toggle_files(True)\n        self.summary.set(f\'{len(self.paths)} documentos listos para analizar.\')\n\n    def _refresh_files(self):\n        self.files_tree.delete(*self.files_tree.get_children())\n        lookup={f[\'ruta\']:f for f in (self.data or {}).get(\'files\',[])}\n        for path in self.paths:\n            item=lookup.get(str(path),{})\n            self.files_tree.insert(\'\', \'end\',iid=str(path),values=(self.zip_sources.get(str(path),path.name),\n                path.suffix.lower(), document_section(path) or \'No indicada\',\n                item.get(\'vertices\',\'—\'),item.get(\'estado\',\'Pendiente\')))\n\n    def remove_files(self):\n        removed=set(self.files_tree.selection())\n        self.paths=[p for p in self.paths if str(p) not in removed]\n        for key in removed:self.zip_sources.pop(key,None)\n        for src,files in list(self.zip_loaded.items()):\n            self.zip_loaded[src]=files-removed\n        self._reset()\n\n    def clear_files(self):\n        self.paths.clear();self.zip_sources.clear();self.zip_loaded.clear();self._reset()\n\n    def _reset(self):\n        self.data=None;self.save_btn.configure(state=\'disabled\')\n        self._refresh_files();self._draw()\n        if self.save_btn.winfo_manager():self.save_btn.pack_forget()\n        self.metrics.configure(text=\'0 vértices    ·    0 vanos    ·    0 alertas\')\n        self.summary.set(f\'{len(self.paths)} archivos seleccionados. Construye el trazado para visualizar.\')\n\n    def start_build(self):\n        if self.busy:return\n        if not self.paths:\n            messagebox.showinfo(\'Cargar LDE\',\'Selecciona al menos un archivo mediante «Agregar LDE».\',parent=self);return\n        self.data=None;self.save_btn.configure(state=\'disabled\');self.build_btn.configure(state=\'disabled\')\n        self.busy=True;self.progress[\'value\']=0\n        paths=list(self.paths);zone=self.zone.get()\n        def runner():\n            try:\n                result=build_trace(paths,zone if zone in (\'18\',\'19\') else \'auto\',\n                    progress=lambda i,n,msg:self.events.put((\'progress\',(i,n,msg))),source_map=dict(self.zip_sources))\n                self.events.put((\'complete\',result))\n            except Exception as exc:self.events.put((\'error\',str(exc)))\n            finally:self.events.put((\'done\',None))\n        threading.Thread(target=runner,daemon=True).start()\n\n    def _poll(self):\n        try:\n            while True:\n                action,data=self.events.get_nowait()\n                if action==\'progress\':\n                    i,n,msg=data;self.progress[\'value\']=round(100*i/max(n,1));self.summary.set(msg);self._log(msg)\n                elif action==\'complete\':\n                    self.data=data;tot=data[\'totals\']\n                    self._refresh_files()\n                    self.metrics.configure(text=f"{tot[\'vertices\']} vértices · {tot[\'vanos_reconstruidos\']} vanos\\n{tot[\'tramos_continuos\']} trazados · {tot[\'alertas\']} alertas")\n                    self.summary.set(f"Listo: {tot[\'archivos_con_trazado\']}/{tot[\'archivos\']} LDE con trazado · {tot[\'vertices\']} vértices · {tot[\'vanos_reconstruidos\']} vanos.")\n                    self.save_btn.configure(state=\'normal\' if tot[\'vertices\'] else \'disabled\')\n                    if tot[\'vertices\'] and not self.save_btn.winfo_manager():self.save_btn.pack(fill=\'x\',pady=(7,0))\n                    self.toggle_files(False)\n                    self._draw()\n                    if self.esri is not None:self._refresh_esri()\n                    for f in data[\'files\']:\n                        self._log(f"{f[\'archivo\']} · {f[\'estado\']} · {f[\'vertices\']} vértices · {f[\'vanos\']} vanos")\n                        if f[\'estado\'] in (\'ERROR\',\'SIN_TRAZADO\'):self._log(\'  \'+f.get(\'detalle\',\'\'))\n                    if tot[\'alertas\']:\n                        self._log(f"ATENCIÓN: {tot[\'alertas\']} advertencias. GeoJSON conserva solo geometrías con coordenadas utilizables.")\n                    if tot[\'vertices\']==0:\n                        messagebox.showwarning(\'Sin trazado\',\'Ningún documento entregó coordenadas utilizables. Revisa el registro de actividad.\',parent=self)\n                elif action==\'error\':\n                    self.summary.set(\'No fue posible construir el trazado.\');self._log(\'ERROR: \'+data)\n                    messagebox.showerror(\'Error al interpretar LDE\',data,parent=self)\n                elif action==\'done\':self.busy=False;self.build_btn.configure(state=\'normal\')\n        except queue.Empty:pass\n        if self.winfo_exists():self.after(110,self._poll)\n\n    def _draw(self,preserve=False):\n        ax=self.ax\n        old=(ax.get_xlim(),ax.get_ylim()) if preserve and self.data else None\n        ax.clear();ax.set_facecolor(\'#F8FAFC\')\n        if not self.data or not self.data.get(\'points\'):\n            ax.text(.5,.53,\'Carga los LDE y pulsa «Construir trazado»\',ha=\'center\',va=\'center\',transform=ax.transAxes,color=\'#64748B\',fontsize=12)\n            ax.set_xticks([]);ax.set_yticks([])\n            self.canvas.draw_idle();return\n        palette=[\'#1D4ED8\',\'#0F766E\',\'#7C3AED\',\'#B45309\',\'#047857\',\'#DC2626\',\'#334155\']\n        for i,part in enumerate(self.data[\'paths\']):\n            xs=[p[0] for p in part[\'coords\']];ys=[p[1] for p in part[\'coords\']]\n            ax.plot(xs,ys,color=palette[i%len(palette)],linewidth=2.3,alpha=.9,\n                    solid_capstyle=\'round\',label=(part[\'archivo\'][:26] if i<10 else None),zorder=3)\n        for seg in self.data[\'spans\']:\n            if seg[\'estado\']==\'REVISAR_SALTO\':\n                ax.plot([seg[\'a\'][0],seg[\'b\'][0]],[seg[\'a\'][1],seg[\'b\'][1]],\n                        color=\'#DC2626\',linewidth=2.1,linestyle=\'--\',zorder=4)\n        if self.show_points.get():\n            ax.scatter([p[\'lon\'] for p in self.data[\'points\']],[p[\'lat\'] for p in self.data[\'points\']],\n                       s=12,c=\'#0F766E\',edgecolors=\'white\',linewidths=.3,zorder=7)\n        if self.show_labels.get():\n            # Only show at most 100 labels to avoid hiding the trace.\n            points=self.data[\'points\'];step=max(1,math.ceil(len(points)/100))\n            for p in points[::step]:ax.annotate(str(p[\'nombre\']),xy=(p[\'lon\'],p[\'lat\']),xytext=(3,3),textcoords=\'offset points\',fontsize=7,color=\'#334155\')\n        ax.set_title(f"Trazado documental · {len(self.data[\'points\'])} vértices",fontsize=11,color=\'#143452\')\n        ax.set_xlabel(\'Longitud (WGS84)\');ax.set_ylabel(\'Latitud (WGS84)\')\n        ax.tick_params(labelsize=8)\n        ax.grid(True,linestyle=\':\',alpha=.30)\n        ax.set_aspect(\'auto\')  # Panoramic line should not collapse into a thin strip.\n        ax.margins(x=.09,y=.13)\n        if old:\n            ax.set_xlim(*old[0]);ax.set_ylim(*old[1])\n        self.fig.tight_layout(pad=1.4)\n        self.canvas.draw_idle()\n\n    def _pick(self,event):\n        if not self.data or event.inaxes!=self.ax or event.x is None or event.y is None:return\n        nearest=None\n        for p in self.data[\'points\']:\n            x,y=self.ax.transData.transform((p[\'lon\'],p[\'lat\']))\n            d=math.hypot(x-event.x,y-event.y)\n            if nearest is None or d<nearest[0]:nearest=(d,p)\n        if nearest is None or nearest[0]>12:return\n        p=nearest[1]\n        details=f"Documento: {p[\'archivo\']}\\nSección BDIT: {p.get(\'seccion_bdit\') or \'No indicada\'}\\nEstructura: {p[\'nombre\']}\\nFila: {p.get(\'fila\')}\\nEste: {p.get(\'este\')}  Norte: {p.get(\'norte\')}\\nHuso: {p.get(\'huso\')}; Datum: {p.get(\'datum\')}\\nLat: {p[\'lat\']:.8f}; Lon: {p[\'lon\']:.8f}\\nObservaciones: {p.get(\'alerta\') or \'Sin observaciones\'}"\n        self._set_inspector(details)\n\n    def _wheel(self,event):\n        if event.inaxes!=self.ax or event.xdata is None or event.ydata is None:return\n        factor=.8 if event.button==\'up\' or getattr(event,\'step\',0)>0 else 1.25\n        x0,x1=self.ax.get_xlim();y0,y1=self.ax.get_ylim()\n        x,y=event.xdata,event.ydata\n        self.ax.set_xlim(x+(x0-x)*factor,x+(x1-x)*factor)\n        self.ax.set_ylim(y+(y0-y)*factor,y+(y1-y)*factor)\n        self.canvas.draw_idle()\n\n    def _set_inspector(self,details):\n        self.inspector.configure(state=\'normal\');self.inspector.delete(\'1.0\',\'end\')\n        self.inspector.insert(\'1.0\',details);self.inspector.configure(state=\'disabled\')\n\n    def _tab_changed(self,event=None):\n        if self.map_tabs.select()!=str(self.esri_frame):return\n        if self.esri is None:\n            try:\n                from tkintermapview import TkinterMapView\n                self.esri_msg.pack_forget()\n                self.esri=TkinterMapView(self.esri_frame,corner_radius=0)\n                self.esri.pack(fill=\'both\',expand=True)\n                self.esri.set_tile_server(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}\',max_zoom=19)\n            except Exception as exc:\n                self._log(\'Esri no disponible, el mapa de análisis sigue operativo: \'+str(exc))\n                self.esri_msg.configure(text=\'No se pudo iniciar Esri. Instala tkintermapview y verifica la conexión.\\n\'+str(exc))\n                return\n        self._refresh_esri()\n\n    def _refresh_esri(self):\n        w=self.esri\n        if w is None or not self.data:return\n        try:\n            for obj in self.esri_layers:\n                try:obj.delete()\n                except Exception:pass\n            self.esri_layers=[]\n            coords=[]\n            for part in self.data[\'paths\']:\n                xy=[(p[1],p[0]) for p in part[\'coords\']]\n                if len(xy)>=2:self.esri_layers.append(w.set_path(xy,color=\'#2563EB\',width=3))\n                coords.extend(xy)\n            # Markers stay sparse at overview to avoid covering the satellite image.\n            vertices=self.data[\'points\'];step=max(1,math.ceil(len(vertices)/90))\n            if self._esri_icon is None:\n                from PIL import Image,ImageDraw,ImageTk\n                image=Image.new(\'RGBA\',(14,14),(0,0,0,0))\n                brush=ImageDraw.Draw(image);brush.ellipse((3,3,11,11),fill=\'#0F766E\',outline=\'white\',width=1)\n                self._esri_icon=ImageTk.PhotoImage(image,master=w)\n            for p in vertices[::step]:\n                lat,lon=p[\'lat\'],p[\'lon\']\n                if not (-90<=lat<=90 and -180<=lon<=180):continue\n                marker=w.set_marker(lat,lon,text=\'\',icon=self._esri_icon,icon_anchor=\'center\',command=lambda m,p=p:self._set_inspector(\n                    f"{p[\'archivo\']}\\nEstructura: {p[\'nombre\']}\\nEste/Norte: {p.get(\'este\')} / {p.get(\'norte\')}\\nLat/Lon: {p[\'lat\']:.7f}, {p[\'lon\']:.7f}"))\n                self.esri_layers.append(marker)\n            if coords:\n                lats=[p[0] for p in coords];lons=[p[1] for p in coords]\n                w.fit_bounding_box((max(lats)+.005,min(lons)-.005),(min(lats)-.005,max(lons)+.005))\n            self._log(f\'Esri: {len(self.data["paths"])} trazados y marcadores reducidos para facilitar lectura.\')\n        except Exception as exc:\n            self._log(\'Error de Esri (no afecta el trazado): \'+str(exc))\n\n    def export(self):\n        if not self.data or not self.data[\'points\']:\n            messagebox.showinfo(\'Sin datos\',\'Primero construye el trazado.\',parent=self);return\n        first=self.paths[0].parent if self.paths else Path.cwd()\n        file=filedialog.asksaveasfilename(parent=self,title=\'Guardar trazado GeoJSON\',initialdir=str(first),\n              initialfile=\'Trazado_LDE.geojson\',defaultextension=\'.geojson\',filetypes=[(\'GeoJSON\',\'*.geojson\')])\n        if not file:return\n        try:\n            geo,csvfile=save_trace(self.data,file)\n            self._log(f\'GeoJSON: {geo}\')\n            self._log(f\'Control CSV: {csvfile}\')\n            messagebox.showinfo(\'Trazado guardado\',f\'Se guardaron:\\n{geo.name}\\n{csvfile.name}\\n\\nCarpeta: {geo.parent}\',parent=self)\n        except Exception as exc:messagebox.showerror(\'No se pudo guardar\',str(exc),parent=self)\n')]
# Punto de entrada del aplicativo (los módulos anteriores se registran en memoria).
if __name__ == "__main__":
    try:
        launch()
    except Exception:
        detail = traceback.format_exc()
        log_path = BASE / "ERROR_INICIO_APLICATIVO.log"
        try:
            log_path.write_text(detail, encoding="utf-8")
        except OSError:
            pass
        print(detail, file=sys.stderr)
        try:
            error_root = tk.Tk()
            error_root.withdraw()
            messagebox.showerror("Error al iniciar GeoLínea Tx",
                "No se pudo abrir el aplicativo.\n\n" + detail[-2300:] +
                "\n\nRegistro: " + str(log_path), parent=error_root)
            error_root.destroy()
        except Exception:
            pass
        sys.exit(1)
